insert into public.companies (slug, doc) values ('blue-origin', '{"slug":"blue-origin","name_he":"בלו אוריג''ין","name_en":"Blue Origin","tagline_he":"צעד אחר צעד, בנחישות: מקצה האטמוספרה ועד הקוטב הדרומי של הירח","description_he":"Blue Origin היא חברת החלל שהקים מייסד Amazon, Jeff Bezos, בשנת 2000 בעיירה קנט שליד סיאטל, מתוך חזון ארוך טווח: מיליוני בני אדם שחיים ועובדים בחלל. במשך שנים התנהלה החברה בשקט ובחשאיות תחת המוטו הלטיני Gradatim Ferociter, צעד אחר צעד, בעוז, ומומנה כמעט כולה מכיסו של Bezos. כיום היא מעסיקה בערך 12,000 עובדים ובונה בעצמה כמעט הכול: רקטות, מנועים, נחתות ירח ואפילו תחנת חלל.\n\nספינת הדגל של החברה היא רקטת New Glenn, ענקית בגובה 98 מטרים שנושאת בערך 45 טונות למסלול נמוך סביב כדור הארץ. הדרגה הראשונה שלה נבנתה לשימוש חוזר: במקום להיזרק לים אחרי כל שיגור, היא חוזרת ונוחתת על ספינה באוקיינוס, בדומה למטוס נוסעים שנוחת, מתודלק וממריא שוב. מאז ינואר 2025 טסה New Glenn שלוש פעמים: בטיסה הראשונה הגיעה למסלול כבר בניסיון הראשון, בשנייה שיגרה זוג חלליות של NASA למאדים והנחיתה לראשונה את הבוסטר בים, ובשלישית ביצעה שימוש חוזר ראשון באותו בוסטר. במאי 2026 התפוצצה רקטה שלמה במבחן מנועים בכן השיגור בפלורידה, והחברה עובדת כעת על חזרה לטיסה לפני סוף 2026.\n\nבשנת 2026 עברה Blue Origin מיקוד דרמטי לעבר הירח: טיסות התיירות של New Shepard הושהו אחרי 38 טיסות, נחתת המטען Blue Moon MK1 סיימה את מבחני הקרקע של NASA לקראת נחיתה ראשונה ליד הקוטב הדרומי של הירח, והנחתת המאוישת Blue Moon MK2 מתחרה מול Starship של SpaceX על הנחתת האסטרונאוטים הבאה בתוכנית Artemis. במקביל מוכרת החברה את מנועי BE-4 שלה לרקטת Vulcan של United Launch Alliance, ומפתחת יחד עם Sierra Space את תחנת החלל המסחרית Orbital Reef. אחרי שנים בצילה של SpaceX, היא כיום היריבה המשמעותית ביותר שלה.","color":"#005DAA","founded":"2000","hq_he":"קנט, וושינגטון, ארצות הברית","ll2_id":141,"stats":[{"label_he":"שיגורי New Glenn עד היום","value":"3","sub_he":"שתי נחיתות מוצלחות של הדרגה הראשונה בים, ושימוש חוזר אחד בבוסטר"},{"label_he":"כושר נשיאה למסלול נמוך","value":"45 טונות","sub_he":"הגרסה העתידית New Glenn 9x4 מתוכננת לשאת מעל 70 טונות"},{"label_he":"טיסות New Shepard לקצה החלל","value":"38","sub_he":"מעל 90 בני אדם חצו את קו קרמן, התוכנית מושהית מאז ינואר 2026"},{"label_he":"דחף של מנוע BE-4 אחד","value":"2,400 קילוניוטון","sub_he":"שבעה מנועים מניעים את New Glenn, ושניים את רקטת Vulcan של ULA"}],"timeline":[{"date":"2026-06","tag_he":"הכרזה","title_he":"התחייבות לחזרה לטיסה עד סוף 2026","text_he":"ימים ספורים אחרי הפיצוץ בכן השיגור פרסם המנכ\"ל Dave Limp תוכנית חזרה לטיסה. חוות הדלק, מגדל המים ומתקני תשתית מרכזיים שרדו את הפיצוץ, והחברה החליטה לדלג על שיקום מלא של המערך הישן ולעבור ישירות לתפיסת הפעלה חדשה שפותחה במקור עבור הדור הבא של הרקטה. היעד המוצהר: New Glenn תטוס שוב לפני סוף 2026."},{"date":"2026-05","tag_he":"כישלון","title_he":"רקטת New Glenn מתפוצצת במבחן מנועים בכן השיגור","text_he":"ב28 במאי 2026, במהלך הצתת ניסוי סטטית של שבעת מנועי BE-4 לקראת הטיסה הרביעית, התפוצצה רקטת New Glenn שלמה בכן השיגור LC-36 בקייפ קנוורל. הדרגה הראשונה החדשה נהרסה כליל והתשתית ניזוקה, אך איש לא נפגע. ממצאי החקירה הצביעו על שסתום חמצן ראשי באחד המנועים כמקור התקלה. זהו האתר היחיד שממנו New Glenn ממריאה, ולכן הפיצוץ עצר את כל לוח השיגורים של החברה."},{"date":"2026-05","tag_he":"אבן דרך","title_he":"נחתת הירח Blue Moon MK1 עוברת את מבחני הוואקום של NASA","text_he":"הנחתת הראשונה מדגם MK1, שקיבלה את השם Endurance, סיימה בהצלחה סדרת מבחנים בתא הוואקום הענק Chamber A במרכז החלל Johnson ביוסטון, אותו תא שבו נבדקו חלליות Apollo. המבחנים דימו את תנאי הריק ואת הטמפרטורות הקיצוניות של הדרך לירח ושל השהייה על פניו. הנחתת נועדה להביא בערך 3 טונות מטען אל אזור הקוטב הדרומי של הירח, ליד מכתש Shackleton, בדיוק נחיתה של עד 100 מטרים מהמטרה."},{"date":"2026-04","tag_he":"שיגור","title_he":"טיסה שלישית: שימוש חוזר ראשון בבוסטר, אך הלוויין הגיע למסלול שגוי","text_he":"בטיסה NG-3 ב19 באפריל 2026 עשתה Blue Origin היסטוריה כשהטיסה שוב את הדרגה הראשונה שנחתה בטיסה הקודמת, והיא אף נחתה בהצלחה פעם שנייה על הספינה בים. אלא שבדרגה השנייה אירעה תקלת דחף באחד ממנועי BE-3U, והלוויין BlueBird 7 של AST SpaceMobile שוחרר למסלול נמוך מהמתוכנן. החקירה מצאה דליפה קריוגנית שהקפיאה קו הידראולי, ומנהל התעופה הפדרלי האמריקאי קרקע זמנית את הרקטה."},{"date":"2026-02","tag_he":"חוזה","title_he":"NASA משנה את תוכנית Artemis ופותחת דלת לנחתת של Blue Origin","text_he":"אחרי שבאוקטובר 2025 פתחה NASA מחדש את התחרות על הנחיתה המאוישת הראשונה על הירח מאז Apollo, בפברואר 2026 הוכרז מבנה חדש לתוכנית: משימת Artemis III תהפוך למבחן מפגש ועגינה במסלול סביב כדור הארץ עם נחתות של SpaceX ושל Blue Origin, והנחיתה המאוישת עצמה נדחתה למשימת Artemis IV בשנת 2028. במקביל הגיע דגם בגודל מלא של הנחתת המאוישת Blue Moon MK2 למרכז Johnson, ואסטרונאוטים של NASA כבר מתאמנים עליו."},{"date":"2026-01","tag_he":"הכרזה","title_he":"טיסה 38 של New Shepard, ואז השהיה: כל הכוח לירח","text_he":"ב22 בינואר 2026 השלימה New Shepard את טיסתה ה38 עם שישה נוסעים, ובסוף אותו חודש הודיעה החברה על השהיית טיסות התיירות התת מסלוליות. הסיבה: ריכוז כוח האדם והמשאבים בפיתוח נחתות הירח עבור תוכנית Artemis. עד אז הפכה הטיסה לקצה החלל לשגרה של ממש, עם מעל 90 בני אדם שחצו את קו קרמן בגובה 100 ק\"מ."},{"date":"2025-12","tag_he":"הכרזה","title_he":"חשיפת New Glenn 9x4: גרסת ענק מול Starship של SpaceX","text_he":"אחרי הצלחת הטיסה השנייה חשפה Blue Origin שדרוג כפול: מנועים חזקים יותר לרקטה הנוכחית, ותוכנית לגרסת ענק בשם New Glenn 9x4 עם תשעה מנועי BE-4 בדרגה הראשונה וארבעה מנועי BE-3U בדרגה השנייה. הגרסה החדשה מתוכננת לשאת מעל 70 טונות למסלול נמוך ומעל 20 טונות לעבר הירח, עם כיפת מטען ברוחב 8.7 מטרים. זו הצהרת כוונות ברורה: תחרות ישירה ברקטות העל הכבדות של SpaceX."},{"date":"2025-11","tag_he":"שיגור","title_he":"ESCAPADE בדרך למאדים, והבוסטר נוחת לראשונה על ספינה בים","text_he":"בטיסה השנייה, ב13 בנובמבר 2025, שיגרה New Glenn את זוג החלליות ESCAPADE של NASA למסע אל מאדים, שם יחקרו כיצד רוח השמש מקלפת את האטמוספרה של הכוכב. הדרגה הראשונה, שנקראה Never Tell Me The Odds, נחתה בהצלחה על הספינה האוטונומית Jacklyn באוקיינוס האטלנטי. בכך הפכה Blue Origin לחברה השנייה בהיסטוריה, אחרי SpaceX, שמנחיתה בוסטר של רקטה מסלולית על ספינה בים."},{"date":"2025-04","tag_he":"היסטוריה","title_he":"צוות נשי מלא בחלל: טיסת NS-31 עם Katy Perry","text_he":"ב14 באפריל 2025 המריאה New Shepard עם שש נשים, בהן הזמרת Katy Perry, העיתונאית Gayle King והטייסת Lauren Sanchez. זה היה הצוות הנשי המלא הראשון בחלל מאז טיסת היחיד של Valentina Tereshkova בשנת 1963. הטיסה משכה תשומת לב עולמית עצומה, לצד לא מעט ביקורת, והמחישה את מעמדה של Blue Origin בתיירות החלל."},{"date":"2025-02","tag_he":"ארגון","title_he":"קיצוץ של כמעט 1,400 משרות ומעבר ממחקר לייצור","text_he":"חודש אחרי טיסת הבכורה המוצלחת של New Glenn הודיע המנכ\"ל Dave Limp על פיטורים של בערך עשרה אחוזים מהעובדים, כמעט 1,400 איש מתוך כמעט 14,000. ההסבר: החברה גדלה מהר מדי וצברה בירוקרטיה שפגעה במיקוד. המהלך סימן שינוי אסטרטגי, פחות מחקר ופיתוח איטי ויותר ייצור סדרתי של רקטות ומנועים."},{"date":"2025-01","tag_he":"שיגור","title_he":"טיסת בכורה: New Glenn מגיעה למסלול כבר בניסיון הראשון","text_he":"ב16 בינואר 2025, אחרי בערך עשור של פיתוח, המריאה New Glenn לראשונה מקייפ קנוורל והגיעה למסלול סביב כדור הארץ כבר בניסיון הראשון, הישג נדיר לרקטה חדשה. על סיפונה טס אב הטיפוס Blue Ring Pathfinder, פלטפורמת הלוגיסטיקה החללית של החברה. ניסיון הנחיתה של הדרגה הראשונה על הספינה בים נכשל, אך המשימה העיקרית הוגדרה הצלחה מלאה."},{"date":"2021-07","tag_he":"היסטוריה","title_he":"הטיסה המאוישת הראשונה: Jeff Bezos טס לחלל","text_he":"ב20 ביולי 2021, בדיוק 52 שנה אחרי נחיתת Apollo 11 על הירח, טסו Jeff Bezos, אחיו Mark, חלוצת התעופה בת ה82 Wally Funk והסטודנט ההולנדי בן ה18 Oliver Daemen בטיסה המאוישת הראשונה של New Shepard. הקפסולה חצתה את קו קרמן בגובה 100 ק\"מ וחזרה לנחיתה רכה במצנחים במדבר טקסס. כך נפתח עידן התיירות התת מסלולית של החברה."},{"date":"2015-11","tag_he":"היסטוריה","title_he":"הרקטה הראשונה בהיסטוריה שחוצה את גבול החלל ונוחתת בחזרה","text_he":"ב23 בנובמבר 2015 שוגרה New Shepard לגובה של מעל 100 ק\"מ, ואז חזר הבוסטר ונחת נחיתה אנכית מדויקת באתר השיגור בטקסס. זו הייתה הפעם הראשונה שרקטה חצתה את גבול החלל ונחתה שלמה, חודש לפני הנחיתה הראשונה של SpaceX עם Falcon 9. הרעיון שרקטה היא כלי רב פעמי, כמו מטוס נוסעים ולא כמו גפרור חד פעמי, הפך באותו רגע ממדע בדיוני למציאות."},{"date":"2000-09","tag_he":"היסטוריה","title_he":"Jeff Bezos מקים חברת חלל בשקט מוחלט","text_he":"מייסד Amazon הקים את Blue Origin בספטמבר 2000 בעיירה קנט שליד סיאטל, שנתיים לפני הקמת SpaceX. במשך שנים פעלה החברה בחשאיות כמעט מוחלטת תחת המוטו הלטיני Gradatim Ferociter, שפירושו צעד אחר צעד, בעוז. Bezos מימן אותה ממכירת מניות Amazon, לעיתים בהיקף של מיליארד דולר בשנה."}],"programs":[{"name":"New Glenn","desc_he":"רקטה כבדה בגובה 98 מטרים עם דרגה ראשונה רב פעמית שנוחתת על ספינה בים, ומסוגלת לשאת בערך 45 טונות למסלול נמוך. טסה שלוש פעמים מאז ינואר 2025, והיא מקורקעת כרגע אחרי פיצוץ במבחן מנועים במאי 2026.","status_he":"מושהית, חזרה לטיסה מתוכננת עד סוף 2026"},{"name":"New Glenn 9x4","desc_he":"גרסת על כבדה מתוכננת של New Glenn עם תשעה מנועי BE-4 וכיפת מטען ברוחב 8.7 מטרים, שתישא מעל 70 טונות למסלול נמוך ומעל 20 טונות לעבר הירח. נחשפה בסוף 2025 כתשובה של Blue Origin לרקטת Starship של SpaceX.","status_he":"בפיתוח"},{"name":"Blue Moon MK1","desc_he":"נחתת ירח רובוטית לא מאוישת שנועדה להביא בערך 3 טונות מטען אל פני הירח בעזרת מנוע המימן BE-7. הנחתת הראשונה, Endurance, סיימה מבחני ואקום תרמי במרכז Johnson של NASA במאי 2026, והיא מיועדת לנחות ליד הקוטב הדרומי של הירח.","status_he":"לקראת משימה ראשונה, סוף 2026 עד תחילת 2027"},{"name":"Blue Moon MK2","desc_he":"נחתת מאוישת גדולה שנבחרה על ידי NASA להנחתת אסטרונאוטים על הירח במסגרת תוכנית Artemis. דגם בגודל מלא כבר משמש לאימוני אסטרונאוטים ביוסטון, והיא מתחרה מול Starship של SpaceX על משימות הנחיתה הקרובות.","status_he":"בפיתוח, בתחרות על משימות Artemis"},{"name":"BE-4","desc_he":"מנוע רקטה מתקדם שצורך גז טבעי נוזלי וחמצן נוזלי ומפיק בערך 2,400 קילוניוטון דחף. מלבד New Glenn הוא מניע גם את רקטת Vulcan של United Launch Alliance, וקצב הייצור במפעל בהאנטסוויל הגיע לבערך מנוע אחד בשבוע.","status_he":"בייצור סדרתי"},{"name":"New Shepard","desc_he":"רקטה תת מסלולית רב פעמית לטיסות תיירות ומחקר של בערך 11 דקות אל מעבר לקו קרמן בגובה 100 ק\"מ. השלימה 38 טיסות והטיסה מעל 90 בני אדם, אך הטיסות הושהו בינואר 2026 כדי למקד את החברה בתוכנית הירח.","status_he":"מושהית מאז ינואר 2026"},{"name":"Orbital Reef","desc_he":"תחנת חלל מסחרית שמפותחת יחד עם Sierra Space, מעין פארק עסקים במסלול עם נפח מחיה של 830 מטרים מעוקבים לצוות של עד עשרה אנשים. עברה סקר תכן מערכתי של NASA ביולי 2025 והשלימה מבחנים למערכות תמך החיים בשנת 2026.","status_he":"בפיתוח"},{"name":"Blue Ring","desc_he":"פלטפורמת לוגיסטיקה חללית שנועדה להוביל מטענים בין מסלולים ולספק להם חשמל, תקשורת והנעה, בדומה למשאית שירות בחלל. אב טיפוס ראשון טס בהצלחה בטיסת הבכורה של New Glenn בינואר 2025.","status_he":"בפיתוח, אב טיפוס ראשון טס"}],"news_query":"Blue Origin","vehicles":["new-glenn","vulcan"]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.companies (slug, doc) values ('israel-space', '{"slug":"israel-space","name_he":"תעשיית החלל הישראלית","name_en":"Israel Space Sector","tagline_he":"מהשרטוט ועד המסלול, הכול כחול לבן","description_he":"ישראל היא אחת המדינות הבודדות בעולם שמחזיקות בשרשרת חלל מלאה: תכנון לוויינים, בנייתם ושיגורם במשגר מתוצרת בית. בלב התעשייה עומדת התעשייה האווירית לישראל (IAI), שבונה את לווייני הביון מסדרת Ofek, את לוויין התקשורת הלאומי Dror 1 ואת משגר Shavit, לצד סוכנות החלל הישראלית שמתאמת את הפעילות האזרחית. סביבן פועלות Rafael, שמערכות ההנעה שלה מותקנות ביותר ממאה לוויינים ברחבי העולם, Elbit עם מערכות אופטיות מתקדמות, וחברת Spacecom שמפעילה את לווייני התקשורת מסדרת Amos.\n\nלישראל אילוץ גאוגרפי ייחודי: היא משגרת מערבה מעל הים התיכון, נגד כיוון סיבוב כדור הארץ, כדי שלא לטוס מעל מדינות שכנות. זה כמו לשחות נגד הזרם: כל קילוגרם למסלול דורש יותר אנרגיה, ולכן המהנדסים הישראלים התמחו בלוויינים קטנים, קלים וחכמים במיוחד. ההתמחות הזאת הוכיחה את עצמה שוב בשנים האחרונות: ביולי 2025 שוגר Dror 1, לוויין תקשורת במשקל 4.5 טונות שנבנה כולו בישראל והגיע למסלול בגובה 36,000 ק\"מ, ובספטמבר 2025 עלה למסלול לוויין המכ\"ם Ofek 19, לפי פרסומים בשיגור האחרון של Shavit בתצורתו הנוכחית, לפני שייכנס לשירות משגר גדול ממנו.\n\nלצד הענקיות הביטחוניות צומחת סצנת New Space של כמעט 90 חברות: מטרמינלי התקשורת של hiSky ולווייני האנטנות הנפרשות של BeetleSat ועד ניתוח נתוני חלל. דוח מתחילת 2026 מתאר תעשייה שעוברת ממכירת חומרה ביטחונית לשירותים אזרחיים וגלובליים, והמדינה משקיעה בתשתית חדשה כמו מעבדת Access to Space במצפה רמון. לצד זה נותרו אתגרים: משימת הירח Beresheet 2 קפואה מחוסר מימון, וטלסקופ החלל ULTRASAT, פרויקט משותף עם NASA, מתוכנן לשיגור רק בסוף 2027.","color":"#0038b8","founded":"1983","hq_he":"תל אביב, ישראל","ll2_id":95,"news_query":"Israel","stats":[{"label_he":"חברות חלל פעילות בישראל","value":"90","sub_he":"לפי דוח Startup Nation Central שפורסם בתחילת 2026"},{"label_he":"משקל Dror 1","value":"4.5 טונות","sub_he":"לוויין התקשורת הכבד והמתקדם ביותר שנבנה אי פעם בישראל, שוגר ביולי 2025"},{"label_he":"גובה המסלול של Dror 1","value":"36,000 ק\"מ","sub_he":"מסלול גאוסטציונרי, גבוה בערך פי 90 מתחנת החלל הבינלאומית"},{"label_he":"השנה שבה ישראל הפכה עצמאית בחלל","value":"1988","sub_he":"המדינה השמינית בעולם ששיגרה לוויין במשגר מתוצרתה"}],"timeline":[{"date":"2026-01","title_he":"דוח המצב 2026: מביטחון לשירותים גלובליים","tag_he":"תעשייה","text_he":"דוח State of the Israeli Space Industry 2026 של Startup Nation Central מיפה כמעט 90 חברות חלל ישראליות פעילות. הדוח מתאר תעשייה שעוברת ממוצרים ביטחוניים לשירותים אזרחיים: תקשורת, תצפית על כדור הארץ וניתוח נתונים. כמעט מחצית מהחברות בונות לוויינים, משגרים ורכיבים, וכשליש כבר עוסקות בשירותים שנשענים על לוויינים קיימים. בין 2020 עד 2023 צמח התחום בכשני שלישים, קצב כמעט פי שלושה מכלל ההייטק הישראלי."},{"date":"2025-12","title_he":"מעבדת Access to Space: כרטיס מסובסד לחלל","tag_he":"תשתית","text_he":"סוכנות החלל הישראלית ורשות החדשנות בחרו בחברת Creation Space להקים במצפה רמון מעבדת מחקר ופיתוח לאומית בתקציב של 60 מיליון שקל, מתוכם 40 מיליון במענקי ממשלה. המעבדה מסבסדת לסטארטאפים ולמוסדות מחקר שירותי שיגור, בדיקות והפעלה במסלול בהנחה של יותר משליש מהמחיר, במטרה להטיס לפחות 15 מטענים ניסיוניים בתוך שלוש שנים. הרעיון פשוט: להוריד את מחיר הכניסה לחלל, כמו כרטיסייה מסובסדת לתחבורה ציבורית."},{"date":"2025-09","title_he":"Ofek 19 במסלול: עין רדאר שרואה בכל מזג אוויר","tag_he":"ביטחון","text_he":"בליל 2 בספטמבר 2025 שוגר לוויין הביון Ofek 19 במשגר Shavit מבסיס פלמחים, והחל לשדר נתונים זמן קצר אחרי הכניסה למסלול. זהו לוויין מכ\"ם מסוג SAR: במקום מצלמה רגילה הוא שולח גלי רדיו וקולט את ההחזרים, ולכן הוא רואה גם בלילה, מבעד לעננים ובגשם. לפי פרסומים ייתכן שזה השיגור האחרון של Shavit בתצורתו הנוכחית: בישראל מפתחים משגר גדול יותר, שיוכל לשאת לוויינים במשקל כמעט כפול."},{"date":"2025-08","title_he":"hiSky חוברת אל Kratos האמריקאית","tag_he":"New Space","text_he":"חברת hiSky הישראלית, שמפתחת טרמינלי לוויין שטוחים ממשפחת Smartellite, חתמה על שיתוף פעולה עם Kratos, ענקית מערכות הקרקע האמריקאית. השילוב מאפשר להפעיל רשתות לווייניות של אינטרנט של הדברים (IoT) כשירות ענן מנוהל: חיישנים בשדות, בצינורות ובמכרות שמדווחים ישירות דרך הלוויין, בלי תשתית סלולרית בסביבה."},{"date":"2025-07","title_he":"Dror 1 ממריא: לוויין התקשורת הלאומי","tag_he":"תקשורת","text_he":"ביולי 2025 שוגר Dror 1 על משגר Falcon 9 של SpaceX מקייפ קנוורל שבפלורידה. הלוויין, במשקל 4.5 טונות ובמוטה של 17.8 מטרים עם הפאנלים הסולאריים פרוסים, טיפס לגובה 36,000 ק\"מ, שם הוא מרחף מעל נקודה קבועה על קו המשווה. IAI מכנה אותו \"סמארטפון בחלל\": מטען תקשורת דיגיטלי שאפשר לעדכן בתוכנה לאורך 15 שנות שירות מתוכננות. זהו הראשון בסדרה מתוכננת של כעשרה לווייני Dror שיבטיחו לישראל עצמאות בתקשורת לוויינית."},{"date":"2025-03","title_he":"Beresheet 2 נכנסת להקפאה","tag_he":"ירח","text_he":"עמותת SpaceIL לא הצליחה לגייס את התקציב הדרוש עד המועד האחרון שנקבע במרץ 2025, והשעתה את הפיתוח ההנדסי של משימת הירח Beresheet 2. סביב 25 עובדים ויועצים עזבו את הפרויקט, וההסכמים עם ספקים מרכזיים הוקפאו. בעמותה מדגישים שהמשימה קפואה אך לא בוטלה, והחיפוש אחר מימון ושותפויות בינלאומיות נמשך."},{"date":"2025-01","title_he":"איטליה מושיטה יד למשימת הירח","tag_he":"שיתוף פעולה","text_he":"בכנס החלל הבינלאומי על שם אילן רמון בתל אביב חתמו סוכנות החלל הישראלית וסוכנות החלל האיטלקית על מכתב כוונות לשיתוף פעולה במשימת Beresheet 2. אחת ההצעות שנבחנו: להחליף אחת מנחתות המשימה בלוויינים מדעיים קטנים מתוצרת איטליה. הסכם מחייב טרם נחתם, אך זהו סימן חיים חשוב למשימה שנאבקת על מימון."},{"date":"2024-02","title_he":"אנטנה שטוחה שמדברת עם לוויין בנסיעה","tag_he":"New Space","text_he":"hiSky חשפה את דור הטרמינלים Smartellite Dynamic עם אנטנה אלקטרונית של 16 על 16 יסודות קרינה, שמיועד לתקשורת לוויינית תוך כדי תנועה: משאיות, ספינות וציוד חקלאי. במקביל השלימה החברה אישורים רגולטוריים בארצות הברית למשפחת הטרמינלים הקומפקטיים שלה, וכל הטרמינלים שיוצרו עד אמצע 2024 נמכרו מראש לשותפים."},{"date":"2023-10","title_he":"עסקת ייצוא: שני לוויינים לאזרבייג''ן","tag_he":"ייצוא","text_he":"IAI חתמה עם סוכנות החלל של אזרבייג''ן על עסקה בשווי 120 מיליון דולר לאספקת שני לווייני תצפית אלקטרואופטיים מדגם OptSat 500, ברזולוציה חדה מחצי מטר: מספיק כדי להבחין ברכב בודד מהחלל. השיגורים מתוכננים לשנת 2026 ולשנת 2028, והעסקה כוללת גם העברת ידע והקמת מערך חלל מקומי באזרבייג''ן."},{"date":"2022-04","title_he":"רקיע: איתן סטיבה בתחנת החלל","tag_he":"מאוישים","text_he":"איתן סטיבה הפך לישראלי השני בחלל כשהצטרף אל Axiom Mission 1, המשימה הפרטית הראשונה לתחנת החלל הבינלאומית, שהמריאה בחללית Dragon של SpaceX. במסגרת משימת \"רקיע\" הוא הפעיל בתחנה עשרות ניסויים של חוקרים, חברות וסטודנטים ישראלים, מרפואה ועד אופטיקה."},{"date":"2019-04","title_he":"בראשית כמעט נוגעת בירח","tag_he":"ירח","text_he":"החללית בראשית של SpaceIL ושל IAI, שנבנתה בתקציב של כמאה מיליון דולר בלבד, הגיעה למסלול סביב הירח: הישג שרשמו לפניה שש מדינות בלבד. באפריל 2019, במהלך ירידת הנחיתה, כשל המנוע הראשי והחללית התרסקה על פני הירח. למרות הסיום המר, המשימה הציבה את ישראל על מפת חקר הירח והציתה דור חדש של יזמות חלל."},{"date":"2003-01","title_he":"אילן רמון, הישראלי הראשון בחלל","tag_he":"מאוישים","text_he":"אל\"ם אילן רמון המריא בינואר 2003 במעבורת Columbia במשימה בת 16 יממות, ובה הפעיל ניסויים ישראליים, בהם מצלמה לחקר אבק מדברי. בתום המשימה, בפברואר 2003, התפרקה המעבורת בכניסה לאטמוספירה וכל שבעת אנשי הצוות נספו. מורשתו מלווה את תוכנית החלל הישראלית עד היום, וכנס החלל השנתי בתל אביב נושא את שמו."},{"date":"1988-09","title_he":"Ofeq 1: הצטרפות למועדון החלל","tag_he":"אבן דרך","text_he":"בספטמבר 1988 שיגרה ישראל את Ofeq 1 במשגר Shavit מבסיס פלמחים, והפכה למדינה השמינית בעולם ששיגרה לוויין במשגר מתוצרתה. משיקולי בטיחות ומדיניות ישראל משגרת מערבה מעל הים התיכון, נגד כיוון סיבוב כדור הארץ: כמו ריצה נגד כיוון של מסוע נע, זה דורש יותר אנרגיה על כל קילוגרם, ולכן הלוויינים הישראליים תוכננו מאז ומתמיד להיות קלים וחכמים במיוחד."}],"programs":[{"name":"Ofek","desc_he":"סדרת לווייני הביון של משרד הביטחון, שנבנית בידי IAI ומשוגרת במשגר Shavit מבסיס פלמחים. הסדרה כוללת לווייני צילום אופטיים ולווייני מכ\"ם, והאחרון בהם, Ofek 19, שוגר בספטמבר 2025.","status_he":"פעיל"},{"name":"Shavit","desc_he":"משגר בעל שלושה שלבים המבוסס על מנועי דלק מוצק, היחיד בעולם שמשגר בקביעות מערבה, נגד כיוון סיבוב כדור הארץ. לפי פרסומים מפותח לו יורש גדול יותר, שיוכל לשאת לוויינים במשקל כמעט כפול.","status_he":"מבצעי, יורש בפיתוח"},{"name":"Dror","desc_he":"דור לווייני התקשורת הלאומיים של ישראל בבנייה מקומית של IAI. Dror 1 שוגר ביולי 2025 ופועל במסלול גאוסטציונרי, והמדינה מתכננת סדרה של כעשרה לוויינים לעשורים הקרובים.","status_he":"Dror 1 פעיל במסלול"},{"name":"Amos","desc_he":"צי לווייני התקשורת המסחריים של חברת Spacecom הישראלית, שמספק שידורי טלוויזיה ותקשורת לישראל, לאירופה ולאפריקה. חלק מהלוויינים נבנו בידי IAI וחלק נרכשו מיצרנים זרים.","status_he":"פעיל"},{"name":"Beresheet 2","desc_he":"משימת ההמשך של SpaceIL לנחיתה על הירח, שתוכננה לכלול חללית אם ושתי נחתות. הפיתוח הוקפא במרץ 2025 בשל קשיי מימון, ונבחנת שותפות עם סוכנות החלל האיטלקית.","status_he":"מוקפא"},{"name":"ULTRASAT","desc_he":"טלסקופ חלל אולטרה סגול של מכון ויצמן וסוכנות החלל הישראלית בשיתוף NASA וגרמניה, עם שדה ראייה רחב במיוחד של 204 מעלות רבועות. ישוגר למסלול גאוסטציונרי ויצוד אירועים קוסמיים מהירים, כמו התמזגות כוכבי נייטרונים.","status_he":"בפיתוח, שיגור מתוכנן לסוף 2027"},{"name":"Rafael Space Propulsion","desc_he":"מערכות הנעה ללוויינים מבית Rafael: מנועי הידרזין כימיים, מנועי הול חשמליים ומכלי דלק. נכון לשנת 2026 טכנולוגיה של Rafael פועלת ביותר ממאה לוויינים ברחבי העולם.","status_he":"פעיל"},{"name":"BeetleSat & hiSky","desc_he":"BeetleSat, לשעבר NSLComm, מפתחת לוויינים קטנים עם אנטנות נפרשות שנפתחות רק בחלל, ומתכננת מערך לוויינים לתקשורת מאובטחת. hiSky מפתחת טרמינלים שטוחים ורשת ניהול לתקשורת לוויינית ולאינטרנט של הדברים.","status_he":"פעיל"}],"vehicles":["shavit","falcon-9"]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.companies (slug, doc) values ('nasa', '{"slug":"nasa","name_he":"נאס\"א","name_en":"NASA","tagline_he":"חוזרים לירח, הפעם כדי להישאר","description_he":"נאס\"א היא סוכנות החלל האזרחית של ארצות הברית, והשחקן הגדול והמשפיע ביותר בתעשיית החלל העולמית. היא נוסדה בשנת 1958 בעיצומו של המרוץ לחלל מול ברית המועצות, והובילה מאז את נחיתות Apollo על הירח, את מעבורות החלל, את טלסקופ החלל Hubble ואת תחנת החלל הבינלאומית. התקציב שלה לשנת 2026 עומד על כ 24.4 מיליארד דולר, גדול יותר מתקציבי כל סוכנויות החלל האחרות בעולם יחד, והיא מפעילה מרכזי פיתוח, שיגור ומחקר בכל רחבי ארצות הברית.\n\nהעשור הנוכחי שייך לתוכנית Artemis, המסע לחזרה מאוישת אל הירח. באפריל 2026 השלימה משימת Artemis II הקפה מאוישת של הירח, הטיסה הראשונה של בני אדם אל סביבת הירח מאז 1972, שקבעה שיא מרחק אנושי של כ 407,000 ק\"מ מכדור הארץ. במקביל עברה הסוכנות טלטלה ניהולית: המנהל החדש ג''ארד אייזקמן ביטל את שדרוגי הענק של רקטת SLS, הפך את משימת Artemis III לתרגיל עגינה במסלול סביב כדור הארץ בשנת 2027, ודחה את הנחיתה עצמה למשימת Artemis IV, עם יעד בשנת 2028.\n\nהדרך הפשוטה להבין את נאס\"א של היום היא לדמיין חברת תעופה שהפסיקה לייצר מטוסים בעצמה ועברה לקנות כרטיסים: במקום לבנות ולהחזיק כל חללית, הסוכנות קונה שירותים מחברות פרטיות כמו SpaceX, Blue Origin ואחרות, ושומרת לעצמה את קביעת היעדים, הבטיחות והמדע. המודל הזה יגיע לשיאו סביב שנת 2030, כשתחנת החלל הבינלאומית תוצא ממסלול ותוחלף בתחנות מסחריות פרטיות שנאס\"א תהיה הלקוחה העוגנת שלהן, בזמן שהסוכנות עצמה מפנה את משאביה אל הירח, אל מאדים ואל מדע החלל העמוק.","color":"#0B3D91","founded":"1958","hq_he":"וושינגטון הבירה, ארצות הברית","ll2_id":44,"news_query":"NASA","stats":[{"label_he":"תקציב שנתי","value":"24.4 מיליארד דולר","sub_he":"התקציב שאישר הקונגרס לשנת 2026, אחרי שדחה הצעה לקצץ רבע ממנו"},{"label_he":"שיא המרחק האנושי מכדור הארץ","value":"407,000 ק\"מ","sub_he":"נקבע בטיסת Artemis II סביב הירח באפריל 2026"},{"label_he":"נחיתות מאוישות על הירח","value":"6","sub_he":"כולן בתוכנית Apollo, והבאה מתוכננת למשימת Artemis IV בשנת 2028"},{"label_he":"שנות נוכחות אנושית רצופה בחלל","value":"26","sub_he":"בתחנת החלל הבינלאומית, שמתוכננת לפרוש סביב שנת 2030"}],"timeline":[{"date":"2026-09","title_he":"עדכון דרישות חליפת הירח AxEMU","text_he":"נאס\"א עדכנה את דרישות חליפת הירח AxEMU של Axiom Space כדי להתאים לצורכי המשימות הקרובות, לקראת ההליכה על הירח בתוכנית ארטמיס.","tag_he":"ארטמיס"},{"date":"2026-08","tag_he":"אבן דרך","title_he":"הרקטה של Artemis III מתגבשת","text_he":"באוגוסט 2026 החלה במרכז החלל קנדי התקנת ארבעת המנועים הראשיים בליבת רקטת SLS שתשגר את צוות Artemis III. במקביל חוברה קפסולת הצוות של Orion אל מודול השירות האירופי שלה. בנאס\"א מדווחים שקצב האינטגרציה מהיר מזה של Artemis II, סימן שהסוכנות מיישמת את הלקחים מהמשימה הקודמת."},{"date":"2026-07","tag_he":"תוכנית","title_he":"נחשף תסריט העגינה של Artemis III","text_he":"נאס\"א פרסמה את פרטי המשימה המעודכנת: ראשונה תשוגר נחתת Blue Moon Mark 2 של Blue Origin, שתוכל להמתין במסלול עד 30 ימים, אחריה יעלו ארבעת האסטרונאוטים בחללית Orion על גבי רקטת SLS, ולבסוף תצטרף נחתת ניסוי של Starship. הצוות יבלה כשבועיים בגובה של כ 460 ק\"מ מעל כדור הארץ ויתרגל עגינות עם שתי הנחתות, חזרה כללית לקראת הנחיתה על הירח."},{"date":"2026-04","tag_he":"תקציב","title_he":"בקשת תקציב 2027: המדע שוב על הכוונת","text_he":"הבית הלבן פרסם בקשת תקציב של 18.8 מיליארד דולר לשנת 2027, שוב עם קיצוץ של כמעט מחצית מתקציב המדע של נאס\"א: 65 אחוזים פחות לאסטרופיזיקה, 52 אחוזים פחות לחקר השמש. אחרי שהקונגרס דחה קיצוצים דומים שנה קודם לכן וקבע תקציב של 24.44 מיליארד דולר, הקרב התקציבי נפתח מחדש."},{"date":"2026-04","tag_he":"שיגור","title_he":"Artemis II: בני אדם סביב הירח לראשונה מאז 1972","text_he":"ב 1 באפריל 2026 שוגרה משימת Artemis II ממרכז החלל קנדי, עם ריד ווייזמן, ויקטור גלובר, כריסטינה קוך והקנדי ג''רמי הנסן. הצוות חלף במרחק של כ 6,500 ק\"מ מפני הירח, קבע שיא אנושי של כ 407,000 ק\"מ מכדור הארץ, ונחת בשלום באוקיינוס השקט ב 10 באפריל. זו הייתה הטיסה המאוישת הראשונה של חללית Orion, והוכחה שמערכת ההסעה של תוכנית Artemis עובדת."},{"date":"2026-02","tag_he":"מדיניות","title_he":"טלטלה בתוכנית Artemis: ביטול שדרוגי SLS","text_he":"המנהל החדש ג''ארד אייזקמן הכריז על שינוי כיוון עמוק: ביטול השלב העליון החדש של רקטת SLS ותצורות השדרוג Block 1B, Block 2, אחרי שכבר הושקעו בהן כ 2 מיליארד דולר. הרקטה תישאר בתצורת Block 1 הקיימת, ונאס\"א בוחנת שלב עליון מסחרי מבוסס Centaur V של ULA. במסגרת אותה החלטה הפכה Artemis III ממשימת נחיתה לתרגיל עגינה במסלול סביב כדור הארץ, והנחיתה נדחתה למשימת Artemis IV עם יעד בשנת 2028."},{"date":"2025-12","tag_he":"מינוי","title_he":"ג''ארד אייזקמן אושר כמנהל נאס\"א","text_he":"הסנאט אישר ברוב של 67 מול 30 את מינויו של המיליארדר והאסטרונאוט הפרטי ג''ארד אייזקמן למנהל מספר 15 של נאס\"א, אחרי סאגה של שנה שכללה מועמדות, ביטול פתאומי ומינוי מחדש. אייזקמן, שפיקד על טיסות החלל הפרטיות Inspiration4 וכן Polaris Dawn, נכנס לתפקיד עם אג''נדה מסחרית מובהקת."},{"date":"2025-11","tag_he":"חוזה","title_he":"Starliner מורדת לתפקיד ספינת משא","text_he":"אחרי שנים של תקלות במערכת ההנעה, נאס\"א וחברת Boeing הסבו את טיסת Starliner הבאה מטיסה מאוישת של ארבעה אסטרונאוטים לטיסת מטען בלבד, והחוזה צומצם משש משימות מאוישות לארבע משימות בסך הכול. נכון לספטמבר 2026 הטיסה טרם התקיימה, והיא נדחתה לרבעון האחרון של השנה."},{"date":"2025-10","tag_he":"אבן דרך","title_he":"הושלמה הערמת הרקטה של Artemis II","text_he":"בבניין הרכבת החלליות במרכז קנדי הונחה חללית Orion בראש רקטת SLS, והשלימה מגדל בגובה של כ 98 מטרים, גבוה יותר מפסל החירות. ההערמה סימנה את המעבר משלב הייצור לשלב ההכנות האחרונות לקראת השיגור המאויש הראשון של התוכנית, והרקטה הגיעה לכן השיגור במרץ 2026."},{"date":"2025-07","tag_he":"תקציב","title_he":"הקונגרס מזרים כ 10 מיליארד דולר לתוכנית הירח","text_he":"חוק התקציב הגדול שנחתם ב 4 ביולי 2025 כלל תוספת של כ 10 מיליארד דולר לנאס\"א ביוזמת הסנאטור טד קרוז: 4.1 מיליארד דולר לרקטות SLS של המשימות Artemis IV, Artemis V, וכן 2.6 מיליארד דולר להשלמת תחנת Gateway שתקיף את הירח, לצד תקציב להמשך הפעלת תחנת החלל הבינלאומית. התוספת נטרלה בפועל את ניסיון הביטול של הבית הלבן."},{"date":"2025-05","tag_he":"תקציב","title_he":"הצעה לקצץ רבע מתקציב נאס\"א","text_he":"הבית הלבן הציע תקציב של 18.8 מיליארד דולר לשנת 2026, קיצוץ של כרבע מהתקציב הקיים: ביטול של יותר מ 40 משימות מדע, צמצום כוח האדם מ 17,400 עובדים בקירוב ל 11,850, וסיום דרכן של רקטת SLS וחללית Orion אחרי Artemis III. הקונגרס דחה לבסוף את רוב הקיצוצים, אבל אי הוודאות הובילה לגל עזיבות ופגעה במורל הסוכנות."},{"date":"2025-03","tag_he":"משימה","title_he":"אסטרונאוטי Starliner חזרו הביתה אחרי תשעה חודשים","text_he":"בוץ'' וילמור וסוני ויליאמס, שהמריאו ביוני 2024 לטיסת ניסוי של שמונה ימים בחללית Starliner, נחתו סוף סוף בכדור הארץ אחרי כ 286 ימים בתחנת החלל, לאחר שחלליתם הוחזרה ריקה בגלל תקלות במנועי הדחף. השניים חזרו בקפסולת Dragon של SpaceX, בפרשה שהפכה לסמל פער האמינות בין שתי ספקיות הטיסות המאוישות של נאס\"א."},{"date":"2024-10","tag_he":"שיגור","title_he":"Europa Clipper יצאה למסע אל הירח הקפוא של צדק","text_he":"החללית הפלנטרית הגדולה ביותר שנאס\"א בנתה אי פעם, במשקל של כ 6 טונות ועם מערכי שמש שנפרשים לרוחב של כ 30 מטרים, שוגרה על רקטת Falcon Heavy. היא תגיע למערכת צדק בשנת 2030 ותבדוק אם באוקיינוס שמתחת לקרח של הירח Europa קיימים תנאים לחיים."},{"date":"1969-07","tag_he":"היסטוריה","title_he":"Apollo 11: צעד קטן לאדם","text_he":"ניל ארמסטרונג ובאז אולדרין נחתו על הירח ב 20 ביולי 1969, שמונה שנים בלבד אחרי שהנשיא קנדי הציב את היעד. שש נחיתות מאוישות של תוכנית Apollo נותרו עד היום הפעמים היחידות שבני אדם דרכו על עולם אחר."},{"date":"1958-10","tag_he":"היסטוריה","title_he":"הקמת נאס\"א","text_he":"בתגובה לשיגור הלוויין הסובייטי Sputnik הקים הקונגרס האמריקאי סוכנות חלל אזרחית חדשה, על בסיס גוף המחקר האווירונאוטי NACA. מאז הפכה נאס\"א לשם נרדף לחקר החלל: מהאדם הראשון על הירח ועד טלסקופים שרואים את קצה היקום."}],"programs":[{"name":"Artemis","desc_he":"תוכנית הדגל להחזרת בני אדם לירח ולבניית נוכחות קבועה בו. משימת Artemis II הקיפה את הירח באפריל 2026, משימת Artemis III תתרגל עגינות עם שתי נחתות במסלול סביב כדור הארץ בשנת 2027, והנחיתה המאוישת מתוכננת למשימת Artemis IV בשנת 2028.","status_he":"פעילה, המשימה הבאה בשנת 2027"},{"name":"Space Launch System","desc_he":"רקטת הענק שמשגרת את חללית Orion אל הירח, בגובה של כ 98 מטרים ועם דחף המראה של כ 39,000 קילוניוטון. אחרי ביטול השדרוגים בתחילת 2026 היא תישאר בתצורת Block 1 הקיימת, ונאס\"א בוחנת החלפה של השלב העליון בפתרון מסחרי.","status_he":"מבצעית"},{"name":"Human Landing System","desc_he":"חוזי הנחתות המאוישות: Starship HLS של SpaceX ונחתת Blue Moon Mark 2 של Blue Origin. שתי החברות מפתחות במקביל, ושתיהן יבצעו תרגילי עגינה עם חללית Orion במשימת Artemis III לפני הנחיתה עצמה.","status_he":"בפיתוח"},{"name":"Gateway","desc_he":"תחנת חלל קטנה שתקיף את הירח ותשמש נקודת ביניים למשימות Artemis. הקונגרס הבטיח לה 2.6 מיליארד דולר להשלמה, והמודולים הראשונים שלה נמצאים בשלבי בנייה ובדיקות.","status_he":"בבנייה"},{"name":"Commercial LEO Destinations","desc_he":"התוכנית שמממנת תחנות חלל פרטיות שיחליפו את תחנת החלל הבינלאומית לקראת הוצאתה ממסלול סביב שנת 2030. בין המתמודדות: תחנת Haven 1 של Vast עם יעד שיגור בתחילת 2027, תחנת Axiom, תחנת Starlab וכן Orbital Reef.","status_he":"בתחרות פעילה"},{"name":"Commercial Crew","desc_he":"רכש שירותי הטסת אסטרונאוטים מחברות פרטיות. קפסולת Dragon של SpaceX מטיסה צוותים באופן שוטף מאז 2020, ואילו Starliner של Boeing הוסבה בינתיים לטיסת מטען ניסיונית אחרי שנים של תקלות.","status_he":"פעילה"},{"name":"מדע וחקר רובוטי","desc_he":"צי של טלסקופים, גשושיות ורכבי שטח: טלסקופ James Webb, החללית Europa Clipper שבדרכה לצדק, ורכבי המאדים. התחום נמצא תחת איום תקציבי כבד, עם הצעות חוזרות לקצץ כמחצית ממנו.","status_he":"פעילה תחת איום תקציבי"}],"vehicles":["sls"]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.companies (slug, doc) values ('rocket-lab', '{"slug":"rocket-lab","name_he":"רוקט לאב","name_en":"Rocket Lab","tagline_he":"לחלל, בקצב של פס ייצור","description_he":"Rocket Lab היא חברת השיגורים הפעילה ביותר בעולם המערבי אחרי SpaceX, והמתחרה הקרובה ביותר שלה בשוק המסחרי. את החברה הקים בשנת 2006 המהנדס הניו זילנדי Peter Beck, וכיום המטה שלה שוכן בלונג ביץ'' שבקליפורניה והיא משגרת משלושה כני שיגור בשני חצאי כדור הארץ. מוצר הדגל שלה הוא Electron, רקטה קטנה בגובה 18 מטרים בלבד שמובילה בערך 300 קילוגרם למסלול נמוך. אם Falcon 9 של SpaceX היא משאית הובלה ענקית, Electron היא שליח האופנוע של תעשיית החלל: היא נושאת מטען קטן, אבל מגיעה בדיוק לכתובת ובזמן שנוח ללקוח.\n\nמעבר לשיגורים, Rocket Lab הפכה בשנים האחרונות ליצרנית חלל מקיפה. היא בונה ספינות חלל ממשפחת Photon, מייצרת רכיבים ותוכנה לחלק גדול מתעשיית הלוויינים, ואחרי רכישת Geost האמריקאית ורכישת Mynaric הגרמנית היא מספקת גם חיישנים ביטחוניים ומסופי תקשורת לייזר. בנוסף היא מפעילה את HASTE, גרסה תת מסלולית של Electron שמשמשת את הפנטגון כמעבדה מעופפת לניסויים היפרסוניים. בשנת 2025 קבעה החברה שיא עם 21 שיגורים מוצלחים, ובשנת 2026 היא בדרך לשבור אותו.\n\nהפרויקט הגדול של החברה הוא Neutron, רקטה רב פעמית בגובה 43 מטרים שתוביל 13 טונות למסלול נמוך ותתחרה ישירות ברקטת Falcon 9. השלב הראשון שלה מתוכנן לנחות בחזרה, וחרטום המטען שלה, המכונה Hungry Hippo, נפתח כמו פה של היפופוטם: הוא משחרר את השלב השני וחוזר לקרקע סגור ושלם יחד עם הבוסטר. טיסת הבכורה מתוכננת לסוף 2026 מאתר Wallops שבווירג''יניה, ואחריה מחכה גם משימה יוצאת דופן: הגשושית הפרטית הראשונה לכוכב הלכת נוגה, שתחפש סימנים לחומרים אורגניים בעננים.","color":"#E4002B","founded":"2006","hq_he":"לונג ביץ'', קליפורניה, ארצות הברית","ll2_id":147,"news_query":"Rocket Lab","stats":[{"label_he":"משימות Electron","value":"95+","sub_he":"מאז 2017, נכון לספטמבר 2026, כולל 16 שיגורים מתחילת השנה"},{"label_he":"שיגורים בשנת 2025","value":"21","sub_he":"שיא שנתי חדש, וכל המשימות הצליחו"},{"label_he":"כושר נשיאה של Neutron","value":"13 טונות","sub_he":"למסלול נמוך בתצורה רב פעמית, בכורה מתוכננת לסוף 2026"},{"label_he":"הכנסות בשנת 2025","value":"602 מיליון דולר","sub_he":"שיא כל הזמנים, לעומת 436 מיליון דולר בשנת 2024"}],"timeline":[{"date":"2026-09","title_he":"רכישת Iridium","text_he":"Rocket Lab מקדמת עסקה לרכישת מפעילת התקשורת הלוויינית Iridium תמורת כשמונה מיליארד דולר. העסקה הופכת אותה מחברת שיגור לחברת חלל אנכית מלאה: שיגור, לוויינים ושירותי תקשורת תחת קורת גג אחת.","tag_he":"עסקים"},{"date":"2026-09","tag_he":"עדכון Neutron","title_he":"Neutron בישורת האחרונה לקראת טיסת הבכורה","text_he":"חרטום המטען הרב פעמי של Neutron, שקיבל את הכינוי Hungry Hippo, סיים את בדיקות ההסמכה והקבלה ונשלח לאתר השיגור LC-3 בווירג''יניה. במקביל חצתה החברה את רף 95 המשימות של Electron עם השיגור המוצלח של 11 בספטמבר, השישה עשר מתחילת 2026. היעד הרשמי לבכורת Neutron נותר הרבעון האחרון של 2026, אם כי בחברה מודים שחלון הזמן הולך ומצטמצם."},{"date":"2026-08","tag_he":"חוזה ביטחוני","title_he":"חוזה של 397 מיליון דולר מחיל החלל האמריקאי","text_he":"Rocket Lab נבחרה לבנות ולשגר לpredviיני Flatellite עבור תוכנית המעקב אחר מטרות אוויריות נעות של חיל החלל האמריקאי. זהו החוזה הגדול הראשון ללוויין השטוח שנחשף בתחילת 2025, והוא מסמן את הפיכת החברה מספקית שיגורים לקבלנית ביטחונית שמספקת מערכת שלמה: הרקטה, ספינת החלל וגם החיישן המבצעי."},{"date":"2026-05","tag_he":"עסקה","title_he":"עסקת השיגורים הגדולה בתולדות החברה","text_he":"לקוח מסחרי חסוי הזמין חמישה שיגורי Neutron לצד שיגורי Electron, בעסקה שהחברה הגדירה כגדולה ביותר בתולדותיה. באותו יום נחתם גם חוזה של 30 מיליון דולר עם Anduril לשלושה שיגורי HASTE היפרסוניים. הזמנות בהיקף כזה ל Neutron, עוד לפני טיסת הבכורה, משקפות ביקוש אמיתי בשוק לחלופה לרקטת Falcon 9 של SpaceX."},{"date":"2026-04","tag_he":"רכישה","title_he":"השלמת רכישת Mynaric והקמת Rocket Lab Europe","text_he":"Rocket Lab השלימה את רכישת Mynaric, חברת תקשורת אופטית מגרמניה, תמורת 155 מיליון דולר, לאחר קבלת אישור רגולטורי סופי. Mynaric מייצרת מסופי לייזר שמאפשרים ללוויינים לדבר זה עם זה בקרני אור במקום בגלי רדיו, טכנולוגיית מפתח לרשתות לוויינים ביטחוניות. הרכישה הפכה לבסיס לזרוע אירופית חדשה בשם Rocket Lab Europe."},{"date":"2026-03","tag_he":"חוזה ביטחוני","title_he":"190 מיליון דולר עבור 20 טיסות היפרסוניות","text_he":"משרד המלחמה האמריקאי הזמין 20 טיסות ניסוי של HASTE במסגרת תוכנית MACH-TB 2.0, בחוזה של 190 מיליון דולר שיתפרש על פני ארבע שנים. HASTE, גרסה תת מסלולית של Electron, משמשת מעבדה מעופפת לכלי טיס שנעים במהירות העולה על פי חמישה ממהירות הקול. החוזה ביסס את מעמדה של Rocket Lab כספקית ניסויי הטיסה ההיפרסוניים המרכזית של הפנטגון."},{"date":"2026-02","tag_he":"עדכון Neutron","title_he":"Neutron נדחית לסוף 2026 אחרי קריעת מכל בניסוי","text_he":"במהלך ניסוי לחץ עם מים בינואר נקרע מכל דלק של השלב הראשון של Neutron, והחברה דחתה את טיסת הבכורה מאמצע השנה לסופה. במקביל פרסמה Rocket Lab דוחות שיא לשנת 2025: הכנסות של 602 מיליון דולר, עלייה של 38 אחוזים לעומת שנת 2024. בחברה הדגישו שהעדיפות היא הצלחה בניסיון הראשון להגיע למסלול, גם במחיר של דחייה."},{"date":"2025-12","tag_he":"שיא","title_he":"2025 נסגרת עם 21 שיגורי Electron והצלחה מלאה","text_he":"שיגור לוויין מכ\"ם של חברת iQPS היפנית חתם שנה עם 21 שיגורי Electron, שיא שנתי חדש, וכל המשימות הצליחו. השיגורים בוצעו משלושה כנים בשני חצאי כדור הארץ: שניים בחצי האי Mahia בניו זילנד ואחד באתר Wallops שבווירג''יניה. לשם השוואה, בשנת 2024 עמד השיא על 16 שיגורים בלבד."},{"date":"2025-11","tag_he":"אבן דרך","title_he":"שני שיגורים ביומיים ושתי גשושיות בדרך למאדים","text_he":"Rocket Lab שברה את השיא השנתי שלה עם שני שיגורי Electron בהפרש של יומיים בלבד, משני חצאי כדור הארץ. באותו חודש המריאו גם שתי גשושיות ESCAPADE שבנתה החברה עבור NASA למסע אל מאדים, על גבי רקטת New Glenn של Blue Origin. בנוסף הודיעה החברה רשמית שבכורת Neutron לא תתקיים בשנת 2025 אלא בשנת 2026."},{"date":"2025-08","tag_he":"רכישה","title_he":"רכישת Geost תמורת 275 מיליון דולר","text_he":"Rocket Lab השלימה את רכישת Geost מאריזונה, שמפתחת חיישנים אופטיים וחיישני אינפרה אדום ללווייני התרעה וביטחון. העסקה, בהיקף של 275 מיליון דולר, השלימה את החזון של החברה כקבלנית ביטחון מקצה לקצה: שיגור, ספינת חלל, ועכשיו גם המטען המבצעי עצמו."},{"date":"2025-02","tag_he":"חשיפה","title_he":"חשיפת Flatellite, לוויין שטוח לייצור המוני","text_he":"החברה הציגה לוויין שטוח שניתן לערום בערימות, ותוכנן מהיסוד לייצור בקצב תעשייתי, בהשראת גישת פס הייצור של Starlink. המבנה השטוח מאפשר לדחוס עשרות לוויינים בשיגור Neutron אחד. חודש לאחר מכן צורפה החברה גם למסלול ההתקשרות של תוכנית השיגורים הביטחונית הלאומית NSSL בארצות הברית, כרטיס כניסה לחוזי שיגור צבאיים עבור Neutron."},{"date":"2024-08","tag_he":"אבן דרך","title_he":"הצתה ראשונה של מנוע Archimedes ושנת שיא של Electron","text_he":"Archimedes, מנוע המתאן שיניע את Neutron, ביצע הצתה מלאה ראשונה במתקן הניסויים של NASA במיסיסיפי. באותה שנה קבעה Electron שיא של 16 שיגורים וחצתה את רף 50 המשימות. מאז השלים המנוע מאות הצתות ניסוי בדרך להסמכת תשעת המנועים של טיסת הבכורה."},{"date":"2023-06","tag_he":"בכורה","title_he":"טיסת הבכורה של HASTE","text_he":"הגרסה התת מסלולית של Electron המריאה לראשונה מווירג''יניה עבור ניסוי היפרסוני של ממשל ארצות הברית. במקום להקיף את כדור הארץ, HASTE מטיסה מטעני ניסוי בקשת גבוהה ומהירה בתוך האטמוספירה. מאז הפכה לעסק ביטחוני משמעותי עם עשרות טיסות מוזמנות."},{"date":"2022-06","tag_he":"אבן דרך","title_he":"CAPSTONE בדרך לירח ותפיסת בוסטר במסוק","text_he":"ספינת החלל Photon הובילה את לוויין הניווט CAPSTONE של NASA אל מסלול סביב הירח, המשימה הראשונה של Rocket Lab מעבר למסלול כדור הארץ. חודש קודם לכן תפסה החברה לרגע בוסטר Electron באוויר באמצעות מסוק, ניסוי נועז במסגרת מאמצי השימוש החוזר בשלב הראשון."},{"date":"2006-06","tag_he":"הקמה","title_he":"Peter Beck מקים את Rocket Lab בניו זילנד","text_he":"המהנדס האוטודידקט Peter Beck ייסד את החברה באוקלנד, ובשנת 2009 שיגרה Rocket Lab את Atea 1, הרקטה הפרטית הראשונה שהגיעה לחלל מחצי הכדור הדרומי. בשנת 2017 המריאה Electron לראשונה, ובינואר 2018 הגיעה למסלול בהצלחה. כיום המטה שוכן בלונג ביץ'' שבקליפורניה והחברה נסחרת בבורסת Nasdaq."}],"programs":[{"name":"Electron","status_he":"פעיל","desc_he":"רקטה קלה בגובה 18 מטרים מסיבי פחמן, שמובילה בערך 300 קילוגרם למסלול נמוך. מנועי Rutherford שלה מודפסים בתלת ממד ומונעים במשאבות חשמליות, רעיון שהיה מהפכני בזמנו. עם יותר מ 95 משימות, זו הרקטה הקלה המצליחה בעולם, והחברה גם משחזרת בוסטרים מהים לצורך שימוש חוזר ברכיבים."},{"name":"Neutron","status_he":"בפיתוח, בכורה מתוכננת לסוף 2026","desc_he":"רקטה בינונית רב פעמית בגובה 43 מטרים עם תשעה מנועי מתאן מדגם Archimedes, שתוביל 13 טונות למסלול נמוך. חרטום המטען Hungry Hippo נפתח כמו פה של היפופוטם, משחרר את השלב השני ונשאר מחובר לבוסטר שחוזר לנחיתה. תשגר מאתר Wallops בווירג''יניה ותתחרה ישירות ברקטת Falcon 9."},{"name":"HASTE","status_he":"פעיל","desc_he":"גרסה תת מסלולית של Electron שמשמשת את משרד המלחמה האמריקאי כמעבדה מעופפת לניסויים היפרסוניים, כלומר טיסה במהירות העולה על פי חמישה ממהירות הקול. בשנת 2026 נחתם חוזה של 190 מיליון דולר עבור 20 טיסות, לצד עסקאות עם Anduril ו Kratos."},{"name":"Photon וספינות חלל","status_he":"פעיל","desc_he":"משפחת ספינות חלל שהחברה בונה ללקוחות: Photon הובילה את CAPSTONE לירח בשנת 2022, גרסת Explorer שימשה את גשושיות ESCAPADE של NASA שיצאו למאדים בשנת 2025, וגרסת Pioneer משמשת את קפסולות הייצור בחלל של Varda. הזרוע הזו כוללת גם חיישנים של Geost ותקשורת לייזר של Mynaric."},{"name":"Flatellite","status_he":"בפיתוח, חוזה ראשון נחתם","desc_he":"לוויין שטוח שנחשף בשנת 2025 ותוכנן לייצור המוני ולערימה צפופה בתוך חרטום של Neutron. בשנת 2026 זכתה החברה בחוזה של 397 מיליון דולר לבנות ולשגר לווייני Flatellite למערך מעקב של חיל החלל האמריקאי."},{"name":"משימת נוגה","status_he":"ממתינה לזמינות Neutron","desc_he":"הגשושית הפרטית הראשונה לכוכב הלכת נוגה, בשיתוף חוקרים מ MIT ובעלות של פחות מ 10 מיליון דולר. גשושית קטנה תצלול בענני נוגה למשך שלוש דקות ותחפש מולקולות אורגניות, רמז אפשרי לחיים. המשימה נדחתה שוב ושוב וכעת היא ממתינה לרקטת Neutron מוכנה לטיסה."}],"vehicles":["electron","neutron"]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.companies (slug, doc) values ('spacex', '{"slug":"spacex","name_he":"SpaceX","name_en":"SpaceX","tagline_he":"להפוך את האנושות למין רב כוכבי","description_he":"SpaceX, שהקים אילון מאסק בשנת 2002, היא חברת החלל הגדולה והמשפיעה בעולם, והמטרה המוצהרת שלה נשמעת כמו מדע בדיוני: להפוך את האנושות למין שחי על יותר מכוכב לכת אחד. הדרך לשם עוברת בשימוש חוזר ברקטות. אם פעם כל רקטה הייתה נזרקת לים אחרי שיגור אחד, כמו מטוס נוסעים שמושבת אחרי טיסה אחת, SpaceX הפכה את הנחיתה של רקטות ואת הטסתן שוב ושוב לשגרה יומיומית. ביוני 2026 הפכה החברה לציבורית בהנפקה הגדולה בהיסטוריה, ושווי השוק שלה חצה 2 טריליון דולר כבר ביום המסחר הראשון.\n\nסוס העבודה של החברה הוא Falcon 9, רקטה בגובה 70 מטרים שהשלימה 165 שיגורים בשנת 2025 לבדה, שיגור בערך כל יומיים, ובשנת 2026 היא בדרך לעבור את רף 150 השיגורים בשנה. בוסטרים בודדים כבר צברו 37 טיסות כל אחד. הרקטות האלה בונות את Starlink, קבוצת האינטרנט הלוויינית של החברה: מעל 11,000 לוויינים פעילים במסלול נמוך, שמשרתים 12 מיליון מנויים ברחבי העולם ומכניסים לחברה יותר ממחצית מהכנסותיה.\n\nאבל הפרויקט המרכזי הוא Starship: רקטה דו שלבית בגובה 124 מטרים, גבוהה ממגדל בן 40 קומות, שמתוכננת להיות רב פעמית במלואה. מאז 2023 ביצעה 13 טיסות ניסוי, ומאז מאי 2026 טסה גרסת V3 עם מנועי Raptor 3, שכל אחד מהם מפיק דחף של בערך 2,750 קילוניוטון, כמו להרים משקל של 280 טונות. גרסה ירחית של Starship נבחרה על ידי NASA להנחית אסטרונאוטים על הירח בתוכנית Artemis, במשימה שמתוכננת כיום לשנת 2028, ובטווח הארוך זהו הכלי שאמור לשאת בני אדם למאדים.","color":"#005288","founded":"2002","hq_he":"Starbase, טקסס, ארצות הברית","ll2_id":121,"news_query":"SpaceX","stats":[{"value":"165","label_he":"שיגורים בשנת 2025","sub_he":"שיא עולמי לחברה אחת: שיגור בערך כל יומיים"},{"value":"12 מיליון","label_he":"מנויי Starlink","sub_he":"נכון ליוני 2026, כפול מאשר שנה קודם לכן"},{"value":"124 מטרים","label_he":"גובה Starship V3","sub_he":"הרקטה הגדולה והחזקה בהיסטוריה, גבוהה ממגדל בן 40 קומות"},{"value":"2 טריליון דולר","label_he":"שווי שוק","sub_he":"אחרי ההנפקה הגדולה בהיסטוריה, נאסד\"ק, יוני 2026"}],"timeline":[{"date":"2026-09","title_he":"הכנות לניסיון המסלולי המלא של Starship","text_he":"טיסה 14 של Starship מתוכננת לניסיון השיגור המסלולי המלא הראשון, עם 26 לווייני Starlink בתא המטען. המטרה: להשלים הקפה ולחזור, במקום המסלולים החלקיים של הטיסות הקודמות.","tag_he":"Starship"},{"date":"2026-08","title_he":"שיגור טלסקופ החלל Roman","text_he":"בסוף אוגוסט 2026 שיגר Falcon Heavy בהצלחה את טלסקופ הדגל של נאס\"א, Nancy Grace Roman. נאס\"א מפקידה בידי SpaceX גם את המטענים המדעיים היקרים ביותר שלה.","tag_he":"מדע"},{"date":"2026-08","title_he":"Starbase לואיזיאנה","text_he":"SpaceX הכריזה על הקמת Starbase, Louisiana: מתחם שמתוכנן להיות נמל החלל הפרטי הגדול בעולם, לצד האתר הקיים בטקסס.","tag_he":"תשתית"},{"date":"2026-09","tag_he":"צפוי","title_he":"טיסה 14: לוויינים אמיתיים למסלול יציב","text_he":"הטיסה הבאה של Starship מתוכננת לתאריך 22 בספטמבר 2026, והיא צפויה להיות הראשונה שמציבה לוויינים במסלול יציב סביב כדור הארץ: 26 לווייני Starlink V3. עד היום שוחררו מהחללית רק דגמי דמה במסלול חלקי שהסתיים באוקיינוס. אם הטיסה תצליח, Starship תהפוך רשמית מרקטת ניסוי לרקטה שמובילה מטענים מבצעיים."},{"date":"2026-08","tag_he":"אבן דרך","title_he":"100 שיגורי Falcon 9 בשנה, עוד לפני סוף אוגוסט","text_he":"בתאריך 25 באוגוסט 2026 שיגרה SpaceX את משימת Falcon 9 המאה שלה לשנה זו, עם 29 לווייני Starlink מקייפ קנוורל. לשם השוואה, בכל שנת 2023 ביצעה החברה 96 שיגורים, מספר שנחשב אז בלתי נתפס. באותה טיסה השלים הבוסטר B1067 את הטיסה מספר 37 שלו, והוא מתקרב לשיא של מעבורת החלל: 39 טיסות לכלי טיס אחד."},{"date":"2026-07","tag_he":"טיסת ניסוי","title_he":"טיסה 13: לווייני Starlink V3 ראשונים בחלל","text_he":"בתאריך 24 ביולי 2026 המריאה Starship לטיסתה השלוש עשרה, השנייה של דור V3. לראשונה שוחררו ממנה לווייני Starlink V3 מהדור הבא, והחללית אספה נתונים קריטיים על ביצועי מגן החום בכניסה לאטמוספירה. בסיום ביצעה תמרון הטיה דינמי שמדמה את מסלול החזרה העתידי אל מגדל השיגור ב Starbase, ונחתה בדיוק מלא באוקיינוס ההודי."},{"date":"2026-06","tag_he":"עסקים","title_he":"ההנפקה הגדולה בהיסטוריה: SpaceX נסחרת בנאסד\"ק","text_he":"בתאריך 12 ביוני 2026 החלה SpaceX להיסחר תחת הסימול SPCX, במחיר של 135 דולר למניה. ההנפקה גייסה בערך 86 מיליארד דולר, הסכום הגדול ביותר אי פעם בהנפקה ראשונה, ושווי השוק חצה 2 טריליון דולר כבר ביום המסחר הראשון. מהתשקיף התברר ש Starlink הכניסה 11.4 מיליארד דולר בשנת 2025, יותר ממחצית מסך הכנסות החברה, כלומר עסקי האינטרנט כבר גדולים מעסקי השיגורים."},{"date":"2026-05","tag_he":"טיסת ניסוי","title_he":"טיסה 12: בכורה לדור V3 ולמנוע Raptor 3","text_he":"בתאריך 22 במאי 2026 המריאה לראשונה גרסת V3 של Starship, הרקטה הגדולה בהיסטוריה: 124 מטרים, גבוהה ממגדל בן 40 קומות. זו הייתה גם טיסת הבכורה של מנועי Raptor 3 החדשים, וגם השיגור הראשון אי פעם מכן השיגור החדש Pad 2 ב Starbase. בנוסף שוחררו לווייני Starlink מותאמים שצילמו את Starship בחלל מבחוץ, לראשונה בתוכנית."},{"date":"2026-02","tag_he":"Artemis","title_he":"NASA משנה תוכנית: הנחיתה על הירח עוברת ל Artemis IV","text_he":"בפברואר 2026 עדכנה NASA את מבנה תוכנית Artemis: משימת Artemis III, המתוכננת לשנת 2027, תישאר במסלול נמוך סביב כדור הארץ ותשמש אימון עגינה בין חללית Orion לבין אבות טיפוס של נחתות, ובהן Starship HLS של SpaceX. הנחיתה המאוישת עצמה נדחתה למשימת Artemis IV, המתוכננת לשנת 2028. עבור SpaceX זו דחייה מאכזבת, אבל גם הזדמנות לבחון את הנחתת הירחית בתנאים אמיתיים לפני הרגע הגדול."},{"date":"2025-12","tag_he":"שיא","title_he":"שנת שיא: 165 שיגורים בשנת 2025","text_he":"SpaceX סגרה את שנת 2025 עם 165 שיגורי Falcon, שיא עולמי לחברה אחת: שיגור בערך כל יומיים. 123 מהמשימות הוקדשו ל Starlink והציבו במסלול יותר מ 3,000 לוויינים חדשים באותה שנה בלבד. הבוסטר B1067 הגיע ל 32 טיסות, נתון שממחיש עד כמה השימוש החוזר הפך לשגרה, כמו מטוס נוסעים שחוזר לטרמינל ויוצא מיד לטיסה הבאה."},{"date":"2025-10","tag_he":"טיסת ניסוי","title_he":"טיסה 11: סיום מושלם לדור השני של Starship","text_he":"בתאריך 13 באוקטובר 2025 השלימה Starship את טיסתה האחת עשרה, האחרונה של דור V2 והאחרונה מכן השיגור הישן. כל יעדי הטיסה הושגו: שחרור שמונה דגמי Starlink, הצתה חוזרת של מנוע Raptor בחלל, יכולת קריטית לתמרוני חזרה ממסלול, ונחיתות מדויקות של הבוסטר במפרץ ושל החללית באוקיינוס ההודי. ההצלחה סללה את הדרך למעבר לדור V3."},{"date":"2025-08","tag_he":"טיסת ניסוי","title_he":"טיסה 10: החזרה לנתיב ההצלחות","text_he":"אחרי חצי שנה של כישלונות, בתאריך 26 באוגוסט 2025 השיגה Starship את כל היעדים המרכזיים של הטיסה העשירית. לראשונה בתולדות התוכנית שוחרר מטען מהחללית: שמונה דגמי דמה של לווייני Starlink. בנוסף נערכו ניסויים במגן החום, כולל הסרה מכוונת של אריחים ובדיקת אריחי מתכת ניסיוניים, לקראת היעד הגדול: שימוש חוזר מלא גם בשלב העליון."},{"date":"2025-01","tag_he":"כישלון","title_he":"חצי שנה קשה: שלושה אובדנים רצופים של השלב העליון","text_he":"בשלוש טיסות רצופות, בין ינואר למאי 2025, אבד השלב העליון של Starship שוב ושוב, בעוד הבוסטרים דווקא תפקדו היטב ואף נתפסו שוב במגדל. התקלות חשפו בעיות בדור V2 של החללית. בשיטת הפיתוח של SpaceX, לטוס, לשבור, לתקן ולטוס שוב, הכישלונות הם חלק מהתהליך, והלקחים מהם הובילו ישירות להצלחות של סוף 2025."},{"date":"2024-10","tag_he":"היסטורי","title_he":"המגדל תופס את הבוסטר: רגע היסטורי בטיסה 5","text_he":"בתאריך 13 באוקטובר 2024 חזר בוסטר Super Heavy, בגובה 71 מטרים, אל מגדל השיגור ונתפס באוויר בין שתי זרועות פלדה, מהלך שמעולם לא נוסה קודם. זה כמו לתפוס בניין בן 20 קומות שצונח מהשמיים, בעדינות של הנחת כוס על שולחן. התפיסה חוסכת כני נחיתה כבדים ומקרבת את החזון: לתדלק את הבוסטר ולשגר אותו שוב מאותו מגדל בתוך שעות."},{"date":"2020-05","tag_he":"היסטורי","title_he":"Demo 2: חברה פרטית מטיסה אסטרונאוטים לראשונה","text_he":"במאי 2020 שיגרה SpaceX את האסטרונאוטים בוב בנקן ודאג הארלי לתחנת החלל הבינלאומית בחללית Dragon. זו הייתה הפעם הראשונה שחברה פרטית מטיסה בני אדם למסלול, והיא החזירה לארצות הברית יכולת שיגור מאוישת שאבדה עם פרישת המעבורות בשנת 2011."},{"date":"2015-12","tag_he":"היסטורי","title_he":"הנחיתה הראשונה: בוסטר Falcon 9 חוזר הביתה","text_he":"בתאריך 21 בדצמבר 2015 נחת לראשונה שלב ראשון של Falcon 9 בשלמותו על הקרקע בפלורידה, דקות אחרי ששיגר 11 לוויינים למסלול. הרגע הזה הוכיח שרקטה אינה חייבת להיות מוצר חד פעמי, והניח את היסודות למהפכת העלויות שהפכה את SpaceX לשליטת שוק השיגורים העולמי."},{"date":"2002-03","tag_he":"ייסוד","title_he":"אילון מאסק מקים את SpaceX","text_he":"החברה נוסדה במרץ 2002 במטרה להוזיל את היציאה לחלל ולהגיע בסופו של דבר למאדים. אחרי שלושה כישלונות של רקטת Falcon 1, הצליח בשנת 2008 השיגור הרביעי, והפך אותה לרקטה הראשונה בהנעה נוזלית שפותחה במימון פרטי והגיעה למסלול. ההישג הציל את החברה מפשיטת רגל וזיכה אותה בחוזה ראשון מ NASA."}],"programs":[{"name":"Starship","desc_he":"מערכת שיגור ענקית ורב פעמית במלואה בגובה 124 מטרים: בוסטר Super Heavy עם 33 מנועים, ומעליו חללית Starship. מיועדת למטענים כבדים, לירח ובעתיד למאדים.","status_he":"בטיסות ניסוי, גרסת V3 טסה מאז מאי 2026"},{"name":"Falcon 9","desc_he":"סוס העבודה של תעשיית החלל העולמית, רקטה בגובה 70 מטרים. השלב הראשון נוחת וטס שוב ושוב, ובוסטרים בודדים כבר צברו 37 טיסות.","status_he":"מבצעית, מעל 100 שיגורים בשנת 2026 עד כה"},{"name":"Starlink","desc_he":"קבוצת לוויינים לאינטרנט מהחלל: מעל 11,000 לוויינים פעילים במסלול נמוך שמספקים גלישה מהירה גם למקומות שאין בהם סיבים או קליטה סלולרית.","status_he":"מבצעית, 12 מיליון מנויים"},{"name":"Dragon","desc_he":"חללית מאוישת ומטענית שמובילה אסטרונאוטים וציוד לתחנת החלל הבינלאומית. מאז 2020 היא המונית של NASA אל המסלול.","status_he":"מבצעית"},{"name":"Starship HLS","desc_he":"גרסה ירחית של Starship שנבחרה על ידי NASA להנחית אסטרונאוטים על הירח. אב טיפוס שלה צפוי לתרגל עגינה עם חללית Orion במשימת Artemis III.","status_he":"בפיתוח, נחיתה מאוישת מתוכננת לשנת 2028"},{"name":"Raptor 3","desc_he":"דור המנועים החדש של Starship, מונע במתאן ובחמצן נוזליים. כל מנוע מפיק דחף של בערך 2,750 קילוניוטון, כמו להרים משקל של 280 טונות, והוא קל ופשוט יותר מקודמיו.","status_he":"מבצעי, טס מאז מאי 2026"},{"name":"Starmind","desc_he":"תשתית מחשוב בינה מלאכותית במסלול: חוות שרתים בחלל, בבנייה אנכית מלאה של SpaceX. נחשף במהלך 2026.","status_he":"בפיתוח"}],"vehicles":["starship","falcon-9"]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.companies (slug, doc) values ('ula', '{"slug":"ula","name_he":"יונייטד לונץ'' אליאנס","name_en":"United Launch Alliance","tagline_he":"כשאסור להיכשל, אמריקה משגרת עם ULA","description_he":"אם SpaceX היא הסטארט אפ המהיר והזול של תעשיית החלל, ULA היא חברת השליחויות המשוריינת של ממשלת ארצות הברית: לא הכי זולה, לא הכי מהירה, אבל המטען מגיע ליעד, תמיד. החברה נוסדה בדצמבר 2006 כמיזם משותף בבעלות שווה של Boeing ו Lockheed Martin, וירשה שתי שושלות רקטות ותיקות, Atlas ו Delta. מאז ביצעה יותר מ 170 שיגורים, ולפי החברה כולם הצליחו, כולל לווייני ריגול סודיים, לווייני GPS וגשושיות של NASA למאדים ולפלוטו.\n\nהעשור הנוכחי הוא עשור של חילופי דורות. משפחת Delta פרשה באפריל 2024, ו Atlas V, שנשען על מנוע רוסי מדגם RD-180, נמצא בשלהי דרכו: נותרו לו שש טיסות בלבד, כולן שמורות לחללית המאוישת Starliner של Boeing. את מקומם תופס Vulcan Centaur, רקטה חדשה בעלת שני שלבים עם מנועי מתאן BE-4 מתוצרת Blue Origin ועד שישה מאיצי דלק מוצק, המסוגלת להרים עד 27 טונות למסלול נמוך. במרץ 2025 הסמיך חיל החלל האמריקאי את Vulcan לשיגורים ביטחוניים, ובאוגוסט 2025 הוא ביצע את משימת הביטחון הלאומי הראשונה שלו. בחוזה NSSL Phase 3 קיבלה ULA שיא של 19 משימות ביטחוניות בשווי כ 5.4 מיליארד דולר לשנים 2027 עד 2032.\n\nאבל 2026 מסרבת להיות שנה קלה. בפברואר, במהלך המשימה הביטחונית השנייה של Vulcan, נשרף נחיר של אחד ממאיצי הדלק המוצק, והלוויינים ניצלו רק בזכות פיצוי מהיר של המנועים הראשיים. חיל החלל הקפיא את כל השיגורים הביטחוניים על Vulcan עד לסיום חקירה שנמשכת עד היום, וזאת חודשים ספורים אחרי שהמנכ\"ל האגדי Tory Bruno התפטר ועבר למתחרה Blue Origin. בינתיים דווקא החזית המסחרית פורחת: Atlas V שיגר שמונה אצוות של לווייני האינטרנט של Amazon, קבוצה שנקראה Project Kuiper וקיבלה בסוף 2025 את השם Amazon Leo, וכעת Vulcan עומד לחזור לטיסה עם 45 לוויינים כאלה בבת אחת, על גבי שלב עליון Centaur V חדש שהותאם במיוחד למשימות מסלול נמוך.","color":"#0033a0","founded":"2006","hq_he":"סנטניאל, קולורדו, ארצות הברית","ll2_id":124,"news_query":"ULA","stats":[{"value":"170+","label_he":"שיגורים מאז 2006","sub_he":"לפי החברה, כולם הצליחו, רצף נדיר בתעשייה"},{"value":"19","label_he":"משימות ביטחון לאומי בחוזה","sub_he":"במסגרת NSSL Phase 3, בשווי כ 5.4 מיליארד דולר"},{"value":"17,056 kN","label_he":"דחף המראה מרבי של Vulcan","sub_he":"בתצורת VC6L עם שישה מאיצי דלק מוצק"},{"value":"47","label_he":"שיגורים שהוזמנו עבור Amazon Leo","sub_he":"38 על Vulcan ועוד 9 על Atlas V"}],"timeline":[{"date":"2026-09","title_he":"Vulcan חוזר לטיסה עם המשימה הראשונה של Amazon Leo","tag_he":"שיגור קרוב","text_he":"אחרי חודשים של קרקוע, ULA מציבה את Vulcan על הכן למשימת LV-01, השיגור הראשון של לווייני האינטרנט Amazon Leo על גבי Vulcan. הרקטה תישא 45 לוויינים בבת אחת על גרסה חדשה של השלב העליון Centaur V, שהותאמה במיוחד למסלולים נמוכים בגובה כ 600 קילומטרים. הטיסה תשמש גם כטיסת הסמכה של התצורה החדשה עבור חיל החלל האמריקאי. היעד הנוכחי: לא לפני ספטמבר 2026."},{"date":"2026-07","title_he":"Atlas V נושא מטען קלאסי בפעם האחרונה","tag_he":"סוף עידן","text_he":"ב 2 ביולי 2026 שיגר Atlas V את משימת Leo 8 של Amazon, הפעם האחרונה שבה הרקטה הוותיקה נושאת מטען רגיל בתוך חרטום. מעתה נותרו במלאי שש רקטות Atlas V בלבד, וכולן שמורות לחללית המאוישת Starliner של Boeing. במקביל הודיעה Amazon שיש לה כבר מספיק לוויינים במסלול כדי להשיק שירות אינטרנט עוד השנה."},{"date":"2026-05","title_he":"בדיקת מאיץ מוצלחת בדרך חזרה לטיסה","tag_he":"חקירה","text_he":"במסגרת חקירת התקלה ביצעה Northrop Grumman מבחן קרקעי מוצלח של מאיץ הדלק המוצק GEM-63XL, מהדגם שכשל בטיסה בפברואר. ULA הגדירה זאת צעד משמעותי לקראת החזרת Vulcan לטיסה עוד במהלך 2026. במקביל, Blue Origin מכניסה שיפורים במנועי BE-4 שהיא מספקת לשלב הראשון של הרקטה."},{"date":"2026-03","title_he":"חיל החלל מקרקע את Vulcan ממשימות ביטחוניות","tag_he":"משבר","text_he":"בעקבות התקלה במאיץ הקפיא חיל החלל האמריקאי את כל שיגורי הביטחון הלאומי על Vulcan עד לסיום החקירה, תהליך שהוגדר רשמית כעניין של חודשים רבים. ההשעיה משאירה בפועל את SpaceX כמשגרת הביטחונית היחידה של ארצות הברית בטווח הקצר. בחיל החלל אף שקלו להטיס את Vulcan בלי מאיצי דלק מוצק כלל, בתצורה חלשה יותר אך פשוטה יותר."},{"date":"2026-02","title_he":"USSF-87: הצלחה עם כוכבית","tag_he":"תקלה בשיגור","text_he":"ב 12 בפברואר 2026 שוגרה משימת הביטחון השנייה של Vulcan, ובה שני לווייני GSSAP שעוקבים אחרי פעילות במסלול הגיאוסטציונרי, בגובה כ 36,000 קילומטרים. כ 20 שניות אחרי ההמראה נצפתה שריפה חריגה בנחיר של אחד מארבעת מאיצי הדלק המוצק, ככל הנראה חדירת להבה דרך הדופן. שני מנועי BE-4 פיצו על אובדן הדחף, והלוויינים הגיעו בדיוק למסלול המתוכנן, אבל התקלה הציתה חקירה מקיפה שמשתקת את הרקטה עד היום."},{"date":"2025-12","title_he":"Tory Bruno עוזב אחרי 12 שנה בפסגה","tag_he":"הנהלה","text_he":"המנכ\"ל Tory Bruno, שהוביל את ULA כמעט 12 שנה ובנה את Vulcan מאפס, התפטר במפתיע ב 22 בדצמבר 2025. זמן קצר אחר כך התברר שהוא עובר למתחרה Blue Origin, לנהל שם את תחום הביטחון הלאומי. John Elbon מונה למנכ\"ל זמני, עם מטרה מוצהרת: להאיץ את קצב השיגורים ל 16 עד 18 בשנת 2026."},{"date":"2025-08","title_he":"המשימה הביטחונית הראשונה של Vulcan","tag_he":"אבן דרך","text_he":"ב 12 באוגוסט 2025 ביצע Vulcan את USSF-106, משימת הביטחון הלאומי הראשונה שלו ומספר 101 של ULA בתחום. המטען המרכזי, לוויין הניווט הניסיוני NTS-3, שוחרר אחרי טיסה של יותר משבע שעות אל מסלול בגובה כ 36,000 קילומטרים. השיגור סימן גם את סוף התלות של משימות הביטחון האמריקאיות במנוע הרוסי RD-180."},{"date":"2025-04","title_he":"מתחילים לבנות את קבוצת הלוויינים של Amazon","tag_he":"שיגור מסחרי","text_he":"ב 28 באפריל 2025 שיגר Atlas V את KA-01, האצווה המבצעית הראשונה של Project Kuiper: 27 לווייני אינטרנט של Amazon. זו הייתה פתיחתו של קמפיין שיגורים צפוף, עם אצוות נוספות ביוני ובספטמבר, בדרך לקבוצה מתוכננת של 3,236 לוויינים שתתחרה ב Starlink. בסוף 2025 העניקה Amazon לפרויקט שם חדש: Amazon Leo."},{"date":"2025-04","title_he":"חוזה ענק: 19 משימות ביטחוניות עד 2032","tag_he":"חוזה","text_he":"חיל החלל חילק את השלב השלישי של תוכנית השיגורים הביטחוניים NSSL: ULA קיבלה 19 משימות בשווי כ 5.4 מיליארד דולר, SpaceX קיבלה 28, ו Blue Origin נכנסה לראשונה עם 7. עבור ULA זו הצבעת אמון עצומה: כמעט 40 אחוז מהמטענים הרגישים ביותר של ארצות הברית לשנים 2027 עד 2032 יעלו על Vulcan."},{"date":"2025-03","title_he":"Vulcan מוסמך רשמית לשיגורים ביטחוניים","tag_he":"הסמכה","text_he":"ב 26 במרץ 2025, אחרי בחינה של 52 קריטריונים ויותר מ 180 מטלות בדיקה נפרדות, הסמיך חיל החלל האמריקאי את Vulcan לשאת מטעני ביטחון לאומי. ULA הפכה בכך לספקית השנייה בלבד המוסמכת לכך, לצד SpaceX. ההסמכה התעכבה כחצי שנה בגלל תקלת הנחיר בטיסת ההסמכה השנייה."},{"date":"2024-10","title_he":"טיסת הסמכה שנייה, עם דרמה","tag_he":"תקלה בשיגור","text_he":"בטיסת ההסמכה Cert-2, ב 4 באוקטובר 2024, ניתק נחיר של אחד ממאיצי הדלק המוצק כ 30 שניות אחרי ההמראה. הרקטה פיצתה על הדחף החסר והשלימה את המשימה, והחקירה מצאה פגם ייצור בבידוד הנחיר. במבט לאחור, זו הייתה הקדמה לתקלה הדומה והחמורה יותר של תחילת 2026."},{"date":"2024-04","title_he":"פרידה מ Delta IV Heavy","tag_he":"סוף עידן","text_he":"ב 9 באפריל 2024 המריאה בפעם האחרונה Delta IV Heavy, הרקטה שבמשך שנים הייתה הדרך היחידה של אמריקה לשגר את לווייני הריגול הכבדים ביותר. הטיסה סגרה יותר מ 60 שנות מורשת של משפחת רקטות Delta. מעתה כל המטענים הכבדים של ULA עוברים אל Vulcan."},{"date":"2024-01","title_he":"טיסת הבכורה של Vulcan","tag_he":"טיסה ראשונה","text_he":"ב 8 בינואר 2024 המריא Vulcan Centaur לראשונה, ואיתו עשו את טיסת הבכורה גם מנועי המתאן BE-4 של Blue Origin. הרקטה שיגרה בהצלחה מלאה את נחתת הירח הפרטית Peregrine. אחרי עשור של פיתוח, ל ULA יש סוף סוף רקטה אמריקאית לחלוטין, בלי מנועים רוסיים."},{"date":"2006-12","title_he":"לידתה של ULA","tag_he":"היסטוריה","text_he":"Boeing ו Lockheed Martin איחדו את עסקי השיגור שלהן למיזם משותף בבעלות שווה, שקיבל מונופול בפועל על השיגורים הממשלתיים של ארצות הברית. החברה החדשה ירשה שתי משפחות רקטות ותיקות, Atlas ו Delta, ובנתה מוניטין של אמינות מושלמת. המונופול נשבר רק כעבור כעשור, כש SpaceX פרצה לתחום."}],"programs":[{"name":"Vulcan Centaur","status_he":"פעיל, מושהה זמנית עד סיום חקירת התקלה","desc_he":"רקטת הדגל החדשה: שני שלבים, שני מנועי מתאן BE-4 של Blue Origin ועד שישה מאיצי דלק מוצק, עם יכולת הרמה של עד 27 טונות למסלול נמוך. הוסמכה לשיגורים ביטחוניים במרץ 2025, ומאז פברואר 2026 מוקרקעת בעקבות תקלת נחיר במאיץ מוצק, עם יעד חזרה לטיסה עוד ב 2026."},{"name":"Atlas V","status_he":"בתהליך פרישה","desc_he":"סוס העבודה הוותיק שטס מאז 2002 עם מנוע רוסי מדגם RD-180. ביולי 2026 נשא מטען רגיל בפעם האחרונה, ונותרו לו שש טיסות בלבד, כולן עבור החללית המאוישת Starliner של Boeing."},{"name":"שיגורי ביטחון לאומי (NSSL)","status_he":"פעיל, בהמתנה לחזרת Vulcan לטיסה","desc_he":"ליבת העסק של ULA: יותר מ 100 משימות ביטחון לאומי בוצעו עד היום, ובחוזה NSSL Phase 3 הוזמנו 19 משימות נוספות בשווי כ 5.4 מיליארד דולר לשנים 2027 עד 2032. חיל החלל הקפיא את השיגורים הללו זמנית עד לסגירת חקירת התקלה של פברואר 2026."},{"name":"חוזה Amazon Leo","status_he":"פעיל","desc_he":"העסקה המסחרית הגדולה בתולדות החברה: 38 שיגורי Vulcan ועוד 9 שיגורי Atlas V לקבוצת לווייני האינטרנט של Amazon, שנקראה בעבר Project Kuiper. שמונה אצוות כבר שוגרו על Atlas V, והשיגור הראשון על Vulcan, עם 45 לוויינים בבת אחת, מתוכנן לא לפני ספטמבר 2026."},{"name":"Delta IV","status_he":"הסתיים","desc_he":"משפחת הרקטות הכבדות שפרשה באפריל 2024 עם הטיסה האחרונה של Delta IV Heavy. במשך שנים הייתה הדרך היחידה של ארצות הברית להציב לווייני ריגול כבדים במסלול, ותפקידה עבר במלואו אל Vulcan."}],"vehicles":["vulcan"]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('LbH1ZDImaI8', '{"video_id":"LbH1ZDImaI8","title":"Is SpaceX''s Raptor engine the king of rocket engines?","year":2019,"length_min":49,"topics_he":["מנועי רקטות","Raptor","בעירה מדורגת בזרימה מלאה","מתאן"],"summary_he":"שיעור היסוד של הערוץ: הסבר מעמיק על מנוע Raptor של SpaceX ועל מחזור הבעירה המדורגת בזרימה מלאה, שבו כל הדלק וכל החמצן מניעים את משאבות הטורבו לפני שהם נשרפים בתא הבעירה. לומדים למה נבחר דווקא מתאן כדלק, ואיך Raptor עומד מול מנועים כמו Merlin של Falcon 9 ומנוע המעבורת RS25. גם היום, כשדור Raptor 3 כבר טס על Starship V3, זה עדיין ההסבר הטוב ביותר להבנת הבסיס.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('Owji-ukVt9M', '{"video_id":"Owji-ukVt9M","title":"Rocket engine cycles: How do you power a rocket engine?","year":2022,"length_min":55,"topics_he":["מחזורי מנוע","משאבות טורבו","הנעה רקטית","השוואת מנועים"],"summary_he":"מפת הדרכים המלאה של מחזורי ההנעה: מהנעה בלחץ גז ומשאבות חשמליות כמו במנוע Rutherford של Electron, דרך מחזור פתוח כמו Merlin, מחזור סגור, מחזור מרחיב כמו במנוע RL10 של הדרגה העליונה של Vulcan, ועד בעירה מדורגת בזרימה מלאה כמו Raptor. אפשר לחשוב על זה כך: השאלה היא מאיפה לוקחים את האנרגיה שמסובבת את המשאבות, וכל תשובה יוצרת מנוע אחר. בסוף מופיע Elon Musk ומסביר בעצמו למה SpaceX בחרה בזרימה מלאה.","related_vehicles":["starship","falcon-9","electron","vulcan"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('D4SaofKCYwo', '{"video_id":"D4SaofKCYwo","title":"Are Aerospikes Better Than Bell Nozzles?","year":2019,"length_min":62,"topics_he":["Aerospike","נחירי מנוע","היסטוריה של החלל"],"summary_he":"שיעור מצוין על נחירים: למה נחיר פעמון רגיל מכוון לגובה אחד בלבד, ואיך מנוע Aerospike מפצה על שינוי לחץ האוויר בזמן הטיפוס לחלל בעזרת האטמוספירה עצמה. הסרטון סוקר את ההיסטוריה, כולל פרויקטים של NASA משנות התשעים, עם צילומים נדירים וראיונות עם מהנדסים שעבדו על המנועים האלה. בסוף מקבלים תשובה כנה לשאלה למה למרות היתרון התיאורטי אף Aerospike עדיין לא הגיע למסלול.","related_vehicles":[]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('he_BL6Q5u1Y', '{"video_id":"he_BL6Q5u1Y","title":"Why don''t rocket engines melt? How engineers keep engines cool","year":2022,"length_min":27,"topics_he":["קירור מנועים","קירור רגנרטיבי","הנדסת חומרים"],"summary_he":"בתא הבעירה של מנוע רקטי שוררים יותר מ 3,000 מעלות צלזיוס, חם יותר מנקודת ההיתוך של כל מתכת, ובכל זאת המנוע שורד. הסוד הוא קירור: הזרמת דלק קר בתעלות דקות בתוך דפנות המנוע, כמו צנרת מים שעוברת בתוך קיר של תנור, לצד שיטות נוספות כמו קירור סרט, קירור מתכלה וקירור בקרינה. שיעור קצר וחיוני להבנת כל מנוע מודרני, מ Merlin ועד Raptor.","related_vehicles":["starship","falcon-9"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('bAUVCn_jw5I', '{"video_id":"bAUVCn_jw5I","title":"Why Starting A Rocket Engine Is So Hard!","year":2023,"length_min":60,"topics_he":["הצתת מנועים","RS25","רצף התנעה"],"summary_he":"מסתבר שהרגע המסוכן ביותר בחיי מנוע רקטי הוא ההתנעה: צריך לצנן את הצנרת, לסובב את משאבות הטורבו ולהצית את התערובת בתזמון של אלפיות שנייה, אחרת המנוע מתפוצץ. הסרטון עובר שלב אחרי שלב על רצף ההתנעה של מנוע המעבורת RS25, ומסביר גם איך מציתים מנוע בחלל, ממצתים חשמליים ועד נוזל מיוחד שמתלקח מעצמו במגע עם חמצן, כמו שעושה Falcon 9. אחרי הצפייה תבינו למה שידורי שיגור מדברים כל כך הרבה על השניות שלפני ההמראה.","related_vehicles":["sls","falcon-9"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('ALiNmzoo1_E', '{"video_id":"ALiNmzoo1_E","title":"How SpaceX Is Upgrading Raptor To Be The Ultimate Rocket Engine!","year":2022,"length_min":19,"topics_he":["Raptor 2","פישוט הנדסי","ראיון עם Elon Musk"],"summary_he":"Elon Musk בעצמו משווה מול המצלמה בין Raptor 1 לבין Raptor 2: הדחף עלה מבערך 185 טונות ליותר מ 230 טונות, ובמקביל צנרת שלמה, חיישנים וחלקים פשוט נמחקו מהעיצוב. זה שיעור נדיר בפילוסופיית ההנדסה של SpaceX: החלק האמין והזול ביותר הוא חלק שלא קיים. צפייה בסרטון היום מסבירה בדיוק איך הגיעו אל Raptor 3 הנקי והחזק שטס כיום על Starship V3.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('Y-xyXDiC92s', '{"video_id":"Y-xyXDiC92s","title":"The Entire Soviet Rocket Engine Family Tree","year":2021,"length_min":94,"topics_he":["מנועים סובייטיים","RD180","היסטוריה של החלל","מחזור סגור"],"summary_he":"מסע של שעה וחצי בעץ המשפחה של כמעט כל מנוע סובייטי שהגיע למסלול: ממנועי טיל R7 שגרסאותיו טסות עד היום על Soyuz, דרך מנועי רקטת הירח N1 שנכשלה במרוץ מול Apollo, ועד משפחת RD170 והמנוע RD180 שהניע במשך שנים דווקא רקטות אמריקאיות. לומדים למה דווקא הסובייטים שלטו בטכנולוגיית המחזור הסגור עשיר החמצן, שבמערב נחשבה בלתי אפשרית. פרויקט תשוקה אמיתי של Tim Dodd, וסרטון ההיסטוריה הטוב ביותר בערוץ.","related_vehicles":[]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('cIQ36Kt7UVg', '{"video_id":"cIQ36Kt7UVg","title":"A conversation with Elon Musk about Starship","year":2019,"length_min":17,"topics_he":["ראיון עם Elon Musk","פלדת אל חלד","היסטוריה של Starship"],"summary_he":"הראיון הראשון של Tim Dodd עם Elon Musk, בשטח הפתוח של Boca Chica בתקופה שבה האתר היה עדיין חולות ואוהלים. Musk מסביר שם לראשונה לעומק למה Starship עברה מסיבי פחמן לפלדת אל חלד: החומר זול פי עשרות ומתמודד הרבה יותר טוב עם חום הכניסה לאטמוספירה. תיעוד היסטורי קצר שממחיש כמה רחוק הגיעה התוכנית מאז.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('t705r8ICkRw', '{"video_id":"t705r8ICkRw","title":"Starbase Tour with Elon Musk [PART 1 // Summer 2021]","year":2021,"length_min":53,"topics_he":["סיור מפעל","Starbase","פילוסופיית הנדסה","ראיון עם Elon Musk"],"summary_he":"החלק הראשון של הסיור המפורסם מקיץ 2021: שעה שלמה עם Elon Musk בין קווי הייצור של Starship. כאן נוסחו חמשת שלבי התכנון המפורסמים שלו: להטיל ספק בדרישות, למחוק חלקים, לפשט, להאיץ, ורק בסוף להוסיף אוטומציה, יחד עם התובנה שבניית מערך ייצור קשה פי 10 עד פי 100 מתכנון המוצר עצמו. חובה לכל מי שרוצה להבין איך SpaceX חושבת.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('SA8ZBJWo73E', '{"video_id":"SA8ZBJWo73E","title":"Starbase Tour with Elon Musk [PART 2 // Summer 2021]","year":2021,"length_min":61,"topics_he":["סיור מפעל","Raptor","Super Heavy","ראיון עם Elon Musk"],"summary_he":"החלק השני של סיור 2021, העשיר ביותר טכנית בסדרה: Musk עונה על שאלות הנדסיות עמוקות ליד מלאי מנועי Raptor, ומסביר למה בוסטר Super Heavy נושא יותר מ 30 מנועים, איך מתמודדים עם כשל מנוע בזמן שיגור ולמה יחס דחף למשקל הוא המדד הקריטי במנוע. השיחה גולשת לפיזיקה, לכלכלת שיגור ולתוכניות מאדים. כאן מבינים איך Musk חושב כשנותנים לו לדבר הנדסה בחופשיות.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('9Zlnbs-NBUI', '{"video_id":"9Zlnbs-NBUI","title":"Starbase Launchpad Tour with Elon Musk [PART 3 // Summer 2021]","year":2021,"length_min":21,"topics_he":["עמדת שיגור","תפיסת בוסטר","Starbase"],"summary_he":"סיום הסדרה בעמדת השיגור: שולחן השיגור, חוות מכלי הדלק והמגדל שהיה אז באמצע בנייה. Musk מתאר תוכנית שנשמעה באותו רגע הזויה לגמרי: לתפוס את הבוסטר החוזר באוויר עם זרועות המגדל, בלי רגלי נחיתה בכלל. הצפייה היום מרתקת במיוחד, כי מאז SpaceX כבר תפסה בוסטרים בדיוק בשיטה הזאת, שוב ושוב.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('3Ux6B3bvO0w', '{"video_id":"3Ux6B3bvO0w","title":"[2022] Elon Musk Explains Updates To Starship And Starbase!","year":2022,"length_min":45,"topics_he":["Starbase","Raptor 2","ראיון עם Elon Musk"],"summary_he":"שנה אחרי הסיור הגדול, Musk עובר עם Tim על כל מה שהשתנה: המעבר למנועי Raptor 2, מגדל התפיסה שהושלם, וההיערכות לניסיון טיסת המסלול הראשון. מעניין במיוחד לראות בדיעבד אילו הערכות זמנים התבדו ואילו החלטות הנדסיות שרדו עד לגרסאות שטסות היום. השלמה טבעית לסדרת 2021 למי שרוצה לעקוב אחרי התפתחות התוכנית.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('aFqjoCbZ4ik', '{"video_id":"aFqjoCbZ4ik","title":"First Look Inside SpaceX''s Starfactory w/ Elon Musk","year":2024,"length_min":64,"topics_he":["Starfactory","ייצור המוני","Raptor 3","ראיון עם Elon Musk"],"summary_he":"סיור ראשון אי פעם בתוך מפעל Starfactory הענק, יום לפני טיסה 4: קווי ייצור שנבנו כדי לייצר ספינות Starship בקצב עצום. Musk מדבר לראשונה בפירוט על Raptor 3, שמוותר על מיגון חיצוני כי תעלות הקירור מודפסות בתוך דפנות המנוע עצמן, ועל הדרך לשימוש חוזר מלא. הצצה נדירה לשאלה איך נראה ייצור המוני של רקטות ענק.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('InJOlT6WdHc', '{"video_id":"InJOlT6WdHc","title":"Join Elon Musk on a tour of Starship just before it launches! (w/ post launch interview)","year":2024,"length_min":33,"topics_he":["טיסה 4","שימוש חוזר","ראיון עם Elon Musk"],"summary_he":"סיור מתחת לרקטה מורכבת בגובה של בערך 120 מטרים יום לפני טיסה 4, ואחריו ראיון שנערך מיד אחרי השיגור. הטיסה הזאת הייתה נקודת מפנה: הבוסטר ביצע לראשונה נחיתה רכה מדויקת על המים, והספינה שרדה לראשונה את הכניסה לאטמוספירה, ו Musk מנתח את המשמעות בזמן אמת. שילוב נדיר של סיור, מתח וניתוח הנדסי טרי.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('rsuqSn7ifpU', '{"video_id":"rsuqSn7ifpU","title":"First Look Inside Blue Origin''s New Glenn Factory w/ Jeff Bezos!","year":2024,"length_min":73,"topics_he":["Blue Origin","New Glenn","BE4","סיור מפעל"],"summary_he":"Jeff Bezos כמעט לא מתראיין, וכאן הוא נותן יותר משעה של סיור הנדסי במפעל New Glenn בפלורידה: בוסטר בקוטר 7 מטרים, שבעה מנועי BE4, ותכנון לשימוש חוזר כבר מהיום הראשון. מאז צילום הסרטון הרקטה הגיעה למסלול בטיסת הבכורה בתחילת 2025, ובנובמבר 2025 הבוסטר גם נחת בהצלחה על ספינה בלב ים. עם זאת, במאי 2026 רקטה שלמה התפוצצה במבחן קרקעי בקייפ קנוורל, והטיסות מושהות בזמן ש Blue Origin מתקנת את הליקוי במנוע ושואפת לחזור לטוס עד סוף 2026. הסיור חשוב גם למי שעוקב אחרי רקטת Vulcan, שטסה עם אותם מנועי BE4.","related_vehicles":["new-glenn","vulcan"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('Hu8SlfmpKM4', '{"video_id":"Hu8SlfmpKM4","title":"First Ever Tour Of Blue Origin''s Massive New Glenn Launch Pad w/ Jeff Bezos!","year":2024,"length_min":46,"topics_he":["Blue Origin","עמדת שיגור","תשתיות שיגור"],"summary_he":"המשך הסיור עם Bezos, הפעם בעמדת השיגור LC36 בקייפ קנוורל: מערכות המים, מגדל השירות וכל התשתית שנדרשת כדי לשגר רקטה בגובה 98 מטרים. Bezos מפתיע ברמת הפירוט הטכני שלו, מדלק המתאן של הבוסטר ועד ניהול מימן נוזלי בדרגה השנייה. חשוב לדעת: במאי 2026 רקטת New Glenn התפוצצה בעמדה הזאת בזמן מבחן קרקעי וגרמה לה נזק כבד, ו Blue Origin משקמת אותה כעת במטרה לחדש את השיגורים עד סוף 2026. השלמה מצוינת לסיור המפעל, שממחישה כמה מהעבודה בתעשיית החלל קורית בכלל על הקרקע.","related_vehicles":["new-glenn"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('EY8nbSwjtEY', '{"video_id":"EY8nbSwjtEY","title":"How Stoke Space''s Unique Rocket Works // Exclusive Tour & Interview","year":2023,"length_min":56,"topics_he":["Stoke Space","שימוש חוזר מלא","מגן חום","סיור מפעל"],"summary_he":"היכרות עם אחת החברות המסקרנות בתעשייה: Stoke Space מפתחת רקטה שכל חלקיה חוזרים לשימוש, כולל הדרגה השנייה. הפתרון שלהם יוצא דופן: מגן חום ממתכת שמקורר באופן אקטיבי על ידי מימן, וטבעת של עשרות תאי בעירה קטנים במקום מנוע פעמון אחד. הסיור עם המנכ״ל Andy Lapsa הוא שיעור אמיתי בחשיבה הנדסית מחוץ לקופסה.","related_vehicles":[]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('7OxNZ-N_3vE', '{"video_id":"7OxNZ-N_3vE","title":"The Underdogs Taking On SpaceX [Stoke Space 2025]","year":2025,"length_min":87,"topics_he":["Stoke Space","Nova","סטארטאפים של חלל"],"summary_he":"ביקור חוזר אצל Stoke Space אחרי שנתיים: רקטת Nova כבר מקבלת צורה, עם מנוע דרגה ראשונה במחזור בעירה מדורגת בזרימה מלאה, מועדון מצומצם שבו חברים רק Raptor וקומץ מנועים בהיסטוריה. כמעט שעה וחצי על ההתקדמות, הכישלונות בדרך והאסטרטגיה של חברה קטנה שמתחרה בענקית. אחד הסרטונים הטובים של 2025 להבנת הדור הבא של תעשיית השיגור.","related_vehicles":[]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('aXoXDp3j850', '{"video_id":"aXoXDp3j850","title":"A chat with Rocket Lab''s CEO Peter Beck about Neutron, Electron recovery and Rocket Lab''s future!","year":2021,"length_min":36,"topics_he":["Rocket Lab","Neutron","Electron","ראיון עם Peter Beck"],"summary_he":"שיחה עם Peter Beck זמן קצר אחרי חשיפת Neutron: למה החברה שנשבעה להישאר ברקטות קטנות עוברת לרקטה בינונית, איך תופסים דרגה ראשונה של Electron באוויר בעזרת מסוק, ולמה Beck אכל חתיכה מהכובע שלו, פשוטו כמשמעו. השיחה רלוונטית היום מתמיד: Neutron מתקרבת לטיסת בכורה שמתוכננת כעת לסוף 2026. הזדמנות להבין את הפילוסופיה ההנדסית הייחודית של Rocket Lab.","related_vehicles":["neutron","electron"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('-8p2JDTd13k', '{"video_id":"-8p2JDTd13k","title":"Complete Guide To Starship: Falcon 9 VS Starship. What''s new? What''s different?","year":2020,"length_min":60,"topics_he":["Starship","Falcon 9","שימוש חוזר","מדריך למתחילים"],"summary_he":"המדריך המסודר ביותר למי שמכיר את Falcon 9 ורוצה להבין מה Starship משנה: השוואה שיטתית של מנועים, דלקים, שיטת הנחיתה, חומרי המבנה והכלכלה של שימוש חוזר מלא. כאן מוסבר לעומק תמרון נפילת הבטן המפורסם, שבו הספינה צונחת על הבטן כמו צנחן חופשי ומתיישרת ברגע האחרון לפני הנחיתה. בסיס מצוין לפני צפייה בסרטוני טיסות הניסוי.","related_vehicles":["starship","falcon-9"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('KA69Oh3_obY', '{"video_id":"KA69Oh3_obY","title":"SLS VS Starship: Why does SLS still exist?!","year":2020,"length_min":49,"topics_he":["SLS","Starship","NASA","מדיניות חלל"],"summary_he":"למה אמריקה בנתה בו זמנית שתי רקטות ירח שונות בתכלית? הסרטון מפרק את השאלה לגורמים: פוליטיקה ותקציבים, פיתוח זהיר ומתועד מול ניסוי וטעייה מהירים, ושתי תפיסות שונות לחלוטין של סיכון. הצפייה בשנת 2026 מרתקת במיוחד, אחרי שרקטת SLS כבר הטיסה אסטרונאוטים סביב הירח באפריל, בזמן שרקטת Starship עדיין מוכיחה את יכולת התדלוק במסלול הנדרשת לנחיתה עצמה.","related_vehicles":["sls","starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('wD3MruC-FTc', '{"video_id":"wD3MruC-FTc","title":"How does ULA''s Vulcan rocket compare to the competition?","year":2024,"length_min":20,"topics_he":["Vulcan","ULA","השוואת רקטות"],"summary_he":"סקירה שיצאה סביב טיסת הבכורה של Vulcan בתחילת 2024: איך הרקטה החדשה של ULA עומדת מול Falcon 9 ומול New Glenn במחיר, בדחף וביכולות, ולמה היא נבנתה סביב מנועי BE4 של Blue Origin. מוסבר גם הרעיון העתידי של ULA למחזר רק את חלק המנועים היקר במקום את כל הבוסטר. נכון להיום Vulcan כבר ביצעה שני שיגורים ביטחוניים עבור ממשלת ארה״ב, אבל אחרי תקלה במאיץ דלק מוצק בשיגור של פברואר 2026 השיגורים הביטחוניים הושהו לחקירה, ו ULA מתכננת חזרה לטיסה עד סוף 2026.","related_vehicles":["vulcan","falcon-9","new-glenn"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('eQZbi8HBRcQ', '{"video_id":"eQZbi8HBRcQ","title":"Starship Version 1 VS Starship Version 2","year":2025,"length_min":7,"topics_he":["Starship V2","עדכוני גרסה","טיסה 7"],"summary_he":"שבע דקות ממוקדות על ההבדלים בין הדור הראשון של Starship לדור השני שעלה לאוויר לראשונה בטיסה 7: מכלים מוארכים שנושאים יותר דלק, דשים קדמיים קטנים יותר שהוזזו הרחק מזרם החום של הכניסה לאטמוספירה, ומערכות פנימיות חדשות. סרטון קצר ומדויק שעוזר להבין למה כל טיסת ניסוי נראית קצת אחרת מקודמתה.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('y_ecCDqTSJs', '{"video_id":"y_ecCDqTSJs","title":"Starship V3: Everything you need to know!","year":2026,"length_min":16,"topics_he":["Starship V3","Raptor 3","תדלוק במסלול"],"summary_he":"כל מה שצריך לדעת על הדור השלישי של Starship, שהחל לטוס במאי 2026: מנועי Raptor 3 עם דחף של בערך 280 טונות כל אחד, גובה כולל של בערך 124 מטרים, וחומרת עגינה לתדלוק במסלול, היכולת שעליה נשענת כל תוכנית הירח והמאדים. זהו הסיכום העדכני ביותר להבנת הרקטה כפי שהיא טסה היום, כולל מה השתנה מדור V2 ולמה.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('T-jf6tTKt3Y', '{"video_id":"T-jf6tTKt3Y","title":"Does Starship REALLY require 15+ launches to land one lunar Starship?!","year":2026,"length_min":105,"topics_he":["תדלוק במסלול","Artemis III","אנליזה הנדסית","Starship"],"summary_he":"בדיקה קפדנית של הטענה שנדרשים יותר מ 15 שיגורים כדי להנחית ספינת Starship אחת על הירח: כמה דלק באמת מעבירה כל מכלית, כמה מתאדה בזמן ההמתנה במסלול, ומה ההבדל בין תרחיש אופטימי לפסימי. Tim בונה את החישוב שלב אחרי שלב כך שגם מי שלא מהנדס יכול לעקוב, והתשובה תלויה בהנחות הרבה יותר משנדמה. הניתוח החשוב ביותר שיש להבנת האתגר האמיתי של תוכנית Artemis.","related_vehicles":["starship","sls"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('o593JmtLyMU', '{"video_id":"o593JmtLyMU","title":"Artemis II: Everything You Need To Know!","year":2026,"length_min":14,"topics_he":["Artemis II","SLS","Orion","טיסה מאוישת"],"summary_he":"מדריך תמציתי שיצא יומיים לפני השיגור באפריל 2026: מי ארבעת האסטרונאוטים, למה הם מקיפים את הירח בלי לנחות עליו, ואילו מערכות נבדקות לראשונה עם בני אדם, ממגן החום של חללית Orion ועד מערכות התמיכה בחיים. המשימה עצמה הסתיימה מאז בהצלחה מלאה אחרי עשרה ימים, והסרטון הוא הדרך המהירה ביותר להבין מה בדיוק הושג שם ולמה זה חשוב בדרך אל Artemis III.","related_vehicles":["sls"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('v6lPMFgZU5Q', '{"video_id":"v6lPMFgZU5Q","title":"Why won''t Starship have an abort system? Should it?!","year":2019,"length_min":49,"topics_he":["מערכות מילוט","בטיחות","טיסה מאוישת"],"summary_he":"דיון יסודי בשאלה שתקבע את עתיד הטיסות המאוישות: איך עובדת מערכת מילוט, איך מעבורת החלל שילמה ביוקר על היעדרה, ולמה SpaceX מהמרת במקום זה על יתירות מנועים ועל מאות טיסות הוכחה ללא צוות, בדומה למטוס נוסעים שצובר אמינות לפני שעולים אליו אנשים. הסרטון משנת 2019, אבל השאלה רק מתחדדת ככל שהרקטה מתקרבת להטסת בני אדם.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('C4VHfmiwuv4', '{"video_id":"C4VHfmiwuv4","title":"How Much Do Rockets Pollute? Are They Bad For Our Air?","year":2020,"length_min":56,"topics_he":["איכות סביבה","פליטות","דלקים רקטיים"],"summary_he":"תשובה מבוססת נתונים לשאלה שכולם שואלים: מה בעצם יוצא מהנחיר, מאדי מים נקיים במנועי מימן ועד פיח שחור בדלקים אחרים, ואיפה זה משפיע על האטמוספירה. הפרופורציה מפתיעה: על כל טונה שפלטה אז תעשיית השיגורים, התעופה האזרחית פלטה מאות אלפי טונות. כלי מצוין לשיחה מושכלת על חלל וסביבה, כולל מה ישתנה אם קצב השיגורים ימשיך לזנק.","related_vehicles":["falcon-9","starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('4m75t4x1V2o', '{"video_id":"4m75t4x1V2o","title":"Why Don''t They Launch Rockets From Mountains Or The Equator?","year":2023,"length_min":24,"topics_he":["פיזיקה של שיגור","מכניקה מסלולית","מיתוסים"],"summary_he":"למה לא משגרים מפסגת הר גבוה או תמיד מקו המשווה? Tim עושה את החשבון: סיבוב כדור הארץ תורם בקו המשווה בערך 460 מטרים בשנייה, תוספת נחמדה אבל שולית לעומת בערך 7,800 מטרים בשנייה שנדרשים כדי להגיע למסלול, וגובה ההר חוסך אפילו פחות. שיעור מהנה באינטואיציה פיזיקלית שמסביר למה לוגיסטיקה וגישה נוחה מנצחות גיאוגרפיה אקזוטית.","related_vehicles":[]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('OBLeg0CvHek', '{"video_id":"OBLeg0CvHek","title":"The best places to watch a rocket launch in Florida!","year":2018,"length_min":16,"topics_he":["צפייה בשיגורים","פלורידה","מדריך למתחילים"],"summary_he":"המדריך הפרקטי הקלאסי לצפייה בשיגור בפלורידה: נקודות התצפית סביב קייפ קנוורל, כמה קילומטרים אתם באמת מכן השיגור בכל נקודה, ומתי הרעש מגיע אליכם, כשהקול מפגר אחרי האור בערך 3 שניות על כל קילומטר. הסרטון ותיק אבל העצות עדיין עובדות, והוא נקודת פתיחה מצוינת לכל מי שמתכנן חופשת שיגורים.","related_vehicles":["falcon-9"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('rJfAD1e8gEY', '{"video_id":"rJfAD1e8gEY","title":"Why do rockets scrub because of weather?","year":2025,"length_min":38,"topics_he":["מזג אוויר","ביטולי שיגור","צפייה בשיגורים"],"summary_he":"למה שיגור מתבטל ברגע האחרון כשהשמיים נראים נקיים לגמרי? מסתבר שרקטה ופלומת הפליטה שלה יוצרות מוליך חשמלי באורך קילומטרים שמסוגל להצית ברק בעצמו. הסרטון עובר על קריטריוני מזג האוויר האמיתיים של השיגור, מרוחות בגבהים ועד ענני סדן ושדות חשמליים, וייתן לכם כלים להבין למה השידור הבא שתצפו בו נעצר בספירה לאחור.","related_vehicles":["falcon-9"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.sources (video_id, doc) values ('C1XAbl19quk', '{"video_id":"C1XAbl19quk","title":"[4K Slow-Mo] Starship Flight 7 Launch & Catch // Clean Audio SUPER CUT!","year":2025,"length_min":29,"topics_he":["טיסה 7","תפיסת בוסטר","הילוך איטי","Super Heavy"],"summary_he":"תיעוד עוצר נשימה באיכות 4K ובהילוך איטי של טיסה 7 מתחילת 2025, כולל התפיסה השנייה אי פעם של בוסטר Super Heavy בזרועות המגדל. הצילומים הנקיים עם הסאונד האמיתי ממחישים את קנה המידה: 33 מנועים נדלקים ורקטה במשקל של בערך 5,000 טונות מתרוממת מהכן. הדרך הטובה ביותר לחוות ברגש את מה שהסרטונים ההנדסיים מסבירים בהיגיון.","related_vehicles":["starship"]}') on conflict (video_id) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('electron', '{"slug":"electron","name_en":"Electron","name_he":"אלקטרון","company_slug":"rocket-lab","status_he":"פעילה: 95 שיגורים עד ספטמבר 2026, מהם 91 הצלחות, 16 שיגורים בשנת 2026 לבדה","intro_he":"Electron של חברת Rocket Lab היא הרקטה הקטנה המצליחה בעולם: צינור שחור ומבריק מקומפוזיט פחמן בגובה 18 מטרים ובקוטר 1.2 מטרים בלבד, שמשקלו בהמראה 13 טונות. לשם השוואה, Falcon 9 של SpaceX גבוהה ממנה בערך פי ארבעה וכבדה ממנה בערך פי ארבעים. Electron נולדה מרעיון פשוט: לוויינים קטנים לא צריכים לחכות לטרמפ על רקטה ענקית, מגיע להם שיגור ייעודי משלהם, למסלול המדויק שהם צריכים ובתאריך שנוח להם. היא ממריאה משני אתרים, חצי האי מאהיה (Mahia) בניו זילנד ומתחם וולופס בווירג''יניה שבארצות הברית, ומסוגלת להציב עד 300 קילוגרמים במסלול נמוך סביב כדור הארץ.\n\nמאז טיסת הבכורה במאי 2017 השלימה Electron עד ספטמבר 2026 כבר 95 שיגורים, מהם 91 הצלחות, והיא כיום הרקטה הפעילה העסוקה בעולם אחרי Falcon 9. בשנת 2025 היא קבעה שיא של 21 שיגורים בשנה אחת, ובשנת 2026 כבר ביצעה 16 שיגורים עד אמצע ספטמבר. שני חידושים הפכו אותה לפורצת דרך: מנוע Rutherford, המנוע המסלולי הראשון בהיסטוריה שמשאבות הדלק שלו מונעות בחשמל מסוללות, ושלב עליון קטן בשם Kick Stage שמחלק לוויינים למסלולים מדויקים כמו מונית. Rocket Lab גם ניסתה לשחזר את השלב הראשון, כולל תפיסה במסוק ואיסוף מהים, ואף הטיסה מחדש מנוע משומש בשנת 2023, אך כיום מרב מאמצי השימוש החוזר מופנים לרקטה הגדולה הבאה שלה, Neutron, שאמורה להמריא לראשונה בסוף 2026.","dims":{"height_m":18,"diameter_m":1.2,"mass_t":13,"payload_leo_t":0.3,"stages":2,"thrust_liftoff_kn":224,"first_flight":"2017-05-25","flights":"95 שיגורים עד ספטמבר 2026: 91 הצלחות, 4 כישלונות, וכל השיגורים מאז סוף 2023 הצליחו ברצף"},"sections":[{"id":"s1_engines","name_he":"תשעת מנועי Rutherford","name_en":"Nine Rutherford Engines","from_m":0,"to_m":1.1,"kind":"engines","desc_he":"בבסיס הרקטה יושבים תשעה מנועי Rutherford: שמונה במעגל ואחד במרכז. כל מנוע מפיק דחף של 24.9 קילוניוטון בגובה פני הים, וביחד הם דוחפים את הרקטה בהמראה עם בערך 224 קילוניוטון. הייחוד הגדול של Rutherford הוא מחזור ההנעה: במקום טורבינה מסובכת שמונעת בגזים חמים, משאבות הדלק והחמצן מסובבות במנועים חשמליים חסרי מברשות שניזונים מסוללות ליתיום פולימר. תחשבו על ההבדל בין מקדחת בנזין למברגה חשמלית: פשוט יותר, אמין יותר, וקל לשלוט בו בדיוק רב. הרכיבים העיקריים של המנוע, כולל תא הבעירה המקורר, המשאבות והשסתומים הראשיים, מודפסים בתלת ממד בתוך בערך 24 שעות. כל מנוע מוטה באמצעות מפעילים אלקטרומכניים כדי להגות את הרקטה, ומארזי הסוללות של השלב הראשון יושבים כאן, קרוב למנועים. Rutherford היה המנוע הראשון בעולם עם משאבות חשמליות שהגיע למסלול.","facts":[{"label_he":"דחף כולל בהמראה","value":"224 קילוניוטון"},{"label_he":"דחף לכל מנוע","value":"24.9 קילוניוטון"},{"label_he":"דחף סגולי","value":"311 שניות"},{"label_he":"מספר מנועים","value":"9"}],"engine":{"name":"Rutherford","count":9,"layout":"octaweb","thrust_kn_each":24.9,"isp_s":311,"cycle_he":"הזנה במשאבות חשמליות מסוללות","propellant_he":"חמצן נוזלי וקרוסין"}},{"id":"s1_tanks","name_he":"מכלי הדלק והחמצן של השלב הראשון","name_en":"Stage 1 Common Bulkhead Tanks","from_m":1.1,"to_m":12.1,"kind":"tank_common","desc_he":"רוב גובהה של הרקטה הוא מכל אחד ארוך מקומפוזיט פחמן, ובתוכו מחיצה משותפת שמפרידה בין שני תאים: חמצן נוזלי בטמפרטורה של בערך מינוס 183 מעלות צלזיוס, וקרוסין מזוקק, דלק שדומה לדלק סילוני. המבנה חסר ציפוי פנימי, כלומר שכבות סיבי הפחמן עצמן אוטמות את הנוזלים, וכך נחסך משקל יקר: מבנה הקומפוזיט קל בבערך 40 אחוזים ממבנה אלומיניום שווה ערך. בהמראה מאוחסנות כאן בערך 9 טונות של דלק וחמצן, רוב משקלה של הרקטה כולה, והן נשרפות בתוך בערך שתי דקות וחצי. המחיצה המשותפת חוסכת גם אורך: במקום שני מכלים נפרדים עם רווח ביניהם, קיר אחד משרת את שניהם, כמו קיר משותף בין שתי דירות. בטיסות שחזור, השלב הזה צולל חזרה לאטמוספירה, נבלם במצנחים ונאסף מהים לבדיקות.","facts":[{"label_he":"כמות דלק וחמצן","value":"בערך 9 טונות"},{"label_he":"זמן בעירת השלב הראשון","value":"בערך 155 שניות"},{"label_he":"קוטר","value":"1.2 מטרים"},{"label_he":"חומר מבנה","value":"קומפוזיט פחמן ללא ציפוי פנימי"}]},{"id":"interstage","name_he":"חוליית הביניים","name_en":"Interstage","from_m":12.1,"to_m":13.1,"kind":"interstage","desc_he":"גליל קצר מקומפוזיט פחמן שמחבר בין שני השלבים, ובתוכו מסתתר הנחיר המורחב של מנוע השלב השני, שמור ומוגן עד רגע ההפרדה. בשניה ה155 של הטיסה, בגובה של בערך 78 קילומטרים, נכנסת לפעולה מערכת ההפרדה הפנאומטית: דוחף לחץ אוויר מרחיק את השלבים זה מזה בעדינות, בלי פירוטכניקה, כמו שני קרונות רכבת שמשתחררים בדחיפה שקטה במקום בפיצוץ. החלק הזה נשאר מחובר לשלב הראשון ונופל איתו חזרה. בטיסות שבהן Rocket Lab משחזרת את הבוסטר, האזור הזה מאכלס את מערכת המצנחים: מצנח ייצוב קטן שנפתח קודם, ואחריו מצנח ראשי שמאט את הנפילה לקראת פגישה רכה עם הים. עיצוב פשוט וקל משקל כזה חשוב במיוחד ברקטה קטנה, שבה כל קילוגרם מיותר במבנה נגרע ישירות מהמטען שאפשר לשאת.","facts":[{"label_he":"גובה הפרדת השלבים","value":"בערך 78 קילומטרים"},{"label_he":"מועד ההפרדה","value":"155 שניות מההמראה"},{"label_he":"שיטת הפרדה","value":"דוחף פנאומטי, ללא פירוטכניקה"}]},{"id":"s2_engine","name_he":"מנוע הוואקום של השלב השני","name_en":"Rutherford Vacuum Engine","from_m":13.1,"to_m":13.8,"kind":"engines","desc_he":"מנוע Rutherford יחיד בגרסת ואקום מניע את השלב השני. זהו כמעט אותו מנוע כמו בשלב הראשון, רק עם נחיר מורחב שמנצל טוב יותר את הריק של החלל: הדחף עולה ל25.8 קילוניוטון והדחף הסגולי מטפס ל343 שניות. גם כאן המשאבות חשמליות, ושלוש סוללות מתח גבוה מזינות אותן. וכאן קורה אחד הטריקים היפים של Electron: שתי סוללות עובדות עד שהן מתרוקנות, ואז השלישית נכנסת לפעולה, והריקות מנותקות ומושלכות בשניה ה388 של הטיסה. זה כמו מטפס הרים שמשליך בלון חמצן ריק בדרך לפסגה: פחות משקל מת, יותר ביצועים. המנוע בוער בערך חמש דקות ומכניס את השלב המשלים והמטען למסלול ראשוני. הטיה אלקטרומכנית בשני צירים מכוונת את הדחף, ומערכת מדחפי גז קר שולטת בגלגול הרקטה.","facts":[{"label_he":"דחף בריק","value":"25.8 קילוניוטון"},{"label_he":"דחף סגולי","value":"343 שניות"},{"label_he":"זמן בעירה","value":"בערך 300 שניות"},{"label_he":"השלכת סוללות ריקות","value":"בשניה ה388 של הטיסה"}],"engine":{"name":"Rutherford Vacuum","count":1,"layout":"single","thrust_kn_each":25.8,"isp_s":343,"cycle_he":"הזנה במשאבות חשמליות מסוללות","propellant_he":"חמצן נוזלי וקרוסין"}},{"id":"s2_tanks","name_he":"מכלי הדלק והחמצן של השלב השני","name_en":"Stage 2 Common Bulkhead Tanks","from_m":13.8,"to_m":15.5,"kind":"tank_common","desc_he":"מכלי השלב השני בנויים באותה שיטה כמו בשלב הראשון: קומפוזיט פחמן עם מחיצה משותפת שמפרידה בין החמצן הנוזלי לקרוסין, בקוטר 1.2 מטרים. בפנים מאוחסנים בערך 2,000 קילוגרמים של דלק וחמצן, שהמנוע צורך במשך בערך חמש דקות. השלב הזה עושה את רוב עבודת ההאצה: השלב הראשון מרים את הרקטה אל מעל האטמוספירה הצפופה, אבל את המהירות המסלולית, בערך 7.8 קילומטרים בשניה, משיג בעיקר השלב השני. תחשבו על קפיצה למים ממקפצה: השלב הראשון הוא הריצה על המסלול, והשלב השני הוא הזינוק עצמו שקובע לאן מגיעים. בזכות המבנה הקל מקומפוזיט, היחס בין מסת הדלק למסת המבנה נשאר גבוה מאוד, תנאי קריטי בשלב עליון של רקטה קטנה, שבה כל קילוגרם עודף במבנה היה נגרע ישירות ממשקל הלוויין.","facts":[{"label_he":"כמות דלק וחמצן","value":"בערך 2,000 ק\"ג"},{"label_he":"קוטר","value":"1.2 מטרים"},{"label_he":"מהירות מסלולית נדרשת","value":"בערך 7.8 קילומטרים בשניה"}]},{"id":"kick_stage","name_he":"השלב המשלים (Kick Stage)","name_en":"Kick Stage","from_m":15.5,"to_m":15.9,"kind":"kick_stage","desc_he":"בין השלב השני למטען יושב שלב שלישי קטן: גובהו 405 מילימטרים בלבד ומשקלו היבש 40 קילוגרמים. הוא מונע במנוע Curie, מנוע מודפס בתלת ממד עם דחף של 120 ניוטון בלבד, שמוזן בלחץ ושורף דו דלק נוזלי שניתן לאחסון ממושך בחלל. היתרון שלו אינו כוח אלא דיוק וגמישות: הוא נדלק וכבה שוב ושוב, מעגל את המסלול, משנה גובה, משחרר כמה לוויינים בכתובות מסלוליות שונות באותה טיסה, ולבסוף מנמיך את עצמו כדי להישרף באטמוספירה ולא להשאיר פסולת חלל. תחשבו על Electron כאוטובוס בין עירוני, ועל השלב המשלים כמונית שאוספת את הנוסעים בתחנה המרכזית ומורידה כל אחד בדיוק בפתח הבית. שישה מדחפי גז קר שולטים בכיוון שלו, ובגרסה המורחבת הוא הופך ל Photon, פלטפורמת לוויין עצמאית של Rocket Lab למשימות עד הירח ומעבר לו.","facts":[{"label_he":"גובה","value":"405 מילימטרים"},{"label_he":"מסה יבשה","value":"40 ק\"ג"},{"label_he":"דחף מנוע Curie","value":"120 ניוטון"},{"label_he":"מדחפי בקרה","value":"6 מדחפי גז קר"}],"engine":{"name":"Curie","count":1,"layout":"single","thrust_kn_each":0.12,"isp_s":null,"cycle_he":"מוזן בלחץ, ניתן להצתה חוזרת","propellant_he":"דו דלק נוזלי שניתן לאחסון"}},{"id":"fairing","name_he":"מעטפת המטען","name_en":"Payload Fairing","from_m":15.9,"to_m":18,"kind":"fairing","desc_he":"החרטום של Electron הוא מעטפת מגן דו קליפתית מקומפוזיט פחמן, באורך 2.5 מטרים וקוטר 1.2 מטרים, ומשקלה 44 קילוגרמים בלבד, פחות ממשקלו של אדם בוגר ממוצע. המעטפת עוטפת גם את השלב המשלים שבבסיסה וגם את הלוויינים שמעליו, ומספקת להם בקרת אקלים וריפוד אקוסטי מיריעות קצף בדרך למעלה: בלי ההגנה הזאת, רעש השיגור העצום והחיכוך באוויר היו הורסים אלקטרוניקה עדינה. הלוויינים מתחברים לפלטת מטען מחלת דבש קומפוזיטית בקוטר של בערך מטר. בשניה ה184 של הטיסה, בגובה של בערך 126 קילומטרים, כשהאוויר כבר דליל מאוד, נפתחת נעילה פנאומטית וקפיצים מסובבים כל חצי קליפה על ציר החוצה, כמו צדפה שנפתחת, והמטען ממשיך את הדרך חשוף לחלל. כך נושאת Electron עד 300 קילוגרמים למסלול נמוך, או עד 200 קילוגרמים למסלול סינכרוני שמש בגובה 500 קילומטרים.","facts":[{"label_he":"אורך","value":"2.5 מטרים"},{"label_he":"מסה","value":"44 ק\"ג"},{"label_he":"הפרדת מעטפת","value":"בשניה ה184, בגובה בערך 126 קילומטרים"},{"label_he":"מטען מרבי","value":"עד 300 ק\"ג למסלול נמוך, עד 200 ק\"ג למסלול סינכרוני שמש"}]}],"fun_facts_he":["מנוע Rutherford קרוי על שם הפיזיקאי הניו זילנדי ארנסט רתרפורד, והוא המנוע הראשון בהיסטוריה שהגיע למסלול עם משאבות דלק חשמליות. את רכיביו העיקריים מדפיסים בתלת ממד בתוך בערך 24 שעות.","Electron משליכה סוללות באמצע הטיסה: שתי סוללות ליתיום פולימר שהתרוקנו מנותקות מהשלב השני ונופלות בשניה ה388, כדי לא לסחוב משקל מת. זה כמו מטפס הרים שמשליך בלון חמצן ריק בדרך לפסגה.","בשנת 2022 תפסה Rocket Lab בוסטר נופל באוויר באמצעות מסוק עם וו ארוך. בסוף הוחלט שפשוט וזול יותר לאסוף את הבוסטר מהים, ומנוע Rutherford משומש אחד כבר הוטס מחדש בהצלחה בשנת 2023.","המבנה כולו, כולל מכלי הדלק, עשוי קומפוזיט פחמן שחור, קל בבערך 40 אחוזים ממבנה אלומיניום מקביל. כל הרקטה שוקלת בהמראה 13 טונות בלבד, בערך כמו אוטובוס עירוני.","ל Electron יש גם גרסה תת מסלולית בשם HASTE, שממריאה מווירג''יניה ומשמשת את ממשלת ארצות הברית לניסויים בטכנולוגיות היפרסוניות."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('falcon-9', '{"slug":"falcon-9","name_en":"Falcon 9","name_he":"פאלקון 9","company_slug":"spacex","status_he":"פעיל בשיא קצבו: מעל 100 שיגורים בשנת 2026 עד ספטמבר, מעל 630 שיגורי Block 5 מצטברים, ומשפחת Falcon כולה חצתה 700 שיגורים","intro_he":"Falcon 9 של חברת SpaceX הוא המשגר העסוק ביותר בעולם כיום, וטיל החלל הראשון בהיסטוריה שלמד לחזור מהחלל ולנחות בעמידה. זהו משגר בעל שני שלבים בגובה של כמעט 70 מטרים, ששני שלביו מונעים בחמצן נוזלי מקורר עמוק ובקרוסין. הרעיון המהפכני שלו פשוט לניסוח וקשה לביצוע: השלב הראשון, שמרכז את רוב העלות של הטיל, אינו נזרק לים אחרי השיגור אלא חוזר, נוחת על ארבע רגליים, עובר בדיקה ומשוגר שוב. הגרסה הנוכחית, Block 5, טסה מאז מאי 2018 והפכה לסוס העבודה של תעשיית החלל העולמית. על בסיסו קיימת גם גרסה כבדה, Falcon Heavy: שלושה גופי שלב ראשון מחוברים זה לצד זה עם 27 מנועים, שהשלימה עד היום 13 שיגורים, האחרון שבהם שיגור טלסקופ החלל Roman של NASA באוגוסט 2026.\n\nקשה להגזים בהשפעה של הטיל הזה על תעשיית החלל: הוא הוזיל דרמטית את מחיר ההגעה למסלול, בנה את קבוצת הלוויינים Starlink, והחזיר לארצות הברית את היכולת לשגר אסטרונאוטים מאדמתה. נכון לספטמבר 2026 חצתה משפחת Falcon את רף 700 השיגורים, מתוכם מעל 630 שיגורים של גרסת Block 5 עם כישלון אחד בלבד, ובשנת 2025 לבדה ביצע הטיל 165 שיגורים, יותר מכל שאר הטילים בעולם גם יחד. שיאן הצי, הבוסטר B1067, השלים באוגוסט 2026 את טיסה מספר 37 שלו, והוא מתקרב לשיא כל הזמנים של מעבורת החלל Discovery, שטסה 39 פעמים.","dims":{"height_m":69.8,"diameter_m":3.7,"mass_t":549,"payload_leo_t":22.8,"thrust_liftoff_kn":7607,"stages":2,"first_flight":"2018-05-11","flights":"מעל 630 שיגורי Block 5 מאז 2018 עם כישלון אחד בלבד; משפחת Falcon כולה חצתה 700 שיגורים בספטמבר 2026, והבוסטר המוביל טס 37 פעמים"},"sections":[{"id":"s1-engines","name_he":"תשעת מנועי Merlin והאוקטהווב","name_en":"Merlin 1D Engines & Octaweb","from_m":0,"to_m":2.4,"kind":"engines","desc_he":"בתחתית הטיל יושבים תשעה מנועי Merlin 1D בסידור שנקרא אוקטהווב: שמונה מנועים במעגל ואחד במרכז, בתוך מבנה אלומיניום מרותך שמעביר את הדחף האדיר אל גוף הטיל. כל מנוע עובד במחזור מחולל גז: טורבינה קטנה שורפת מעט דלק כדי להניע את המשאבות שדוחסות חמצן וקרוסין אל תא הבערה. יחד הם מפיקים בהמראה דחף של 7,607 קילוניוטון, מספיק להרים משקל של כמעט 550 טונות, כמו 350 מכוניות משפחתיות. הסידור הזה מעניק יתרון בטיחותי נדיר: גם אם מנוע אחד כבה בטיסה, השאר יכולים לפצות ולהשלים את המשימה. בנחיתה נדלקים רק אחד עד שלושה מנועים, כי הבוסטר הריק קל מדי לדחף מלא, ומגן חום בבסיס שומר על המנועים בכניסה החוזרת לאטמוספירה.","engine":{"name":"Merlin 1D","count":9,"layout":"octaweb","thrust_kn_each":845,"isp_s":283,"cycle_he":"מחזור מחולל גז","propellant_he":"חמצן נוזלי מקורר עמוק וקרוסין RP1"},"facts":[{"label_he":"דחף כולל בהמראה","value":"7,607 קילוניוטון"},{"label_he":"דחף לכל מנוע בגובה פני הים","value":"845 קילוניוטון"},{"label_he":"יחס דחף למשקל של המנוע","value":"בערך 180, מהגבוהים בעולם"},{"label_he":"מספר מנועים","value":"9"}]},{"id":"s1-fuel-tank","name_he":"מכל הקרוסין של השלב הראשון","name_en":"First Stage RP-1 Tank","from_m":2.4,"to_m":16.8,"kind":"tank_fuel","desc_he":"המכל התחתון בשלב הראשון מחזיק 123.5 טונות של קרוסין טילים מסוג RP1, נוזל שדומה לדלק סילוני אך מזוקק בקפידה רבה יותר. SpaceX מקררת אותו לפני השיגור למינוס 7 מעלות צלזיוס: הקירור מצמיק את הנוזל ומאפשר להכניס יותר דלק לאותו נפח. דפנות המכל עשויות סגסוגת אלומיניום ליתיום קלה, מחוזקות בצלעות אורך פנימיות, והן חלק נושא של גוף הטיל עצמו: אין שלד נפרד, המכל הוא המבנה. פרט הנדסי מרתק: צינור חמצן כפול דופן עובר בדיוק במרכז מכל הקרוסין ומוביל את החמצן הנוזלי מהמכל העליון אל תשעת המנועים שלמטה, כמו קשית ענק שחוצה את המכל לכל אורכו.","facts":[{"label_he":"כמות קרוסין","value":"123.5 טונות"},{"label_he":"טמפרטורת הדלק בשיגור","value":"מינוס 7 מעלות צלזיוס"},{"label_he":"אורך המכל","value":"בערך 14 מטרים"},{"label_he":"חומר המבנה","value":"סגסוגת אלומיניום ליתיום"}]},{"id":"s1-lox-tank","name_he":"מכל החמצן הנוזלי של השלב הראשון","name_en":"First Stage LOX Tank","from_m":16.8,"to_m":39.6,"kind":"tank_ox","desc_he":"המכל הגדול ביותר בטיל תופס בערך שליש מגובהו ומחזיק 287.4 טונות של חמצן נוזלי, יותר מפי שניים ממשקל הקרוסין. למה כל כך הרבה חמצן? כי בחלל אין אוויר, והטיל חייב לשאת בעצמו את החמצן לשריפת הדלק, ביחס של בערך 2.3 קילוגרם חמצן על כל קילוגרם קרוסין. SpaceX מקררת את החמצן למינוס 207 מעלות צלזיוס, הרבה מתחת לנקודת הרתיחה שלו: החמצן הצפוף והדחוס הזה הוא אחד הסודות לביצועים של Block 5. שכבת הכפור הלבנה שרואים על הטיל לפני שיגור נוצרת בדיוק כאן, כשלחות האוויר קופאת על הדופן הקרה. בתוך המכל מעוגנים גם מכלי הליום בלחץ גבוה, ששומרים על לחץ פנימי יציב בזמן שהמכל מתרוקן בטיסה.","facts":[{"label_he":"כמות חמצן נוזלי","value":"287.4 טונות"},{"label_he":"טמפרטורת החמצן","value":"מינוס 207 מעלות צלזיוס"},{"label_he":"אורך המכל","value":"בערך 23 מטרים"},{"label_he":"חלק מגובה הטיל","value":"בערך שליש"}]},{"id":"s1-forward","name_he":"מדור האוויוניקה של הבוסטר","name_en":"Forward Skirt & Avionics","from_m":39.6,"to_m":42.6,"kind":"avionics","desc_he":"בראש השלב הראשון, בין מכל החמצן למחבר השלבים, יושב מדור קצר שמרכז את מוח הבוסטר: מחשבי טיסה בשלושה עותקים שמצביעים ברוב קולות, מערכות ניווט שמשלבות GPS עם חיישני תאוצה, מצברים ומשדרי טלמטריה. כאן מתקבלות ההחלטות של מסע החזרה: מתי להצית מנועים לבלימה, איך להטות את סנפירי הרשת ומתי לפרוס את הרגליים. באזור זה יושבות גם פיות של מדחפי חנקן קר, זרבוביות קטנות שפולטות גז דחוס כדי לסובב את הבוסטר בחלל, שם הסנפירים חסרי תועלת באין אוויר. זה החלק שהופך את הבוסטר מצינור דלק ענק לכלי הטיס המדויק בעולם: הוא חוזר מנסיעה במהירות גבוהה פי שש ממהירות הקול ופוגע בנקודת נחיתה שרוחבה מטרים בודדים.","facts":[{"label_he":"מחשבי טיסה","value":"3 עותקים בהצבעת רוב"},{"label_he":"ניווט","value":"GPS משולב בחיישני תאוצה"},{"label_he":"מדחפי עמדה","value":"חנקן קר דחוס"}]},{"id":"interstage","name_he":"מחבר השלבים","name_en":"Interstage","from_m":42.6,"to_m":47.1,"kind":"interstage","desc_he":"הצילינדר השחור שמחבר את שני השלבים הוא מבנה קומפוזיט: סיבי פחמן על ליבת חלת דבש מאלומיניום, חזק וקל במיוחד. הוא נשאר שחור כי מאז Block 5 ויתרה SpaceX על הצבע, גם לחיסכון במשקל וגם כי הקומפוזיט עומד טוב יותר בחום החזרה. בתוכו מסתתרת זרבובית הענק של מנוע השלב השני, כמו עט בתוך מכסה. ההפרדה בין השלבים נעשית בדחיפה פנאומטית שקטה של בוכנות, בלי חומרי נפץ: אין רסיסים, אין זעזוע לחומרה רגישה, ואפשר לבדוק את המנגנון על הקרקע שוב ושוב לפני כל טיסה. המחבר נשאר צמוד לבוסטר וחוזר איתו לנחיתה, וסמוך לראשו מותקנים ארבעת סנפירי הרשת שמנווטים את הדרך חזרה. אורכו 4.5 מטרים, והוא מהחלקים היחידים בטיל שאינם מכלים.","facts":[{"label_he":"אורך","value":"4.5 מטרים"},{"label_he":"חומר","value":"סיבי פחמן על חלת דבש אלומיניום"},{"label_he":"הפרדת שלבים","value":"בוכנות פנאומטיות, ללא פירוטכניקה"}]},{"id":"s2-engine","name_he":"מנוע הוואקום MVac","name_en":"Merlin Vacuum (MVac) Engine","from_m":47.1,"to_m":48,"kind":"engines","desc_he":"השלב השני מונע במנוע Merlin יחיד בגרסת ואקום: אותה ליבה של מנועי הבוסטר, אבל עם זרבובית ענקית שמותאמת לריק של החלל. יחס ההתפשטות שלה, 165:1, הוא מהגדולים שנבנו אי פעם למנוע קרוסין, וההרחבה הזו מתורגמת ליעילות: המנוע סוחט מכל קילוגרם דלק יותר דחף, עם אימפולס סגולי של 348 שניות לעומת 283 שניות בגובה פני הים. שולי הזרבובית עשויים סגסוגת ניוביום שמתקררת בקרינה בלבד, והם זוהרים בכתום עמום בזמן הבערה. המנוע יודע להידלק שוב ושוב בחלל, יכולת קריטית להצבת לוויינים במסלולים מדויקים ולהורדת השלב מהמסלול בסוף המשימה. בשיגור עצמו הזרבובית כולה מקופלת בתוך מחבר השלבים שמתחת, ולכן בציור החתך המנוע כמעט אינו נראה מבחוץ.","engine":{"name":"Merlin Vacuum (MVac)","count":1,"layout":"single","thrust_kn_each":981,"isp_s":348,"cycle_he":"מחזור מחולל גז","propellant_he":"חמצן נוזלי וקרוסין RP1"},"facts":[{"label_he":"דחף בריק","value":"981 קילוניוטון"},{"label_he":"אימפולס סגולי","value":"348 שניות"},{"label_he":"יחס התפשטות הזרבובית","value":"165:1"},{"label_he":"זמן בערה במשימה טיפוסית","value":"בערך 397 שניות"}]},{"id":"s2-fuel-tank","name_he":"מכל הקרוסין של השלב השני","name_en":"Second Stage RP-1 Tank","from_m":48,"to_m":51.4,"kind":"tank_fuel","desc_he":"מעל המנוע יושב מכל הקרוסין של השלב השני, גרסה מקוצרת של מכל הדלק הגדול שבבוסטר: אותה סגסוגת אלומיניום ליתיום, אותם כלי ייצור ואותן שיטות ריתוך בערבול וחיכוך. ההחלטה לבנות את שני השלבים באותו קוטר ובאותה טכנולוגיה חוסכת לחברת SpaceX עלויות ייצור ומורידה סיכונים הנדסיים. המכל מחזיק 32.3 טונות של קרוסין מקורר. השלב השני הוא היחיד בטיל שאינו חוזר לשימוש: אחרי שהשלים את תפקידו הוא מבצע בערת האטה ונשרף באטמוספירה מעל אוקיינוס, או מועבר למסלול קבורה גבוה. זו הפשרה המחושבת של Falcon 9: להשקיע הכל בהחזרת הבוסטר, שמרכז את תשעת המנועים ואת רוב העלות, ולשמור על השלב השני פשוט, קל וזול ככל האפשר.","facts":[{"label_he":"כמות קרוסין","value":"32.3 טונות"},{"label_he":"אורך המדור","value":"בערך 3.5 מטרים"},{"label_he":"שימוש חוזר","value":"אין, שלב לשימוש יחיד"}]},{"id":"s2-lox-tank","name_he":"מכל החמצן של השלב השני","name_en":"Second Stage LOX Tank","from_m":51.4,"to_m":56.6,"kind":"tank_ox","desc_he":"המכל העליון בשלב השני מחזיק 75.2 טונות של חמצן נוזלי מקורר עמוק, והוא בנוי בדיוק כמו אחיו הגדול שבבוסטר: כיפה משותפת מפרידה בינו לבין מכל הקרוסין שמתחתיו, וצינור ירידה מרכזי מוביל את החמצן דרך מכל הדלק אל המנוע. בתוך המכל מעוגנים מכלי הליום עטופים בסיבי פחמן, המכונים COPV, שמחזיקים לחץ אדיר ותפקידם לשמור על לחץ קבוע במכלים בזמן שהם מתרוקנים. בקצה העליון של השלב יושבת האוויוניקה שלו: המחשב שמנהל את הטיסה מרגע ההפרדה ועד שחרור הלוויין. פינה היסטורית: שתי התקלות היחידות בתולדות הטיל, ב2015 וב2016, החלו דווקא סביב מכלי ההליום שבמכל הזה, והלקחים מהן עיצבו את האמינות יוצאת הדופן של Block 5 של היום.","facts":[{"label_he":"כמות חמצן נוזלי","value":"75.2 טונות"},{"label_he":"טמפרטורה","value":"מינוס 207 מעלות צלזיוס"},{"label_he":"מכלי לחץ פנימיים","value":"מכלי הליום מסוג COPV"}]},{"id":"fairing","name_he":"חרטום המטען","name_en":"Payload Fairing","from_m":56.6,"to_m":69.8,"kind":"fairing","desc_he":"הקונוס שבראש הטיל בנוי משני חצאים של קליפת סיבי פחמן על ליבת אלומיניום, והוא שומר על הלוויין מרוח, מחום ומרעש בדרך אל החלל. גובהו 13.2 מטרים וקוטרו 5.2 מטרים: חלל פנימי שיכול לבלוע אוטובוס עירוני שלם. בערך שלוש דקות לתוך הטיסה, כשהאוויר כבר דליל מכדי להזיק, שני החצאים נפתחים כמו צדפה ונפרדים, וכל חצי צונח חזרה בעזרת מדחפי גז קר ומצנח מתמרן עד נגיעה רכה במים, שם אוספת אותו ספינה ייעודית. גם כאן פועלת מהפכת השימוש החוזר: חצי חרטום אחד כבר טס 34 פעמים. בתוך החרטום יושב הלוויין על מתאם מטען שמחבר אותו לשלב השני, ובמשימות מאוישות מוחלף החרטום כולו בחללית Dragon עם האסטרונאוטים.","facts":[{"label_he":"גובה","value":"13.2 מטרים"},{"label_he":"קוטר","value":"5.2 מטרים"},{"label_he":"מועד ההפרדה","value":"בערך שלוש דקות אחרי השיגור"},{"label_he":"שיא שימוש חוזר לחצי חרטום","value":"34 טיסות"}]},{"id":"grid-fins","name_he":"סנפירי רשת מטיטניום","name_en":"Titanium Grid Fins","from_m":45,"to_m":47,"kind":"gridfins","overlay":true,"desc_he":"ארבעה סנפירים בצורת רשת סריג מקופלים לאורך ראש הבוסטר, ונפרסים כשמגיע הזמן לחזור הביתה. סנפיר רשת עובד אחרת מכנף רגילה: האוויר זורם דרך עשרות תאים קטנים, וזה מעניק שליטה מצוינת דווקא במהירויות העל קוליות שבהן כנפיים רגילות מאבדות יעילות. כל סנפיר מוטה על ידי מערכת הידראולית ומכוון את הבוסטר הנופל כמו הגאים של מטוס, עד דיוק של מטרים בודדים בנקודת הנחיתה. בגרסת Block 5 הסנפירים עשויים יציקת טיטניום מלאה, אחרי שסנפירי האלומיניום הקודמים נטו להתלקח בחום הכניסה החוזרת. הטיטניום עומד בחום בלי שום ציפוי מגן, ולכן הסנפירים חוזרים מהטיסה מוכנים מיד לטיסה הבאה. גודלו של כל סנפיר בערך 2 מטרים על 1.5 מטרים, כמו דלת רחבה.","facts":[{"label_he":"מספר סנפירים","value":"4"},{"label_he":"חומר","value":"יציקת טיטניום ללא ציפוי"},{"label_he":"גודל כל סנפיר","value":"בערך 2 על 1.5 מטרים"},{"label_he":"הנעה","value":"הידראולית"}]},{"id":"landing-legs","name_he":"רגלי הנחיתה","name_en":"Landing Legs","from_m":0,"to_m":10.5,"kind":"legs","overlay":true,"desc_he":"ארבע רגליים ענקיות מסיבי פחמן על ליבת חלת דבש מאלומיניום צמודות לגוף הבוסטר לאורך כל הטיסה, ונפתחות בשניות האחרונות לפני הנגיעה בקרקע. בפרישה מלאה הן יוצרות בסיס שרוחבו 18 מטרים, כי בלי בסיס רחב, טיל גבוה ודק כמו בניין של 14 קומות היה מתהפך מכל משב רוח או גל בים. כל רגל נפתחת בלחץ הליום וננעלת במקומה, ובתוכה ליבת כתישה מתכלה שסופגת נחיתות קשות, כמו אזור הקימוט במכונית. בגרסת Block 5 שודרגו הרגליים כך שצוות הנמל יכול לקפל אותן חזרה בתוך שעות במקום לפרק כל רגל בנפרד, שדרוג שקיצר את זמן ההכנה לטיסה הבאה מחודשים לימים ספורים. משקלן הכולל בערך 2 טונות.","facts":[{"label_he":"מספר רגליים","value":"4"},{"label_he":"מוטת פרישה","value":"18 מטרים"},{"label_he":"משקל כולל","value":"בערך 2 טונות"},{"label_he":"מנגנון פתיחה","value":"לחץ הליום עם נעילה עצמית"}]}],"fun_facts_he":["הבוסטר B1067 טס כבר 37 פעמים נכון לאוגוסט 2026, יותר מכל כלי שיגור אחר בהיסטוריה, והוא בדרך לשבור את שיא 39 הטיסות של מעבורת החלל Discovery.","בשנת 2025 שוגר Falcon 9 165 פעמים: בממוצע שיגור אחד כמעט בכל יומיים, יותר מכל שאר טילי העולם גם יחד.","החמצן הנוזלי מקורר למינוס 207 מעלות צלזיוס, קרוב לנקודת הקיפאון שלו: הקירור העמוק מכווץ את הנוזל ומאפשר לדחוס לאותם מכלים עוד עשרות טונות של חומר הנעה.","חצאי החרטום שמגנים על הלוויין נאספים מהים אחרי כל שיגור וטסים שוב: חצי חרטום אחד כבר השלים 34 טיסות.","הבוסטר נוחת על ספינה רובוטית בגודל מגרש כדורגל באמצע האוקיינוס: מתוך 640 ניסיונות נחיתה עד ספטמבר 2026, 634 הצליחו."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('neutron', '{"slug":"neutron","name_en":"Neutron","name_he":"נייטרון","company_slug":"rocket-lab","status_he":"בפיתוח, טרם טסה. טיסת בכורה מתוכננת לרבעון הרביעי של 2026 מוואלופס, וירג''יניה.","intro_he":"Neutron היא הרקטה הגדולה החדשה של Rocket Lab, החברה שהפכה לשם דבר בזכות רקטת Electron הקטנה שכבר ביצעה יותר משישים שיגורים. מדובר במשגר דו שלבי לעומס בינוני: גובה 43 מטרים בקירוב, קוטר 7 מטרים בבסיס, והוא בנוי כמעט כולו מסיבי פחמן, מה שהופך אותו לרקטה הגדולה בעולם מחומרים מרוכבים. תשעה מנועי Archimedes שורפים מתאן נוזלי וחמצן נוזלי ומפיקים 6,600 קילוניוטון בהמראה, מספיק כדי לשאת עד 13 טונות למסלול נמוך בתצורה רב פעמית, או 15 טונות בתצורה חד פעמית. Neutron נועדה להתחרות ישירות ברקטת Falcon 9 של SpaceX בשוק שיגורי הקונסטלציות, וממשלת ארצות הברית כבר צירפה אותה למאגר המשגרים של משימות הביטחון הלאומי בתוכנית NSSL.\n\nהקסם ההנדסי של Neutron הוא בכך שכמעט שום דבר לא נזרק: השלב הראשון, כולל חרטום הפיירינג שנפתח כמו פה של היפופוטם ונסגר בחזרה, חוזר לנחיתה אנכית כיחידה אחת, ורק השלב השני הקל והזול נשאר בחלל. נכון לספטמבר 2026 הרקטה טרם טסה: טיסת הבכורה מתוכננת לרבעון הרביעי של 2026 מאתר Launch Complex 3 בוואלופס, וירג''יניה, וחלון הזמן הזה הולך ומצטמצם. רוב החומרה כבר בנויה: הפיירינג עבר הסמכה מלאה והגיע לאתר השיגור, מנועי Archimedes צברו מעל 400 הצתות ניסוי, ומכלי השלב הראשון נמצאים בשלבי ייצור אחרונים אחרי שמכל נבקע בבדיקת לחץ בינואר 2026 ודחה את הלוח. בטיסה הראשונה לא יתבצע ניסיון נחיתה אלא הנחתה רכה בים, והמטרה המוצהרת: להגיע למסלול כבר בניסיון הראשון.","dims":{"height_m":42.8,"diameter_m":7,"mass_t":480,"payload_leo_t":13,"stages":2,"thrust_liftoff_kn":6600,"first_flight":"טרם טסה. היעד: רבעון רביעי של 2026","flights":"0 שיגורים עד ספטמבר 2026. כל החומרה בבדיקות הסמכה אחרונות לקראת טיסת הבכורה"},"sections":[{"id":"s1-engines","name_he":"מנועי השלב הראשון: תשעה Archimedes","name_en":"First Stage Engines (9x Archimedes)","from_m":0,"to_m":2.2,"kind":"engines","desc_he":"בתחתית הרקטה יושבים תשעה מנועי Archimedes, שמונה במעגל ואחד במרכז. כל מנוע שורף מתאן נוזלי וחמצן נוזלי ומפיק עד 733 קילוניוטון של דחף, וביחד: 6,600 קילוניוטון בהמראה, מספיק כדי להרים רקטה במשקל 480 טונות בקירוב ולהאיץ אותה לשמיים. Archimedes פועל במחזור בעירה מדורגת עשירת חמצן (ORSC), שיטה סגורה שממחזרת את הגז שמניע את המשאבות אל תא הבעירה, ולכן כמעט לא מבזבזת דלק. Rocket Lab בחרה בכוונה להפעיל את המנוע בעומסים נמוכים מהמקסימום ההנדסי שלו, כמו נהג שנשאר מתחת לקו האדום של הסל\"ד כדי שהמנוע יחזיק שנים: כך המנוע מתאים לשימוש חוזר מהיר. חלקים רבים בו, כולל בתי המשאבות ותא הבעירה, מיוצרים בהדפסה תלת ממדית. עד ספטמבר 2026 צברו מנועי Archimedes מעל 400 הצתות ניסוי במתקן Stennis של NASA.","facts":[{"label_he":"דחף לכל מנוע","value":"733 קילוניוטון"},{"label_he":"דחף כולל בהמראה","value":"6,600 קילוניוטון"},{"label_he":"אימפולס סגולי בגובה פני הים","value":"329 שניות"},{"label_he":"מצערת מזערית","value":"65 אחוזים"},{"label_he":"הצתות ניסוי עד ספטמבר 2026","value":"מעל 400"}],"engine":{"name":"Archimedes","count":9,"layout":"octaweb","cycle_he":"בעירה מדורגת עשירת חמצן (ORSC)","propellant_he":"מתאן נוזלי וחמצן נוזלי","thrust_kn_each":733,"isp_s":329}},{"id":"legs","name_he":"רגלי נחיתה","name_en":"Landing Legs","from_m":0,"to_m":9,"kind":"legs","overlay":true,"desc_he":"ארבע רגלי נחיתה מקופלות בצמוד לאורך הבסיס הרחב של הרקטה, בדומה לפתרון של Falcon 9, ונפתחות כלפי חוץ שניות לפני הנגיעה בקרקע. הבסיס המתרחב בקוטר 7 מטרים מעניק לרקטה עמידה יציבה במיוחד, כמו פירמידה קטומה שקשה להפיל. שתי אפשרויות נחיתה מתוכננות: חזרה עד משטח הנחיתה שליד אתר השיגור בווירג''יניה, או נחיתה בלב ים על ספינה בשם Return On Investment, אונייה באורך 122 מטרים שמותאמת בימים אלה לתפקיד עם מיגון נגד להבות וציוד אוטונומי שיתפוס ויאבטח את הבוסטר שנחת. בטיסת הבכורה לא יתבצע ניסיון נחיתה כלל: הבוסטר יתרגל את כל שלבי החזרה ויסיים בהנחתה רכה על פני הים, לאיסוף נתונים לקראת הנחיתות האמיתיות.","facts":[{"label_he":"מספר רגליים","value":"4"},{"label_he":"קוטר בסיס הרקטה","value":"7 מטרים"},{"label_he":"אורך ספינת הנחיתה","value":"122 מטרים"}]},{"id":"s1-thrust","name_he":"מבנה הדחף","name_en":"Thrust Structure","from_m":2.2,"to_m":3.6,"kind":"thrust_structure","desc_he":"מעל המנועים נמצא מבנה הדחף, שלד הנדסי שתפקידו לקחת 6,600 קילוניוטון של כוח ולפזר אותם באופן אחיד אל גוף סיבי הפחמן, כמו שלדת מכונית שמעבירה את כוח המנוע אל הכביש בלי להתעקם. שמונת המנועים ההיקפיים והמנוע המרכזי מעוגנים אליו בנקודות שמאפשרות לכל מנוע להטות את עצמו (גימבל) ולהטות כך את כל הרקטה בציר העלרוד, הסבסוב והגלגול. החלק התחתון מצופה במגן חום רב פעמי: בדרך חזרה לכדור הארץ הבוסטר חודר לאטמוספירה כשהתחתית פונה קדימה, ומבנה הדחף הוא שסופג את עיקר החום. טכנולוגיית ההגנה התרמית הזו פותחה והוכחה בטיסה על הבוסטרים של רקטת Electron הקטנה, שחזרו בשלום ממהירויות קרובות למסלוליות.","facts":[{"label_he":"כוח מועבר בהמראה","value":"6,600 קילוניוטון"},{"label_he":"מנועים מעוגנים","value":"9"},{"label_he":"היגוי","value":"הטיית מנועים (גימבל)"}]},{"id":"s1-tanks","name_he":"מכלי הדלק של השלב הראשון","name_en":"Stage 1 Propellant Tanks","from_m":3.6,"to_m":26,"kind":"tank_common","desc_he":"רוב גובהו של השלב הראשון הוא בעצם מכל ענק אחד מסיבי פחמן, שבתוכו מחיצה משותפת (common bulkhead) מפרידה בין החמצן הנוזלי לבין המתאן הנוזלי. במקום שני מכלים נפרדים עם מרווח ביניהם, המחיצה המשותפת חוסכת מבנה ומשקל, כמו תרמוס עם שתי קומות שחולקות תחתית אחת. הדפנות מיוצרות בהנחה אוטומטית של סרטי סיבי פחמן, והן שהופכות את Neutron לרקטה הגדולה בעולם מחומרים מרוכבים: חומר חזק כמו פלדה אך קל ממנה בהרבה, וכל קילוגרם שנחסך במבנה הופך לקילוגרם נוסף של מטען. שימו לב לצורה: הגוף מתחדד בהדרגה מקוטר 7 מטרים בבסיס לקוטר צר יותר למעלה. הצורה הזו אינה רק אווירודינמיקה של עלייה, היא הופכת את הבוסטר כולו לגוף מעופף שמייצר עילוי בדאייה חזרה לנחיתה. בינואר 2026 נבקע מכל של השלב הראשון בבדיקת לחץ עם מים, אירוע שדחה את טיסת הבכורה לסוף השנה.","facts":[{"label_he":"קוטר בבסיס","value":"7 מטרים"},{"label_he":"אורך אזור המכלים","value":"22 מטרים בקירוב"},{"label_he":"חומר","value":"פולימר משוריין בסיבי פחמן (CFRP)"},{"label_he":"מבנה","value":"מכל משותף עם מחיצה אחת"}]},{"id":"s2-engine","name_he":"מנוע השלב השני: Archimedes Vacuum","name_en":"Archimedes Vacuum Engine","from_m":26,"to_m":28.3,"kind":"engines","desc_he":"עמוק בתוך המפתח (interstage) מסתתר מנוע Archimedes Vacuum יחיד, גרסת החלל של מנוע השלב הראשון. ההבדל העיקרי: פעמון פליטה גדול בהרבה. בריק אין לחץ אוויר שכולא את סילון הגזים, ולכן פעמון רחב מנצל את התפשטותם עד הסוף ומעלה את היעילות לדחף של עד 900 קילוניוטון ואימפולס סגולי של 365 שניות. המנוע יודע להידלק מחדש שוב ושוב במסלול, יכולת קריטית לפריסת קונסטלציות: מדליקים, משחררים לוויין במסלול אחד, כבים, מחליקים בשיוט, ומדליקים שוב במסלול אחר, כמו אוטובוס שעוצר בכמה תחנות ומוריד נוסעים בכל אחת. עד רגע ההפרדה המנוע חוסה כולו בתוך גוף השלב הראשון, מוגן לגמרי מרוח, מחום ומעומסי הטיסה, ולכן אפשר היה לתכנן אותו עדין וקל יותר ממנוע חשוף.","facts":[{"label_he":"דחף בריק","value":"900 קילוניוטון"},{"label_he":"אימפולס סגולי בריק","value":"365 שניות"},{"label_he":"הצתות חוזרות במסלול","value":"כן, מספר פעמים"}],"engine":{"name":"Archimedes Vacuum","count":1,"layout":"single","cycle_he":"בעירה מדורגת עשירת חמצן, מותאם לריק","propellant_he":"מתאן נוזלי וחמצן נוזלי","thrust_kn_each":900,"isp_s":365}},{"id":"fairing","name_he":"פיירינג צמוד: Hungry Hippo","name_en":"Hungry Hippo Captive Fairing","from_m":26,"to_m":42.8,"kind":"fairing","overlay":true,"desc_he":"הפיירינג של Neutron קיבל את הכינוי היפופוטם רעב (Hungry Hippo) כי הוא נפתח כמו לסת ענקית: שתי כיפות המחוברות בצירים אל גוף השלב הראשון ולעולם אינן עוזבות אותו. בתוך המבנה, סביב מפתח מוארך באורך 13 מטרים בקירוב, תלוי השלב השני עם המטען. בסיום עבודת השלב הראשון הלסתות נפתחות, השלב השני משוחרר וממשיך למסלול, הלסתות נסגרות בחזרה, והבוסטר חוזר לנחיתה שלם, כולל הפיירינג. כך נחסך הצורך לייצר פיירינג חדש לכל טיסה או לדוג אותו מהים בספינות. בהסמכה שהושלמה בדצמבר 2025 נפתחו הכיפות ונסגרו בתנאים מדמי טיסה בתוך 1.5 שניות בלבד, פחות מחצי מהזמן הנדרש להפרדה מוצלחת, ונשאו עומס של 1,225 קילוניוטון, שווה ערך למשקל של 125 טונות, המדמה את שיא הלחץ האווירודינמי בטיסה. בתחילת 2026 הגיע הפיירינג המוסמך לאתר השיגור בווירג''יניה.","facts":[{"label_he":"קוטר מטען מרבי","value":"5.5 מטרים"},{"label_he":"זמן פתיחה וסגירה","value":"1.5 שניות"},{"label_he":"עומס הסמכה","value":"1,225 קילוניוטון"},{"label_he":"אורך המפתח הפנימי","value":"13 מטרים בקירוב"},{"label_he":"השלמת הסמכה","value":"דצמבר 2025"}]},{"id":"canards","name_he":"כנפונים קדמיים (Canards)","name_en":"Canards","from_m":27.4,"to_m":29.4,"kind":"flaps","overlay":true,"desc_he":"ארבעה כנפונים קדמיים בולטים מגוף השלב הראשון ממש מתחת לקו הפתיחה של הפיירינג. בעלייה הם צמודים ושקטים, והעבודה האמיתית שלהם מתחילה בדרך חזרה: כשהבוסטר חודר לאטמוספירה כשתחתיתו קדימה, הכנפונים פועלים כהגאים שמכוונים את הגוף המתחדד. יחד עם רצועות אורך אווירודינמיות (strakes) לאורך הגוף, הבוסטר כולו הופך לגוף דואה שמייצר עילוי של ממש ומקטין את העומס התרמי. בניגוד לסנפירי הסבכה של Falcon 9, שבעיקר בולמים ומייצבים את הנפילה, הכנפונים של Neutron מייצרים עילוי אמיתי ומאפשרים לבוסטר לדאות חזרה עד נקודת הנחיתה תוך חיסכון ניכר בדלק. זה ההבדל בין ליפול עם מצנח מכוון לבין לחזור הביתה בדאון קטן עם הגה.","facts":[{"label_he":"מספר כנפונים","value":"4"},{"label_he":"גובה התקנה","value":"28 מטרים בקירוב מהבסיס"}]},{"id":"s2-tanks","name_he":"מכלי השלב השני","name_en":"Stage 2 Tanks","from_m":28.3,"to_m":36.3,"kind":"tank_common","desc_he":"השלב השני של Neutron תוכנן סביב שתי מילים: קל וזול. הוא היחיד ברקטה שאינו חוזר לשימוש, ולכן כל גרם בו נחשב. גם כאן שני החומרים, מתאן נוזלי וחמצן נוזלי, יושבים במכל סיבי פחמן אחד עם מחיצה משותפת, בקוטר 4.9 מטרים, כשאורך השלב כולו 11.5 מטרים. הטריק ההנדסי הגדול: השלב תלוי מהצווארון העליון שלו בתוך השלב הראשון, כמו שקית שתלויה על וו במקום עמוד שנושא משקל. מבנה שתלוי במתיחה ועטוף מכל צדדיו אינו צריך לעמוד ברוח, בחיכוך ובעומסי האוויר של הטיסה, שאותם סופגים השלב הראשון והפיירינג במקומו, ולכן דפנותיו דקות במיוחד. התוצאה לפי Rocket Lab היא אחד השלבים העליונים הקלים ביותר שנבנו ביחס לגודלם, וכל קילוגרם שנחסך כאן מתורגם כמעט אחד לאחד לתוספת מטען.","facts":[{"label_he":"קוטר","value":"4.9 מטרים"},{"label_he":"אורך השלב המלא","value":"11.5 מטרים"},{"label_he":"חומר","value":"סיבי פחמן, מחיצה משותפת"},{"label_he":"שימוש","value":"חד פעמי, אינו חוזר"}]},{"id":"s2-avionics","name_he":"אווניוניקה ונקודת התלייה","name_en":"Stage 2 Avionics & Hang Point","from_m":36.3,"to_m":37.8,"kind":"avionics","desc_he":"כאן, בצווארון שממנו תלוי השלב השני על ממשק הרכבה קשיח בתוך המפתח, מרוכז חדר הבקרה של הרקטה: מחשבי טיסה, משדרי רדיו בפס S לטלמטריה ולווידאו, חיישני ניווט, צנרת נוזלים, ומערכת בטיחות טיסה אוטונומית (AFSS) שמשווה בכל רגע את מצב הרקטה מול כללי המשימה ויכולה להפסיק את הטיסה בעצמה. לכל שלב יש מחשבים משלו, כך שאחרי ההפרדה כל אחד טס באופן עצמאי. ההפרדה עצמה פנאומטית: בוכנות גז דוחפות את השלב השני החוצה בבת אחת, בלי פירוטכניקה, מה שמקטין זעזועים למטען ומונע כל סיכון של פגיעה חוזרת. מדחפי גז קר מייצבים את השלב בשיוט ובסיבוב תרמי איטי. הדיוק המובטח ללקוחות: סטייה של עד 0.15 מעלות בנטיית המסלול ועד 15 קילומטרים בגובהו.","facts":[{"label_he":"דיוק נטיית מסלול","value":"±0.15 מעלות"},{"label_he":"דיוק גובה מסלול","value":"±15 קילומטרים"},{"label_he":"שיטת הפרדה","value":"פנאומטית, ללא פירוטכניקה"}]},{"id":"payload-bay","name_he":"תא המטען","name_en":"Payload Bay","from_m":37.8,"to_m":41.3,"kind":"payload","desc_he":"על חרטום השלב השני יושב חרוט נשיאה (Payload Support Structure) מחומרים מרוכבים, שמסתיים בטבעת אלומיניום עם מעגל ברגים תקני בקוטר 1,575 מילימטרים, ואופציה רחבה בקוטר 2,616 מילימטרים. לכאן מתחברים הלוויינים, ישירות או דרך מתאמים ומפזרי לוויינים לשיגורים מרובי מטענים. נפח המטען מרשים: עד 5.5 מטרים קוטר, רחב יותר מהפיירינג של Falcon 9, ולכן מתאים גם ללוויינים גדולים וגם לערימות של עשרות לוויינים. היכולות: עד 13 טונות למסלול נמוך כשהבוסטר נוחת בים, 15 טונות בתצורה חד פעמית, 8.5 טונות כשהבוסטר חוזר עד אתר השיגור, ובקירוב 2 טונות אל הירח. לשם המחשה, 13 טונות הן משקל של אוטובוס עירוני שלם. שתי דלתות גישה מאפשרות לצוותי הלוויין לטפל במטען עד סמוך לשיגור, בסביבה מבוקרת אקלים ונקייה.","facts":[{"label_he":"קוטר מעטפת מטען","value":"עד 5.5 מטרים"},{"label_he":"למסלול נמוך, נחיתת בוסטר בים","value":"13 טונות"},{"label_he":"בתצורה חד פעמית","value":"15 טונות"},{"label_he":"עם חזרה לאתר השיגור","value":"8.5 טונות"},{"label_he":"אל הירח","value":"2 טונות"}]},{"id":"nose","name_he":"חוד החרטום","name_en":"Nose Tip","from_m":41.3,"to_m":42.8,"kind":"nosecone","desc_he":"קצה החרטום הוא החלק הסגור בראש הפיירינג, החוד האווירודינמי שחותך את האטמוספירה בדרך למעלה ומגן על המטען מחום ומלחץ. בניגוד כמעט לכל רקטה אחרת בעולם, החוד הזה לא נזרק לים ולא מתרסק: הוא חלק בלתי נפרד מהשלב הראשון, נשאר סגור מעל נקודת הציר של שתי הלסתות, וחוזר איתן הביתה לנחיתה, מוכן לטיסה הבאה. הצורה המעוגלת נבחרה בקפידה כפולה: בעלייה היא ממזערת את הגרר, ובדרך חזרה, כשהרקטה טסה תחתית קדימה, החרטום הסגור משלים את קו הגוף שמאפשר לבוסטר לדאות באוויר. זה ההבדל בין לזרוק את האף של מטוס אחרי כל טיסה לבין פשוט להנמיך אותו ולנחות.","facts":[{"label_he":"אורך החוד","value":"1.5 מטרים בקירוב"},{"label_he":"אורך אזור הפיירינג כולו","value":"כמעט 17 מטרים"}]}],"fun_facts_he":["הפיירינג נפתח ונסגר כמו פה של היפופוטם בתוך 1.5 שניות בלבד, ולכן המהנדסים קוראים לו Hungry Hippo, על שם משחק הילדים עם ההיפופוטמים הרעבים.","השלב השני תלוי בתוך הרקטה מהצוואר, כמו שקית על וו, ואינו נושא את עומסי הטיסה: כך אפשר היה לבנות אותו דק וקל במיוחד, אחד השלבים העליונים הקלים בעולם ביחס לגודלו.","ספינת הנחיתה של Neutron נקראת Return On Investment, כלומר החזר על ההשקעה: בדיחה עצמית של Rocket Lab על ההשקעה העצומה בפיתוח הרקטה.","זו הרקטה הגדולה בעולם העשויה סיבי פחמן, אותו חומר של אופני מרוץ ומחבטי טניס: חזק כמו פלדה וקל ממנה בהרבה.","חיל האוויר האמריקאי כבר הזמין טיסת ניסוי של Neutron להובלת מטענים מנקודה לנקודה על פני כדור הארץ דרך החלל."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('new-glenn', '{"slug":"new-glenn","name_en":"New Glenn","name_he":"ניו גלן","company_slug":"blue-origin","status_he":"פעיל אך מקורקע זמנית: 3 טיסות עד ספטמבר 2026, מתוכן 2 הצלחות מלאות, חזרה לטיסה מתוכננת עד סוף 2026 לאחר שיקום מתחם השיגור","intro_he":"New Glenn היא רקטת המשא הכבדה של Blue Origin, חברת החלל של Jeff Bezos, והיא נקראת על שם John Glenn, האמריקאי הראשון שהקיף את כדור הארץ. מדובר בענק של 98 מטרים, גבוה כמו בניין בן 30 קומות, עם גוף ברוחב אחיד של 7 מטרים ושני שלבים: בוסטר רב פעמי עם שבעה מנועי BE-4 שנוחת אנכית על ספינה בלב האוקיינוס ומתוכנן לשרת 25 טיסות לפחות, ודרג עליון עם שני מנועי מימן מסוג BE-3U. הרקטה מסוגלת להניף 45 טונות למסלול נמוך סביב כדור הארץ, ובראשה חרטום מטען בקוטר 7 מטרים שנפחו הפנימי כפול בערך מכל חרטום אחר שטס כיום.\n\nמאז טיסת הבכורה בתאריך 16 בינואר 2025 השלימה New Glenn שלוש טיסות. בטיסה השנייה, בנובמבר 2025, היא שיגרה את זוג גשושיות ESCAPADE של NASA לעבר מאדים והנחיתה לראשונה את הבוסטר על ספינה בים, ובאפריל 2026 נרשמה ראשוניות נוספת: שימוש חוזר באותו בוסטר, אם כי תקלה במנוע הדרג השני הותירה את הלוויין במסלול נמוך מדי. בסוף מאי 2026 התפוצצה רקטה שלמה במבחן הצתה קרקעי והרסה חלק ממתחם השיגור LC-36, האירוע העוצמתי מסוגו מאז הרקטה הסובייטית N1 בשנת 1969. Blue Origin משקמת את המתחם במרץ ומכוונת לחזור לטוס עד סוף 2026 עם משימת NG-4, שתישא את רכב הנחיתה הירחי Blue Moon MK1. הרקטה היא אבן יסוד בתוכניות של Amazon לקבוצת הלוויינים Kuiper ושל NASA בתוכנית Artemis, ולכן כל טיסה שלה מזיזה את כל תעשיית החלל.","dims":{"height_m":98,"diameter_m":7,"mass_t":null,"payload_leo_t":45,"thrust_liftoff_kn":17219,"stages":2,"first_flight":"2025-01-16","flights":"3 טיסות עד ספטמבר 2026: 2 הצלחות (NG-1, NG-2), כישלון חלקי אחד (NG-3), שתי נחיתות בוסטר מוצלחות ושימוש חוזר ראשון בבוסטר"},"sections":[{"id":"gs1_engines","name_he":"שבעה מנועי BE-4","name_en":"7x BE-4 Engines","from_m":0,"to_m":4.5,"kind":"engines","desc_he":"שבעה מנועי BE-4 בתחתית הבוסטר מספקים יחד בסביבות 17,200 קילוניוטון דחף בהמראה, מספיק כדי להרים משא של 1,700 טונות, ובתצורה המשודרגת עם דלק מקורר במיוחד הדחף יטפס לבערך 19,900 קילוניוטון. כל מנוע שורף גז טבעי נוזלי וחמצן נוזלי במחזור בעירה מדורגת עשירת חמצן: כל החמצן עובר קודם דרך טורבינה שמניעה את המשאבות, ורק אז נשרף בתא הבעירה, כך שכמעט שום דלק לא מתבזבז בדרך. חשבו על מנוע טורבו שממחזר את גזי הפליטה של עצמו. המנוע המרכזי ושני מנועים נגדיים לו יודעים להידלק מחדש באוויר לבלימה ולנחיתה האנכית, וכל המנועים מוטים על צירים לצורך היגוי. אגב, אותו מנוע בדיוק מניע גם את רקטת Vulcan של ULA המתחרה.","facts":[{"label_he":"דחף לכל מנוע","value":"2,450 קילוניוטון"},{"label_he":"דחף המראה כולל","value":"17,219 קילוניוטון"},{"label_he":"דחף לאחר שדרוג הצינון","value":"19,928 קילוניוטון"},{"label_he":"מנועים שנדלקים מחדש לנחיתה","value":"3 מתוך 7"}],"engine":{"name":"BE-4","count":7,"layout":"cluster7","cycle_he":"בעירה מדורגת עשירת חמצן","propellant_he":"גז טבעי נוזלי (מתאן) וחמצן נוזלי","thrust_kn_each":2450,"isp_s":340}},{"id":"landing_legs","name_he":"רגלי נחיתה","name_en":"Landing Legs (6)","from_m":0,"to_m":7,"kind":"legs","overlay":true,"desc_he":"שש רגלי נחיתה הידראוליות מקופלות סביב המודול האחורי, בין שבעת המנועים, ונפתחות כלפי חוץ שניות ספורות לפני הנגיעה. הן חייבות לבלום נחיתה של מבנה בגובה בניין בן 19 קומות על סיפון ספינה נעה בלב ים, ולכן כל רגל בולעת את אנרגיית הפגיעה כמו בולם זעזועים ענק ומפצה אוטומטית על הפרשי גובה בין נקודות המגע כשסיפון הספינה מתנדנד. שש רגליים במקום ארבע נותנות בסיס רחב ויציב יותר בים גלי. הנחיתה המוצלחת הראשונה נרשמה בטיסת NG-2 בנובמבר 2025, בניסיון הימי הראשון, על ספינת הנחיתה Jacklyn שנקראת על שם אמו של Jeff Bezos, והבוסטר הזה עצמו המריא שוב באפריל 2026.","facts":[{"label_he":"מספר רגליים","value":"6"},{"label_he":"נחיתה ימית ראשונה","value":"13 בנובמבר 2025"},{"label_he":"ספינת הנחיתה","value":"Jacklyn"}],"engine":null},{"id":"aft_module","name_he":"המודול האחורי ומבנה הדחף","name_en":"Aft Module / Thrust Structure","from_m":4.5,"to_m":8,"kind":"thrust_structure","desc_he":"המודול האחורי הוא הבסיס שנושא את כל העומס: מבנה דחף שמפזר את הכוח האדיר של שבעת המנועים אל גוף הרקטה, עטוף בחצאית מנועים ברוחב 8.5 מטרים, רחבה מהגוף עצמו כדי לפנות מקום לשבעה מנועים ולשש רגלי נחיתה מתקפלות. חשבו עליו כמו יסודות של גורד שחקים: כל טונה של דחף חייבת לעבור דרכו בלי לעוות את המבנה. בדרך חזרה לכדור הארץ המודול הזה פוגש את האטמוספירה ראשון, מנועים קדימה, ולכן הוא בנוי לעמוד בחום ובעומסים העצומים של הכניסה החוזרת. בתוכו יושבות גם מערכות ההידראוליקה שפורשות את הרגליים ומנגנוני ההטיה שמסובבים את המנועים לצורך היגוי.","facts":[{"label_he":"קוטר חצאית המנועים","value":"8.5 מטרים"},{"label_he":"רגלי נחיתה מאוחסנות","value":"6"},{"label_he":"חיי שירות מתוכננים לבוסטר","value":"25 טיסות לפחות"}],"engine":null},{"id":"strakes","name_he":"מייצבים אחוריים","name_en":"Aft Strakes","from_m":6,"to_m":25,"kind":"strakes","overlay":true,"desc_he":"שני מייצבים ארוכים דמויי כנף צמודים לאורך חלקו האחורי של הבוסטר, משני צדדיו. בדרך חזרה לכדור הארץ הבוסטר לא צונח סתם: הוא חוזר כשהמנועים פונים קדימה, והמייצבים מייצרים עילוי שמאפשר לו לגלוש בתוך האטמוספירה ולתקן את נתיבו לעבר ספינת הנחיתה, מאות קילומטרים מנקודת השיגור. חשבו על גולש סנובורד שמטה את גופו כדי לנווט בירידה: כך הבוסטר מנצל את האוויר עצמו במקום לבזבז דלק יקר על תיקוני מסלול. העילוי הזה מגדיל את טווח התמרון הצידי, מקטין את כמות הדלק שצריך לשמור לנחיתה, וכך משאיר יותר דחף למשימת השיגור עצמה. שלושה מהמנועים, אלה שמיושרים עם המייצבים, נדלקים מחדש לבלימה הסופית.","facts":[{"label_he":"מספר מייצבים","value":"2"},{"label_he":"מרחק אזור הנחיתה מהחוף","value":"בסביבות 1,000 קילומטרים"}],"engine":null},{"id":"gs1_lox_tank","name_he":"מיכל חמצן נוזלי, דרג ראשון","name_en":"GS1 LOX Tank","from_m":8,"to_m":31.5,"kind":"tank_ox","desc_he":"מיכל החמצן הנוזלי של הדרג הראשון, הגדול מבין שני מיכלי הבוסטר, יושב בתחתית כדי שהמשא הכבד ביותר יישאר נמוך. החמצן מקורר למינוס 183 מעלות צלזיוס, והוא מהווה כמעט שלושה רבעים ממשקל הדלק הכולל של הדרג: על כל קילוגרם של מתאן נשרפים בערך 3.6 קילוגרמים של חמצן. הדפנות עשויות אלומיניום בכרסום אורתוגריד, רשת של צלעות חיזוק שמסירה חומר מיותר ומשאירה חוזק, כמו קורות בתקרת בטון. במקום בלוני הליום יקרים וכבדים, המיכל שומר על לחץ עצמי: מעט חמצן מאודה ומוזרם בחזרה לחלקו העליון. המיכל תוכנן מראש לעמוד בעומסי החזרה לאטמוספירה, כי הבוסטר כולו נבנה לשימוש חוזר של 25 טיסות לפחות.","facts":[{"label_he":"טמפרטורת החמצן","value":"מינוס 183 מעלות צלזיוס"},{"label_he":"קוטר המיכל","value":"7 מטרים"},{"label_he":"יחס שרפה","value":"3.6 קילוגרם חמצן על כל קילוגרם מתאן"}],"engine":null},{"id":"gs1_lng_tank","name_he":"מיכל דלק, גז טבעי נוזלי","name_en":"GS1 LNG Fuel Tank","from_m":31.5,"to_m":49,"kind":"tank_fuel","desc_he":"מעל מיכל החמצן יושב מיכל הדלק: גז טבעי נוזלי, בעיקרו מתאן, מקורר למינוס 162 מעלות צלזיוס. זה אותו גז שמגיע לכיריים במטבח, רק נוזלי ותופס נפח קטן בערך פי 600. Blue Origin בחרה מתאן משיקול של שימוש חוזר: הוא נשרף נקי כמעט לגמרי, בלי פיח, כך שאפשר להטיס את המנועים שוב ושוב בלי לפרק ולנקות אותם, בניגוד לקרוסין שמשאיר שאריות פחמן בצנרת. הוא גם זול, זמין בכל העולם וקל בהרבה לאחסון לעומת מימן. גם המיכל הזה שומר על לחץ עצמי באמצעות גז מאודה מתוצרת עצמית, בלי הליום. הדפנות המוקשחות נושאות את עומסי הטיסה והחזרה כשלד חיצוני, בלי מסגרת נפרדת, וכך נחסך משקל יקר.","facts":[{"label_he":"טמפרטורת הדלק","value":"מינוס 162 מעלות צלזיוס"},{"label_he":"צמצום נפח לעומת גז רגיל","value":"פי 600 בקירוב"},{"label_he":"זמן בעירת הדרג","value":"190 שניות"}],"engine":null},{"id":"forward_fins","name_he":"סנפירי היגוי קדמיים","name_en":"Forward Fins (4)","from_m":48.5,"to_m":53.5,"kind":"flaps","overlay":true,"desc_he":"ארבעה סנפירים מתנייעים סמוך לראש הבוסטר משמשים הגה בדרך למטה. כשהבוסטר חוזר מנועים קדימה, הסנפירים נמצאים בקצה האחורי של הזרימה, בדיוק כמו הנוצות בקצה חץ, אבל בניגוד לנוצות הם פועלים באופן אקטיבי: מחשב הטיסה מסובב כל סנפיר בנפרד עשרות פעמים בשנייה כדי לשלוט בזווית ובכיוון של הגוף הענק בזמן הצלילה באטמוספירה. יחד עם מדחפי בקרת הגישה שבמודול הקדמי ועם המייצבים האחוריים, הם מכוונים את הבוסטר אל נקודה מדויקת בלב האוקיינוס. בגובה נמוך שלושה מנועים נדלקים מחדש לבלימה, והסנפירים ממשיכים לייצב את הגוף עד רגעי הנחיתה האנכית על סיפון הספינה Jacklyn.","facts":[{"label_he":"מספר סנפירים","value":"4, כולם מתנייעים"},{"label_he":"תפקיד","value":"היגוי ובקרת גישה בזמן הצלילה חזרה"}],"engine":null},{"id":"forward_module","name_he":"המודול הקדמי ואוויוניקה","name_en":"Forward Module & Avionics","from_m":49,"to_m":51.5,"kind":"avionics","desc_he":"המודול הקדמי הוא המוח של הבוסטר. כאן יושבים מחשבי הטיסה והניווט שמנהלים את ההמראה, את ההיפרדות ואת הנחיתה האוטונומית באמצע האוקיינוס, בלי טייס ובלי שליטה מהקרקע. סביב המודול מותקנים ארבעת סנפירי ההיגוי המתנייעים, וכן מדחפי בקרת גישה קטנים שמסובבים את הבוסטר בחלל: אחרי ההיפרדות הם הופכים אותו כך שהמנועים יפנו קדימה לקראת הכניסה לאטמוספירה. כאן נמצאות גם נקודות החיבור הטבוריות לתשתית הקרקע, שדרכן זורמים דלק, חשמל ונתונים עד רגע ההמראה. חשבו על המודול הזה כטייס אוטומטי קשוח: הוא מקבל אלפי החלטות בשנייה כדי להחזיר הביתה, בשלמות, מכונה בגובה של בניין בן 19 קומות.","facts":[{"label_he":"אורך הדרג הראשון כולו","value":"57.5 מטרים"},{"label_he":"סנפירים מעוגנים למודול","value":"4"}],"engine":null},{"id":"interstage","name_he":"טבעת החיבור בין הדרגים","name_en":"Interstage","from_m":51.5,"to_m":57.5,"kind":"interstage","desc_he":"המעבר בין הדרגים הוא גליל חלול באורך של בערך 6 מטרים, שבתוכו מוסתרות הזרבוביות של שני מנועי BE-3U של הדרג השני, כמו נדן שעוטף להב. בערך שלוש דקות אחרי ההמראה, כשהבוסטר סיים את עבודתו, מנגנון ההפרדה משחרר את הדרג העליון, הדרג מתרחק, והמנועים שהיו חבויים נדלקים במרחק בטוח מהבוסטר. התזמון קריטי: הצתה מוקדמת מדי תפגע בבוסטר שעדיין קרוב, ומאוחרת מדי תאבד גובה ומהירות יקרים. הטבעת גם נושאת בזמן הטיסה באטמוספירה את כל משקל הדרג השני והמטען שמעליה, ולכן היא בנויה מחומרים קלים וקשיחים במיוחד. אחרי ההפרדה היא נשארת מחוברת לבוסטר וחוזרת איתו לנחיתה.","facts":[{"label_he":"אורך","value":"בסביבות 6 מטרים"},{"label_he":"מועד ההפרדה","value":"בסביבות 3 דקות לאחר ההמראה"},{"label_he":"תכולה","value":"זרבוביות שני מנועי BE-3U"}],"engine":null},{"id":"gs2_engines","name_he":"שני מנועי BE-3U","name_en":"2x BE-3U Engines","from_m":57.5,"to_m":61.5,"kind":"engines","desc_he":"שני מנועי BE-3U שורפים מימן נוזלי וחמצן נוזלי, הצירוף היעיל ביותר שקיים בהנעה כימית: מהירות הפליטה מגיעה לבערך 4.4 קילומטרים בשנייה. המנועים פועלים במחזור מרחיב פתוח, רעיון אלגנטי בפשטותו: מעט מימן קר עובר בתעלות קירור סביב תא הבעירה, מתחמם והופך לגז, והגז הזה הוא שמסובב את טורבינות המשאבות. פחות חלקים, פחות נקודות כשל. כל מנוע מספק כיום בסביבות 770 קילוניוטון דחף בוואקום, עם שדרוג הדרגתי לקראת 890 קילוניוטון, והוא יודע להידלק מחדש בחלל לצורך מסלולים מדויקים. דווקא כאן אירעה התקלה בטיסת NG-3 באפריל 2026: אחד המנועים לא סיפק דחף מלא בהצתה השנייה, והלוויין נותר במסלול נמוך מדי שממנו הוצא בכוונה.","facts":[{"label_he":"דחף לכל מנוע","value":"770 קילוניוטון כיום, 890 לאחר שדרוג"},{"label_he":"דחף מפרט מקורי לזוג","value":"1,423 קילוניוטון"},{"label_he":"זמן בעירה","value":"644 שניות"},{"label_he":"מקדם יעילות (Isp)","value":"445 שניות"}],"engine":{"name":"BE-3U","count":2,"layout":"cluster2","cycle_he":"מחזור מרחיב פתוח (Expander Bleed)","propellant_he":"מימן נוזלי וחמצן נוזלי","thrust_kn_each":770,"isp_s":445}},{"id":"gs2_tank","name_he":"מיכל משותף של הדרג השני","name_en":"GS2 Common Bulkhead Tank","from_m":61.5,"to_m":76.1,"kind":"tank_common","desc_he":"מיכל משותף אחד מכיל את שני נוזלי ההנעה של הדרג השני: חמצן נוזלי למטה, ומעליו מיכל המימן הגדול, כשמחיצה משותפת מבודדת מפרידה ביניהם וחוסכת את משקלה של דופן כפולה. המימן הנוזלי הוא החומר הקר ביותר ברקטה, מינוס 253 מעלות צלזיוס, בקושי 20 מעלות מעל האפס המוחלט, והוא קל להפליא: קילוגרם אחד תופס 14 ליטרים, ולכן מיכל המימן תופס את רוב אורך הדרג. המחיצה המשותפת היא אתגר הנדסי אמיתי: בצד אחד שוררים מינוס 183 מעלות ובצד השני מינוס 253, והבידוד חייב למנוע מהחמצן לקפוא. הדרג כולו משתרע על 23.4 מטרים, וקצהו העליון מוסתר בתוך חרטום המטען שעוטף אותו.","facts":[{"label_he":"אורך הדרג השני","value":"23.4 מטרים"},{"label_he":"טמפרטורת המימן","value":"מינוס 253 מעלות צלזיוס"},{"label_he":"צפיפות מימן נוזלי","value":"71 קילוגרם למטר מעוקב"}],"engine":null},{"id":"fairing","name_he":"חרטום המטען","name_en":"Payload Fairing","from_m":76.1,"to_m":98,"kind":"fairing","desc_he":"חרטום המטען של New Glenn הוא הגדול בענף: מעטפת מחומרים מרוכבים בקוטר 7 מטרים ובאורך 21.9 מטרים, עם נפח שימושי גדול בערך פי שניים מחרטומי 5 המטרים המקובלים בתעשייה. בפנים אפשר להעמיד שני אוטובוסים עירוניים זה לצד זה, ועוד יישאר מקום. הנפח הזה הוא יתרון מסחרי אמיתי: לוויינים גדולים, טלסקופים מתקפלים ותחנות חלל עתידיות מוגבלים לרוב דווקא בנפח, לא במשקל. בערך שלוש וחצי דקות אחרי ההמראה, מחוץ לאטמוספירה, שני חצאי החרטום נפתחים כמו צדפה ומושלכים. עד היום נשא החרטום את אב הטיפוס Blue Ring, את זוג גשושיות ESCAPADE של NASA בדרכן למאדים ואת לוויין התקשורת BlueBird 7, ובטיסה הבאה ייסע בתוכו רכב הנחיתה הירחי Blue Moon MK1.","facts":[{"label_he":"קוטר","value":"7 מטרים"},{"label_he":"אורך","value":"21.9 מטרים"},{"label_he":"השלכת החרטום","value":"בסביבות דקה 3.5 לטיסה"},{"label_he":"יתרון נפח","value":"פי 2 מחרטום סטנדרטי של 5 מטרים"}],"engine":null}],"fun_facts_he":["השם ממשיך מסורת: הרקטה הקטנה New Shepard נקראת על שם Alan Shepard, האמריקאי הראשון בחלל, ואילו New Glenn נקראת על שם John Glenn, הראשון שהקיף את כדור הארץ בשנת 1962.","ספינת הנחיתה Jacklyn נקראת על שם אמו של Jeff Bezos, והבוסטר הראשון שנחת עליה זכה לכינוי Never Tell Me The Odds, שורה מתוך הסרט מלחמת הכוכבים.","בתוך חרטום המטען אפשר להעמיד שני אוטובוסים עירוניים זה לצד זה, ועדיין יישאר מקום פנוי.","מנועי BE-4 של הבוסטר מניעים גם את רקטת Vulcan Centaur של ULA: המתחרה הישירה קונה את אותם מנועים עצמם מידי Blue Origin.","הפיצוץ במבחן הקרקע במאי 2026 נחשב לפיצוץ הרקטות העוצמתי ביותר מאז ניסוי N1 הסובייטי בשנת 1969, ובכל זאת איש לא נפגע בו."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('shavit', '{"slug":"shavit","name_en":"Shavit 2","name_he":"שביט 2","company_slug":"israel-space","status_he":"פעיל: 7 שיגורים מוצלחים ברצף לדגם שביט 2 מאז 2007, האחרון שבהם Ofeq 19 בספטמבר 2025; משגר דור המשך נמצא בפיתוח","intro_he":"שביט 2 הוא משגר הלוויינים הלאומי של ישראל: רקטה קומפקטית בעלת שלושה שלבים, כולם בדלק מוצק, שמובילה IAI כקבלן ראשי עם מנועים של Tomer ושל Rafael. המשגר נולד מתוך תוכנית הטילים יריחו, ולכן הוא בנוי כמו טיל: פשוט, אמין, ומוכן לשיגור בהתראה קצרה. הוא משגר את לווייני התצפית מסדרת Ofeq מבסיס פלמחים שלחוף הים התיכון, ובניגוד לכל שאר העולם הוא טס מערבה, נגד כיוון סיבוב כדור הארץ, כדי שלא לחלוף מעל מדינות שכנות. גובהו בערך 21.7 מטרים, קוטרו 1.35 מטרים, מסת ההמראה שלו בערך 33 טונות, והוא מרים בערך 350 קילוגרמים למסלול נמוך נסיגתי.\n\nחשיבותו של שביט חורגת בהרבה מגודלו: כששוגר Ofeq 1 בספטמבר 1988 הפכה ישראל למדינה השמינית בעולם עם יכולת שיגור עצמאית, והקטנה שבהן. נכון לספטמבר 2026 רשומים למשפחת שביט 13 שיגורים, מהם 11 הצלחות, ולדגם שביט 2 לבדו 7 שיגורים מוצלחים ברצף, האחרון שבהם לוויין המכ\"ם Ofeq 19 בליל 2 בספטמבר 2025. לפי הצהרות משרד הביטחון סביב אותו שיגור, דור חדש של משגרים כבר נמצא בפיתוח. הערה על הנתונים: חלק גדול מהמפרט חסוי, והמקורות הפומביים נעים למשל בין 21 עד 26 מטרים לגובה הכולל; המספרים כאן מבוססים על השחזור ההנדסי המפורט והעקבי ביותר שפורסם.","dims":{"height_m":21.7,"diameter_m":1.35,"mass_t":33,"payload_leo_t":0.35,"stages":3,"thrust_liftoff_kn":447,"first_flight":"10 ביוני 2007 (משפחת שביט: 19 בספטמבר 1988)","flights":"שביט 2: 7 שיגורים, 7 הצלחות, 2007 עד 2025; משפחת שביט כולה: 13 שיגורים, מהם 11 הצלחות, נכון לספטמבר 2026"},"sections":[{"id":"s1_engine","name_he":"מנוע השלב הראשון","name_en":"First Stage Motor & Nozzle (ATSM-13)","from_m":0,"to_m":1.4,"kind":"engines","desc_he":"זהו הקצה הלוהט של המשגר: נחיר הפליטה של מנוע ATSM-13, מנוע רקטי בדלק מוצק שפותח בתעשייה הצבאית ומיוצר כיום בידי חברת Tomer. מנוע מוצק דומה לזיקוק ענק: הדלק והמחמצן מעורבבים מראש בתוך גוף המנוע, וברגע ההצתה הוא בוער עד הסוף, בלי אפשרות לכבות או להנמיך עוצמה. הפשטות הזאת היא בדיוק היתרון: המשגר יכול לעמוד מוכן זמן רב ולהמריא בהתראה קצרה, תכונה שירש מעולם הטילים הבליסטיים. ההיגוי בשלב הזה נעשה בעזרת להבי הטיה שיושבים בתוך זרם הפליטה ומטים אותו, בשילוב סנפירי הייצוב החיצוניים. בשיגור מספק המנוע דחף של בערך 447 קילוניוטון, שווה ערך למשקל של 45 טונות, והוא בוער במשך בערך 72 שניות עד שהדלק אוזל.","facts":[{"label_he":"דחף בשיגור","value":"בערך 447 קילוניוטון"},{"label_he":"זמן בעירה","value":"בערך 72 שניות"},{"label_he":"דחף סגולי","value":"בערך 268 שניות"},{"label_he":"יצרן המנוע","value":"Tomer (לשעבר התעשייה הצבאית)"}],"engine":{"name":"ATSM-13","count":1,"layout":"single","cycle_he":"מנוע דלק מוצק, ללא משאבות ומחזור הזנה","propellant_he":"דלק מוצק מרוכב על בסיס HTPB","thrust_kn_each":447,"isp_s":268}},{"id":"s1_casing","name_he":"גוף מנוע השלב הראשון","name_en":"First Stage Solid Motor Casing","from_m":1.4,"to_m":7.25,"kind":"tank_fuel","desc_he":"בשלב מוצק אין מכלי דלק נפרדים: הגוף עצמו הוא גם המכל וגם תא הבעירה. בתוך הגליל הזה יצוקות בערך 13.7 טונות של דלק מוצק מרוכב על בסיס HTPB: גומי סינתטי שמשמש גם דבק וגם דלק, אבקת אלומיניום שמוסיפה אנרגיה, ואמוניום פרכלורט שמספק את החמצן. בליבת היציקה עובר חלל פנימי מעוצב בקפידה, וצורת החתך שלו קובעת כמה שטח בוער בכל רגע: כך מתוכנת פרופיל הדחף מראש, כמו נר שצורתו מכתיבה את קצב הבעירה שלו. הגוף עשוי חומרים מרוכבים בליפוף סיבים, פתרון קל משקל שמקורו בתוכנית הטילים יריחו. השלב כולו, באורך של בערך 7.2 מטרים ובמסה של בערך 15 טונות, מספק את רוב העבודה הקשה של היציאה מהאטמוספירה הצפופה.","facts":[{"label_he":"דלק מוצק","value":"בערך 13.7 טונות"},{"label_he":"אורך השלב המלא","value":"בערך 7.2 מטרים"},{"label_he":"מסת השלב במלואו","value":"בערך 14.9 טונות"},{"label_he":"קוטר","value":"1.35 מטר"}]},{"id":"interstage_12","name_he":"מבנה הביניים","name_en":"Interstage","from_m":7.25,"to_m":8.45,"kind":"interstage","desc_he":"טבעת חיבור קצרה שמחברת את שני השלבים הגדולים, ובתוכה מסתתר נחיר הפליטה של השלב השני. זהו אזור הנדסי צפוף במיוחד: המבנה חייב להעביר את כל עומסי הדחף של השלב הראשון אל גוף המשגר שמעליו, ובו בזמן להכיל את מטעני הניתוק הפירוטכניים שחותכים את החיבור ברגע המדויק. כשהדלק בשלב הראשון אוזל, המטענים מנתקים את הטבעת, השלב הראשון הריק נופל אל הים התיכון, והשלב השני מוצת. התזמון קריטי: הצתה מוקדמת מדי תפגע בשלב התחתון שעדיין מחובר, והצתה מאוחרת מדי תבזבז גובה ומהירות שנצברו בעמל רב. באורך של בערך 1.2 מטרים, זהו אחד החלקים הצנועים למראה אך הקריטיים ביותר להצלחת הטיסה כולה.","facts":[{"label_he":"אורך","value":"בערך 1.2 מטרים"},{"label_he":"קוטר","value":"1.35 מטר"},{"label_he":"תפקיד נוסף","value":"מכיל את נחיר השלב השני ואת מטעני הניתוק"}]},{"id":"s2_stage","name_he":"השלב השני","name_en":"Second Stage (ATSM-13)","from_m":8.45,"to_m":14.9,"kind":"tank_fuel","desc_he":"השלב השני הוא כמעט תאום של הראשון: אותו מנוע ATSM-13 עם אותה כמות דלק, בערך 13.7 טונות. הזהות הזאת היא החלטה כלכלית חכמה: קו ייצור אחד, מערך בדיקות אחד וחלפים משותפים, בדיוק כמו יצרן רכב שמרכיב אותו מנוע בשני דגמים. ההבדל המרכזי נמצא בנחיר: כאן הוא רחב יותר, עם יחס התפשטות גבוה, כי השלב השני עובד בגובה שבו האוויר דליל והגזים יכולים להתרחב יותר ולהפיק דחף יעיל יותר, בערך 516 קילוניוטון בריק. גם ההיגוי שונה: בגובה הזה סנפירים כבר חסרי תועלת, ולכן הנחיר עצמו מוטה בעזרת מערכת כיוון דחף. אחרי בערך 72 שניות בעירה נוספות, המשגר כבר נמצא מעל רוב האטמוספירה, בדרכו מערבה מעל הים התיכון נגד כיוון סיבוב כדור הארץ.","facts":[{"label_he":"דחף בריק","value":"בערך 516 קילוניוטון"},{"label_he":"דלק מוצק","value":"בערך 13.7 טונות"},{"label_he":"זמן בעירה","value":"בערך 72 שניות"},{"label_he":"מסת השלב במלואו","value":"בערך 15 טונות"}],"engine":{"name":"ATSM-13","count":1,"layout":"single","cycle_he":"מנוע דלק מוצק עם נחיר מותאם לריק","propellant_he":"דלק מוצק מרוכב על בסיס HTPB","thrust_kn_each":516,"isp_s":277}},{"id":"equipment_bay","name_he":"תא הציוד והאוויוניקה","name_en":"Equipment Bay (Avionics)","from_m":14.9,"to_m":17.3,"kind":"avionics","desc_he":"תא הציוד הוא המוח של שביט 2: כאן יושבים מחשב הטיסה, מערכת הניווט האינרציאלית שמודדת תאוצות וסיבובים בלי שום תלות בעולם החיצון, סוללות, ומשדרי הטלמטריה שמדווחים לתחנת הקרקע בפלמחים על מצב המשגר. מכאן יוצאות פקודות ההיגוי לשני השלבים הראשונים ופקודות הניתוק וההצתה לאורך הטיסה. לתא יש מאפיין יוצא דופן: לפי המקורות הפומביים הוא ננטש לפני הצתת השלב השלישי. הסיבה פשוטה וגאונית: השלב השלישי מיוצב סחרור ואינו זקוק להיגוי פעיל, וכל קילוגרם שמושלים לפני הבעירה האחרונה מתורגם ישירות לתוספת מהירות ללוויין. זה כמו רץ מרתון שמשליך את בקבוק המים רגע לפני הספרינט האחרון. גובה המקטע בערך 2.4 מטרים, והוא משמש גם כמתאם מבני שנושא את השלב השלישי הכדורי שמעליו.","facts":[{"label_he":"גובה המקטע","value":"בערך 2.4 מטרים"},{"label_he":"קוטר","value":"1.35 מטר"},{"label_he":"ניווט","value":"אינרציאלי עצמאי, ללא תלות ב GPS"}]},{"id":"s3_aus51","name_he":"השלב השלישי AUS-51","name_en":"Third Stage AUS-51 (PEPT-420)","from_m":17.3,"to_m":19.45,"kind":"kick_stage","desc_he":"שלב ההכנסה למסלול: מנוע כדורי בשם AUS-51 מתוצרת Rafael, שטס בשיגורים האחרונים בגרסה משופרת המכונה PEPT-420. הצורה הכדורית אינה מקרית: כדור הוא מכל הלחץ היעיל ביותר בטבע, הוא מחזיק את לחץ הבעירה עם מינימום חומר, כמו בועת סבון שמחלקת את המתח שווה בשווה לכל הכיוונים. גוף המנוע עשוי טיטניום, ובתוכו בערך 1.9 טונות דלק מוצק מתוך מסה כוללת של בערך 2.6 טונות. לפני ההצתה מסוחרר השלב יחד עם הלוויין סביב צירו, כמו קליע רובה, וכך הוא שומר על כיוון יציב בלי שום מערכת היגוי. המנוע מספק דחף של 58.6 קילוניוטון במשך בערך 94 שניות, עם דחף סגולי של 298 שניות, הגבוה במשגר, ומעניק ללוויין את הדחיפה האחרונה אל מהירות מסלולית.","facts":[{"label_he":"דחף בריק","value":"58.6 קילוניוטון"},{"label_he":"זמן בעירה","value":"בערך 94 שניות"},{"label_he":"דחף סגולי","value":"בערך 298 שניות"},{"label_he":"מסה","value":"בערך 2.6 טונות, מתוכן 1.9 טונות דלק"}],"engine":{"name":"AUS-51 (PEPT-420)","count":1,"layout":"single","cycle_he":"מנוע דלק מוצק כדורי, מיוצב סחרור","propellant_he":"דלק מוצק מרוכב בגוף טיטניום","thrust_kn_each":58.6,"isp_s":298}},{"id":"payload_ofeq","name_he":"המטען: לווייני Ofeq","name_en":"Ofeq Payload","from_m":19.45,"to_m":20.6,"kind":"payload","desc_he":"כאן יושב הנוסע: לוויין מסדרת Ofeq, סדרת לווייני התצפית הביטחוניים של ישראל שבונה IAI. אלה לוויינים קטנים וחכמים במסה של בערך 300 קילוגרמים, חלקם עם מצלמות אופטיות וחלקם עם מכ\"ם מפתח סינתטי (SAR) שרואה בלילה ומבעד לעננים. האחרון שבהם, Ofeq 19, שוגר בתאריך 2 בספטמבר 2025: לוויין מכ\"ם שמבחין לפי הפרסומים בעצמים בגודל של בערך חצי מטר. בגלל השיגור מערבה נעים הלוויינים במסלול נסיגתי בנטייה של בערך 141 מעלות, בגובה של בערך 350 עד 600 ק\"מ, מסלול שמחזיר אותם מעל המזרח התיכון כמה פעמים ביממה, בדיוק מה שנדרש ממערך מודיעין. המסה הקטנה של הלוויינים היא אילוץ ישיר של השיגור נגד כיוון סיבוב כדור הארץ, שגוזל חלק ניכר מכושר הנשיאה.","facts":[{"label_he":"מסת לוויין טיפוסית","value":"בערך 300 קילוגרמים"},{"label_he":"נטיית מסלול","value":"בערך 141 מעלות (נסיגתי)"},{"label_he":"גובה מסלול","value":"בערך 350 עד 600 ק\"מ"},{"label_he":"רזולוציית Ofeq 19","value":"בערך חצי מטר, לפי פרסומים זרים"}]},{"id":"nosecone","name_he":"החרטום","name_en":"Nose Cone","from_m":20.6,"to_m":21.7,"kind":"nosecone","desc_he":"קצה החרטום הוא החלק שפוגש את האוויר ראשון, ובו מתרכז החימום האווירודינמי הגדול ביותר. צורתו נבחרה כפשרה מחושבת בין שני צרכים מנוגדים: חוד צר חותך את האוויר ומקטין גרר, ואילו קצה מעוגל מפזר את החום טוב יותר ופשוט יותר לייצור. במהירות המרבית בתוך האטמוספירה נדחס האוויר שלפני החרטום ומתחמם למאות מעלות, ולכן הוא בנוי מחומרים מרוכבים עמידי חום. החרטום הוא חלקה העליון של חופת המטען, שאורכה הכולל בערך 4.4 מטרים, וכשהמשגר יוצא מהאטמוספירה הוא ננטש יחד איתה: מרגע שאין אוויר, תפקידו הסתיים, וכל קילוגרם מיותר שממשיך לטוס גוזל מהירות סופית מהלוויין. זו הסיבה שמתזמנים את ההשלה מוקדם ככל שמאפשרת הבטיחות של הלוויין הרגיש שבפנים.","facts":[{"label_he":"אורך החופה כולה","value":"בערך 4.4 מטרים"},{"label_he":"קוטר בסיס","value":"1.35 מטר"}]},{"id":"fins","name_he":"סנפירי ייצוב","name_en":"Stabilizing Fins","from_m":0,"to_m":1.6,"kind":"strakes","overlay":true,"desc_he":"ארבעה סנפירי ייצוב קבועים יושבים על חצאית אחורית מתרחבת שקוטרה בערך 1.56 מטר. תפקידם דומה לנוצות בקצה חץ: הם מזיזים את מרכז הלחץ האווירודינמי אחורה, אל מאחורי מרכז הכובד, וכך כל סטייה קטנה של המשגר מתיישרת מעצמה במקום להתעצם ולהפוך להתהפכות. הדבר חשוב במיוחד בשניות הראשונות אחרי ההמראה, כשהמהירות עדיין נמוכה והמשגר פגיע לרוחות צד. הסנפירים עובדים בשיתוף עם להבי ההטיה שבזרם הפליטה: הלהבים מספקים היגוי אקטיבי מדויק, והסנפירים מספקים יציבות פסיבית שאינה תלויה בשום מערכת חשמלית. ככל שהאוויר מתדלדל עם הגובה, השפעתם נחלשת והולכת, ומרגע ניתוק השלב הראשון הם צוללים איתו יחד אל הים התיכון.","facts":[{"label_he":"מספר סנפירים","value":"4"},{"label_he":"קוטר החצאית האחורית","value":"בערך 1.56 מטר"}]},{"id":"fairing","name_he":"חופת המטען","name_en":"Payload Fairing","from_m":17.3,"to_m":21.7,"kind":"fairing","overlay":true,"desc_he":"חופת המטען של שביט 2 עוטפת לא רק את הלוויין אלא את השלב השלישי כולו: מתחת למעטפת החלקה מסתתרים גם המנוע הכדורי וגם הלוויין המקופל, פרט שרואים יפה בשרטוטי החתך של המשגר. החופה, באורך של בערך 4.4 מטרים ובקוטר 1.35 מטרים, בנויה משתי קליפות מחומרים מרוכבים. תפקידה להגן על הלוויין הרגיש מפני זרם האוויר, מפני הרעש האקוסטי העז של השיגור ומפני החימום בזמן הטיפוס דרך האטמוספירה. ברגע שהמשגר מגיע לגובה שבו האוויר דליל דיו, מטענים פירוטכניים מנתקים את שתי הקליפות והן נפתחות הצידה כמו שתי מחציות של קליפת בוטן. ההשלה המוקדמת חיונית: בשיגור נסיגתי, שבו כל קילוגרם יקר במיוחד, אסור לגרור משקל מת עד למסלול.","facts":[{"label_he":"אורך","value":"בערך 4.4 מטרים"},{"label_he":"קוטר","value":"1.35 מטר"},{"label_he":"מבנה","value":"שתי קליפות מחומרים מרוכבים"}]}],"fun_facts_he":["ישראל היא המדינה היחידה בעולם שמשגרת לוויינים נגד כיוון סיבוב כדור הארץ. שיגור מזרחה מעל מדינות שכנות אינו אפשרי, ולכן שביט טס מערבה מעל הים התיכון. המחיר כבד: אובדן של קרוב לשליש מכושר הנשיאה, כאילו המשגר מוותר מראש על עוד 100 קילוגרמים של לוויין.","כששוגר Ofeq 1 בספטמבר 1988 הפכה ישראל למדינה השמינית בעולם ששיגרה לוויין במשגר מתוצרתה, והקטנה ביותר ברשימה בהפרש עצום.","שביט נולד מתוך תוכנית הטילים הבליסטיים יריחו: שני השלבים הראשונים הם קרובי משפחה ישירים של הטיל יריחו 2, ולכן חלק גדול מהמפרט המדויק של המשגר חסוי עד היום, והמספרים הפומביים הם שחזורים והערכות.","שיגור Ofeq 19 בליל 2 בספטמבר 2025 גרם לבהלה קצרה במרכז הארץ: תושבים שראו את שובל האש בשמי הלילה היו בטוחים שמדובר ביירוט טילים, עד שמשרד הביטחון הבהיר שמדובר בשיגור לוויין מתוכנן.","השלב השלישי והלוויין מסוחררים סביב צירם לפני הבעירה האחרונה, בדיוק כמו קליע רובה, וכך שומרים על כיוון מדויק בחלל בלי שום מנוע היגוי, אחרי שתא האוויוניקה כולו כבר הושלך כדי לחסוך משקל."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('sls', '{"slug":"sls","name_en":"SLS Block 1","name_he":"רקטת SLS Block 1","company_slug":"nasa","status_he":"פעיל: שתי טיסות ושתי הצלחות. Artemis I ללא צוות בנובמבר 2022, Artemis II המאוישת באפריל 2026. המשימה הבאה, Artemis III, מתוכננת לא לפני 2027.","intro_he":"Space Launch System, או בקיצור SLS, היא רקטת הירח הכבדה של NASA והמשגר החזק ביותר שנשא בני אדם אי פעם. בתצורת Block 1 הנוכחית היא מתנשאת לגובה 98 מטרים, בערך כמו בניין של 32 קומות, ומשקלה בשיגור עולה על 2,600 טונות. הרקטה בנויה משלב מרכזי כתום עם ארבעה מנועי RS-25 ותיקים ממעבורות החלל, שני מאיצי דלק מוצק ענקיים שמספקים את רוב דחף ההמראה, שלב עליון קטן ומדויק בשם ICPS, ובראש המגדל חללית Orion עם מגדל מילוט. ברגע ההמראה נוצר דחף של 39,100 קילוניוטון, יותר מזה של Saturn V ההיסטורית מתוכנית Apollo.\n\nSLS היא עמוד השדרה של תוכנית Artemis, המאמץ האמריקאי להחזיר בני אדם אל הירח. בטיסת הבכורה Artemis I בנובמבר 2022 היא שלחה את Orion ריקה מאדם סביב הירח, ובאפריל 2026 הגיעה שעתה הגדולה: Artemis II, הטיסה המאוישת הראשונה סביב הירח מאז 1972. ארבעת אנשי הצוות הגיעו למרחק העולה על 406 אלף ק\"מ מכדור הארץ, רחוק יותר מכל אדם בהיסטוריה, וחזרו בשלום אחרי עשרה ימים. הרקטה של Artemis III כבר נבנית: מנועיה הותקנו בשלב המרכזי באוגוסט 2026. עתידה הרחוק של התוכנית עדיין נדון בוושינגטון, אבל נכון להיום SLS היא הדרך היחידה המוכחת לשגר בני אדם אל הירח.","dims":{"height_m":98.1,"diameter_m":8.4,"mass_t":2608,"payload_leo_t":95,"thrust_liftoff_kn":39100,"stages":2,"first_flight":"2022-11-16","flights":"2 טיסות, 2 הצלחות: Artemis I בנובמבר 2022, Artemis II באפריל 2026 (נכון לספטמבר 2026)"},"sections":[{"id":"engine-section","name_he":"מקטע המנועים","name_en":"Engine Section (4x RS-25)","from_m":0,"to_m":6.7,"kind":"engines","desc_he":"המקטע התחתון של השלב המרכזי הוא החלק המורכב ביותר בכל הרקטה: צפופים בו צנרת דלק, מערכות הידראוליות, חיווט ומחשבים שמזינים ארבעה מנועי RS-25. המנועים האלה הם ותיקי מעבורת החלל: אלה ממש אותם מנועים פיזיים שטסו לחלל וחזרו, עברו שיפוץ והותקנו על SLS. כל מנוע שורף מימן נוזלי וחמצן נוזלי במחזור בעירה מדורגת, שבו טורבו משאבות דוחסות את הדלק בלחץ אדיר לפני ההצתה. כל מנוע מפיק 1,860 קילוניוטון בגובה פני הים, ובריק הדחף עולה עד 2,280 קילוניוטון. הרביעייה עובדת בערך 8 דקות רצופות, עד לניתוק השלב בדרך למסלול. כל מנוע יודע להטות את עצמו בעזרת בוכנות הידראוליות כדי להגות את הרקטה, כמו רוכב אופניים שמאזן את עצמו בתנועות קטנות ומהירות.","engine":{"name":"RS-25","count":4,"layout":"cluster4","cycle_he":"בעירה מדורגת עשירה בדלק","propellant_he":"מימן נוזלי וחמצן נוזלי","isp_s":452,"thrust_kn_each":1860},"facts":[{"label_he":"דחף לכל מנוע בגובה פני הים","value":"1,860 קילוניוטון"},{"label_he":"דחף לכל מנוע בריק","value":"2,280 קילוניוטון"},{"label_he":"זמן בעירה","value":"בערך 480 שניות"},{"label_he":"אורך כל מנוע","value":"4.3 מטרים"}]},{"id":"lh2-tank","name_he":"מכל המימן הנוזלי","name_en":"Liquid Hydrogen Tank","from_m":6.7,"to_m":44.2,"kind":"tank_fuel","desc_he":"מכל המימן הנוזלי הוא הרכיב הגדול ביותר ברקטה כולה: צינור אלומיניום באורך של כמעט 40 מטרים שמכיל בערך 2 מיליון ליטרים של מימן נוזלי בטמפרטורה של מינוס 253 מעלות צלזיוס, קרוב מאוד לאפס המוחלט. לשם השוואה, בריכה אולימפית מכילה בערך 2.5 מיליון ליטרים. המימן קל להפליא: כל הכמות העצומה הזאת שוקלת רק 144 טונות. המכל מורכב מחמש חוליות אלומיניום שחוברו בריתוך בערבול חיכוך, טכניקה שמחברת מתכות בלי להתיך אותן, והדפנות מחוזקות מבפנים ברשת צלעות שמאפשרת להן להישאר דקות וקלות. הצבע הכתום המפורסם הוא בכלל שכבת בידוד מוקצפת שמונעת מהמימן הקפוא לרתוח בשמש של פלורידה, בדיוק כמו במכל החיצוני הכתום של מעבורת החלל.","facts":[{"label_he":"נפח","value":"בערך 2 מיליון ליטרים"},{"label_he":"משקל הדלק","value":"144 טונות"},{"label_he":"טמפרטורה","value":"מינוס 253 מעלות צלזיוס"},{"label_he":"אורך המכל המלא","value":"39.6 מטרים"}]},{"id":"intertank","name_he":"חוליית הביניים","name_en":"Intertank","from_m":44.2,"to_m":50.9,"kind":"thrust_structure","desc_he":"חוליית הביניים מחברת בין מכל המימן הענק שמתחתיה למכל החמצן שמעליה, אבל התפקיד האמיתי שלה שרירי הרבה יותר: זאת הנקודה שדרכה שני מאיצי הדלק המוצק דוחפים את הרקטה כולה. עיקר הדחף של המאיצים עובר דרך נקודות העיגון הקדמיות שלהם, המחוברות בדיוק כאן, ולכן זהו החלק שסופג את העומסים הגדולים ביותר בכל הטיסה. בניגוד למכלים המרותכים, החוליה הזאת מורכבת מפאנלים מחוזקים המחוברים בברגים, כמו שלד פלדה של גשר, כדי לעמוד בכוחות האדירים בלי להתעוות. אפשר לדמות אותה לידית שדרכה שני סבלים ענקיים מרימים ארגז כבד: כל הכוח עובר דרך נקודת אחיזה אחת מחוזקת. בנוסף שוכנים בתוכה ארונות אלקטרוניקה של מערכות הטיסה, מוגנים מהקור של שני המכלים השכנים.","facts":[{"label_he":"גובה","value":"6.7 מטרים"},{"label_he":"תפקיד מבני","value":"נקודת העברת הדחף מהמאיצים"},{"label_he":"מבנה","value":"פאנלים מוברגים, לא ריתוך"}]},{"id":"lox-tank","name_he":"מכל החמצן הנוזלי","name_en":"Liquid Oxygen Tank","from_m":50.9,"to_m":61.4,"kind":"tank_ox","desc_he":"מכל החמצן הנוזלי מכיל בערך 742 אלף ליטרים של חמצן בטמפרטורה של מינוס 183 מעלות צלזיוס. בניגוד למימן הקליל, החמצן כבד מאוד: 840 טונות, רוב משקל הדלק של השלב המרכזי כולו. החמצן הוא המחמצן, החומר שמאפשר למימן לבעור, כי בגבהים שאליהם מטפסת הרקטה אין מספיק אוויר. המכל בנוי משתי חוליות אלומיניום ושתי כיפות, ואורכו המלא 15.5 מטרים, אבל חלק ממנו שקוע בתוך החוליות השכנות ולכן נראה קצר יותר מבחוץ. מהמכל יורדים שני צינורות הזנה עבים לאורך דופן הרקטה, שמזרימים אל ארבעת המנועים כמעט 2 טונות של חמצן בכל שנייה. היחס מכוון בקפידה: על כל קילוגרם מימן נשרפים בערך 6 קילוגרמים של חמצן, והתוצר שנפלט מהנחירים הוא בעיקר אדי מים.","facts":[{"label_he":"נפח","value":"742 אלף ליטרים"},{"label_he":"משקל החמצן","value":"840 טונות"},{"label_he":"טמפרטורה","value":"מינוס 183 מעלות צלזיוס"},{"label_he":"אורך המכל המלא","value":"15.5 מטרים"}]},{"id":"forward-skirt","name_he":"החצאית הקדמית ומחשבי הטיסה","name_en":"Forward Skirt (Avionics)","from_m":61.4,"to_m":64.6,"kind":"avionics","desc_he":"החצאית הקדמית היא המוח של השלב המרכזי: גליל קצר בגובה 3.2 מטרים שבו יושבים שלושת מחשבי הטיסה של הרקטה. המחשבים עובדים בשיטת הצבעה: כל אחד מחשב בנפרד את אותן פקודות, ואם אחד טועה, שני האחרים גוברים עליו, בדומה לשלושה טייסים שמצביעים על כל החלטה. כאן נמצאות גם מערכות הניווט שמודדות תאוצה וסיבוב אלפי פעמים בשנייה, מערכות התקשורת שמשדרות נתונים לתחנות הקרקע, ומצלמות שמתעדות את הטיסה. החצאית נושאת גם את החיבור הפיזי אל מתאם השלבים שמעליה, כלומר כל משקל החלק העליון של הרקטה, כולל החללית והצוות, עובר דרכה. המבנה קל יחסית, אבל הוא מתוכנן לשאת עומסים של מאות טונות בזמן שהרקטה מאיצה ורועדת.","facts":[{"label_he":"מחשבי טיסה","value":"3 מחשבים בהצבעה הדדית"},{"label_he":"גובה","value":"3.2 מטרים"}]},{"id":"lvsa","name_he":"מתאם השלבים LVSA","name_en":"Launch Vehicle Stage Adapter","from_m":64.6,"to_m":73,"kind":"interstage","desc_he":"מתאם השלבים הוא חרוט המעבר בין השלב המרכזי הרחב, בקוטר 8.4 מטרים, לשלב העליון הצר בקוטר 5.1 מטרים. הוא נראה כמו רכיב פשוט, מעין אהיל ענק מאלומיניום, אבל הוא מסתיר בתוכו הפתעה: כל חלקו התחתון של השלב העליון, כולל מכל החמצן שלו ונחיר מנוע RL10, מקופל בתוך החרוט הזה. בזמן ההפרדה מתנתק המתאם יחד עם השלב המרכזי באמצעות טבעת פירוטכנית שמתנפצת בפקודה, והשלב העליון נחשף ומצית את מנועו בחלל. המתאם, שמשקלו בערך 4.5 טונות, נבנה עבור מרכז טיסות החלל Marshall של NASA. הוא סופג את הרעידות והעומסים של שלב ההאצה, ולכן דפנותיו עבות יחסית למרות שאין בו כמעט מערכות פעילות.","facts":[{"label_he":"קוטר","value":"8.4 מטרים בבסיס, 5.1 מטרים בראש"},{"label_he":"גובה","value":"8.4 מטרים"},{"label_he":"משקל","value":"בערך 4.5 טונות"}]},{"id":"icps","name_he":"השלב העליון ICPS","name_en":"Interim Cryogenic Propulsion Stage","from_m":73,"to_m":77.3,"kind":"kick_stage","desc_he":"השלב העליון של Block 1, בשם ICPS, הוא שלב שני מוכר ובדוק: גרסה מוסבת של השלב העליון של רקטת Delta IV מתוצרת ULA. אורכו המלא 13.7 מטרים, אבל מבחוץ רואים רק את חלקו העליון, מכל המימן בקוטר 5.1 מטרים, כי השאר שקוע בתוך המתאם שמתחתיו. הוא נושא בערך 27 טונות של מימן וחמצן נוזליים, ומניע אותו מנוע RL10 יחיד במחזור אקספנדר: המימן הקר מתחמם בדפנות הנחיר, מתפשט, ומסובב בעצמו את המשאבות בלי בעירה נוספת. הדחף צנוע, 110 קילוניוטון בלבד, אבל היעילות מהגבוהות שיש. אחרי שהשלב המרכזי מסיים את ההרמה הכבדה, המנוע הקטן הזה עושה את העבודה העדינה, כמו גוררת נמל שמכוונת אונייה ענקית: בטיסת Artemis II הוא הרים את שיא המסלול לגובה של בערך 70 אלף ק\"מ.","engine":{"name":"RL10C-2","count":1,"layout":"single","cycle_he":"מחזור אקספנדר (הנעת המשאבות בהתפשטות מימן חם)","propellant_he":"מימן נוזלי וחמצן נוזלי","isp_s":461,"thrust_kn_each":110},"facts":[{"label_he":"אורך מלא","value":"13.7 מטרים"},{"label_he":"דלק","value":"בערך 27 טונות"},{"label_he":"דחף","value":"110 קילוניוטון"},{"label_he":"דחף סגולי","value":"461 שניות"}]},{"id":"osa","name_he":"מתאם Orion","name_en":"Orion Stage Adapter","from_m":77.3,"to_m":78.8,"kind":"interstage","desc_he":"טבעת נמוכה, רק מטר וחצי גובה, שמחברת את ראש השלב העליון אל חלליתה של תוכנית Artemis, חללית Orion. בתוך הטבעת מותקנת מחיצה אטומה שמפרידה בין החללית המאוישת לבין אדי המימן של השלב שמתחת, שכבת ביטחון פשוטה וחכמה. למרות גודלה הצנוע, בטיסת Artemis I היא שימשה גם תא מטען זעיר: עשרה לווייני מחקר בגודל קופסת נעליים שוחררו ממנה אל החלל אחרי שהחללית התרחקה, כמו טרמפיסטים שיורדים בתחנה האחרונה. בטיסה המאוישת Artemis II טסה הטבעת בלי לוויינים. המבנה, מאלומיניום קל, שוקל בערך 800 ק\"ג בלבד, והוא נבנה על ידי אותו צוות שבנה את מתאם השלבים הגדול. זהו הרכיב האחרון של המשגר עצמו: כל מה שמעליו הוא כבר החללית.","facts":[{"label_he":"גובה","value":"1.5 מטרים"},{"label_he":"משקל","value":"בערך 800 ק\"ג"},{"label_he":"מטען בטיסת Artemis I","value":"10 לוויינים זעירים"}]},{"id":"esm","name_he":"מודול השירות האירופי של Orion","name_en":"Orion European Service Module","from_m":78.8,"to_m":83.6,"kind":"service_module","desc_he":"מודול השירות האירופי, תרומתה של סוכנות החלל האירופית ומעשה ידיה של Airbus בגרמניה, הוא חדר המכונות של Orion: הוא מספק לקפסולה חשמל, מים, חמצן, בקרת טמפרטורה והנעה, כמו קרוואן שגורר את חדר המגורים ומזין אותו בכל מה שצריך. ארבע כנפיים סולאריות במוטה של בערך 19 מטרים מייצרות את החשמל, ומנוע ראשי מדגם AJ10 עם דחף של בערך 26 קילוניוטון, ותיק ממעבורות החלל, מבצע את התמרונים הגדולים. סביבו פרוסים עוד 32 מנועונים קטנים לתיקוני כיוון עדינים. המודול נושא בערך 8.6 טונות של דלק, ומשקלו הכולל בערך 14 טונות. בשיגור הוא עטוף בשלושה פאנלים מגינים שנזרקים בדרך לחלל. רגע לפני החזרה לאטמוספירה המודול ננטש ונשרף, ורק הקפסולה חוזרת הביתה.","engine":{"name":"AJ10 (OMS-E)","count":1,"layout":"single","cycle_he":"הזנה בלחץ, דלק היפרגולי שנדלק במגע","propellant_he":"MMH עם מחמצן MON","isp_s":316,"thrust_kn_each":26.7},"facts":[{"label_he":"מנועים","value":"33 בסך הכול"},{"label_he":"מוטת הכנפיים הסולאריות","value":"בערך 19 מטרים"},{"label_he":"דלק","value":"בערך 8.6 טונות"},{"label_he":"משקל כולל","value":"בערך 14 טונות"}]},{"id":"crew-module","name_he":"קפסולת הצוות של Orion","name_en":"Orion Crew Module","from_m":83.6,"to_m":87.3,"kind":"capsule","desc_he":"קפסולת הצוות היא הלב של כל המגדל הזה: תא בקוטר 5 מטרים עם נפח מחיה של בערך 9 מטרים מעוקבים לארבעה אסטרונאוטים, במשימות של עד 21 ימים. בטיסת Artemis II באפריל 2026 גרו כאן ארבעה אנשים במשך עשרה ימים בדרך אל הירח ובחזרה. הקפסולה היא החלק היחיד בכל הרקטה שחוזר לכדור הארץ: היא נכנסת לאטמוספירה במהירות של בערך 40 אלף קמ\"ש, ומגן החום שלה, המצופה חומר בשם Avcoat שמתכלה בהדרגה וסוחף איתו את החום, סופג טמפרטורות של בערך 2,800 מעלות צלזיוס, בערך מחצית מהחום על פני השמש. אחרי הבלימה באוויר נפרשים 11 מצנחים בזה אחר זה, והפגישה עם האוקיינוס נעשית במהירות של בערך 30 קמ\"ש בלבד. משקל הקפסולה בערך 9.4 טונות.","facts":[{"label_he":"קוטר","value":"5 מטרים"},{"label_he":"צוות","value":"עד 4 אסטרונאוטים"},{"label_he":"מהירות כניסה לאטמוספירה","value":"בערך 40,000 קמ\"ש"},{"label_he":"משקל","value":"9.4 טונות"}]},{"id":"las","name_he":"מגדל המילוט","name_en":"Launch Abort System","from_m":87.3,"to_m":98.1,"kind":"escape_tower","desc_he":"מגדל המילוט הוא כיסא המפלט של החללית: צריח דק בראש הרקטה שתפקידו לחטוף את הקפסולה והצוות הרחק מהמשגר בשבריר שנייה אם משהו משתבש. מנוע החירום המוצק שלו מפיק 1,780 קילוניוטון, כמעט פי 16 מדחף השלב העליון כולו, ומסוגל להאיץ את הקפסולה מאפס עד 640 קמ\"ש בתוך שתי שניות, בתאוצה הגדולה בערך פי 7 מכוח הכבידה. שני מנועים נוספים משלימים אותו: מנוע היגוי בחרטום שמכוון את מסלול הבריחה, ומנוע ניתוק שמרחיק את המגדל מהקפסולה לפני פריסת המצנחים. המעטפת החרוטית בבסיסו עוטפת את הקפסולה ומגינה עליה מרעש ומחום בשיגור. בטיסה תקינה המגדל ננטש בערך שלוש וחצי דקות אחרי ההמראה, ברגע שהגובה כבר מאפשר מילוט בטוח בלעדיו, וכך נחסך משקל. משקלו בערך 7.3 טונות.","facts":[{"label_he":"דחף מנוע החירום","value":"1,780 קילוניוטון"},{"label_he":"האצה","value":"מאפס עד 640 קמ\"ש בשתי שניות"},{"label_he":"מנועים","value":"3: חירום, היגוי, ניתוק"},{"label_he":"משקל","value":"בערך 7.3 טונות"}]},{"id":"srb","name_he":"מאיצי הדלק המוצק","name_en":"Five Segment Solid Rocket Boosters","from_m":0,"to_m":54,"kind":"srb","overlay":true,"desc_he":"שני מאיצי הדלק המוצק הם מנועי הרקטה המוצקים הגדולים שטסו אי פעם: כל אחד גבוה כמעט 54 מטרים, שוקל 726 טונות ומפיק דחף של 16,000 קילוניוטון. יחד הם מספקים כמעט שלושה רבעים מדחף ההמראה, ושורפים בערך 10 טונות דלק בכל שנייה. הדלק הוא תערובת מוצקה בשם PBAN, בעיקר אבקת אלומיניום ואמוניום פרכלורט, שיצוקה בתוך חמישה מקטעי פלדה, מקטע אחד יותר מגרסת מעבורת החלל, לתוספת עוצמה. מנוע מוצק הוא כמו זיקוק ענק: אחרי ההצתה אי אפשר לכבות או לווסת אותו, והוא בוער עד שהדלק נגמר. אחרי 126 שניות המאיצים מסיימים לבעור, מתנתקים ונופלים לאוקיינוס האטלנטי. בניגוד לימי המעבורת, על SLS הם אינם נאספים לשימוש חוזר, כדי לחסוך את עלויות האיסוף והשיפוץ.","engine":{"name":"Five Segment SRB","count":2,"layout":"cluster2","cycle_he":"מנוע רקטי מוצק, בעירה רציפה ללא משאבות","propellant_he":"דלק מוצק PBAN: אבקת אלומיניום ואמוניום פרכלורט","isp_s":269,"thrust_kn_each":16000},"facts":[{"label_he":"דחף לכל מאיץ","value":"16,000 קילוניוטון"},{"label_he":"משקל כל מאיץ","value":"726 טונות"},{"label_he":"זמן בעירה","value":"126 שניות"},{"label_he":"חלקם בדחף ההמראה","value":"כמעט שלושה רבעים"}]}],"fun_facts_he":["ברגע ההמראה SLS מפיקה דחף של 39,100 קילוניוטון, יותר מכל רקטה אחרת שנשאה בני אדם אי פעם, כולל Saturn V האגדית של תוכנית Apollo.","ארבעת מנועי RS-25 של Artemis I לא היו חדשים: כולם כבר טסו לחלל על מעבורות החלל, וביחד צברו 21 טיסות לפני שהותקנו על הרקטה.","צוות Artemis II הגיע באפריל 2026 למרחק העולה על 406 אלף ק\"מ מכדור הארץ, רחוק יותר מכל בני האדם בהיסטוריה, ושבר שיא שהחזיקה Apollo 13 מאז 1970.","שני מאיצי הדלק המוצק שורפים יחד בערך 10 טונות דלק בכל שנייה, ואחרי ההצתה אי אפשר לכבות אותם עד שהדלק נגמר.","מנועי השלב המרכזי שורפים מימן וחמצן, ולכן מה שנפלט מהם הוא בעיקר אדי מים: הרקטה החזקה בעולם ממריאה על ענן של מים חמים."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('starship', '{"slug":"starship","name_en":"Starship","name_he":"Starship","company_slug":"spacex","status_he":"בטיסות ניסוי פעילות: 13 טיסות עד ספטמבר 2026, גרסת V3 טסה פעמיים, וטיסה 14, הניסיון המסלולי הראשון, מתוכננת לסוף ספטמבר 2026","intro_he":"Starship של חברת SpaceX הוא מערכת השיגור הגדולה והחזקה ביותר שנבנתה אי פעם: מגדל פלדה מבריק בגובה 124.4 מטרים, גבוה יותר מבניין של 40 קומות, שממריא על דחף של בערך 9,200 טונות, כמעט פי שלושה מהסאטורן 5 שנשא את משימות אפולו לירח. המערכת בנויה משני שלבים בקוטר 9 מטרים: הבוסטר Super Heavy עם 33 מנועי Raptor 3 בתחתיתו, והחללית Starship עם 6 מנועים נוספים מעליו. שני השלבים עשויים פלדת אל חלד, שורפים מתאן וחמצן נוזליים, ומתוכננים למשהו שאף טיל לא עשה קודם: שימוש חוזר מלא ומהיר, כשהבוסטר חוזר אל מגדל השיגור ונתפס באוויר בזרועות פלדה ענקיות שזכו לכינוי מקלות האכילה.\n\nזה הפרויקט שסביבו סובב עתיד תעשיית החלל כולה: הוא אמור להוזיל את מחיר ההגעה למסלול פי עשרות, לשגר את לווייני Starlink V3 הכבדים, לשמש כרכב הנחיתה של אסטרונאוטים על הירח בתוכנית Artemis של NASA, ובחזון הרחוק יותר, להקים יישוב על מאדים. נכון לספטמבר 2026 בוצעו 13 טיסות ניסוי מאתר Starbase שבטקסס, והבוסטר נלכד בזרועות המגדל 3 פעמים. גרסת V3 החדשה טסה פעמיים: בטיסה 13 ביולי 2026 שוגרו לראשונה 20 לווייני Starlink V3 מבצעיים, והחללית שרדה בשלמותה נחיתה רכה בים לראשונה בתולדות התוכנית. טיסה 14, שתנסה לראשונה להגיע למסלול מלא סביב כדור הארץ, מתוכננת לימים הקרובים.","dims":{"height_m":124.4,"diameter_m":9,"mass_t":5300,"payload_leo_t":100,"thrust_liftoff_kn":90600,"stages":2,"first_flight":"2023-04-20","flights":"13 טיסות ניסוי מאפריל 2023 עד יולי 2026, מתוכן 8 הצלחות ושלוש לכידות בוסטר במגדל; טיסה 14, הניסיון המסלולי הראשון, מתוכננת בתאריכים 18 עד 22 בספטמבר 2026"},"sections":[{"id":"booster-engines","name_he":"מערך 33 מנועי Raptor 3","name_en":"Super Heavy Engine Section","from_m":0,"to_m":4.5,"kind":"engines","desc_he":"בתחתית הבוסטר Super Heavy יושב מערך המנועים הגדול ביותר שהוטס אי פעם על טיל אחד: 33 מנועי Raptor 3 המסודרים בשלוש טבעות, 3 במרכז, 10 סביבם ו20 בטבעת החיצונית הצמודה לדופן. 13 המנועים הפנימיים יודעים להטות את כיוון הדחף שלהם כדי להגות את הטיל, ואילו 20 החיצוניים קבועים. כל מנוע פועל במחזור בעירה מדורגת בזרימה מלאה, השיטה היעילה ביותר שקיימת: כל הדלק וכל החמצן עוברים דרך משאבות הטורבו ומגיעים לתא השריפה, כמעט ללא בזבוז. דמיינו 33 ברזי כיבוי אש שחייבים להיפתח יחד באותה שנייה בדיוק, כל אחד בלחץ פנימי של 350 בר. בזכות העמידות של Raptor 3 הוסר רוב מיגון החום שעטף את המנועים בדורות הקודמים, חיסכון של יותר מטונה לכל מנוע.","facts":[{"label_he":"מספר מנועים","value":"33"},{"label_he":"דחף לכל מנוע","value":"2,745 קילוניוטון (280 טונות)"},{"label_he":"דחף המראה כולל","value":"בערך 90,000 קילוניוטון"},{"label_he":"משקל מנוע","value":"1,525 ק\"ג"},{"label_he":"לחץ בתא השריפה","value":"350 בר"}],"engine":{"name":"Raptor 3","count":33,"layout":"ring33","cycle_he":"בעירה מדורגת בזרימה מלאה (Full Flow Staged Combustion)","propellant_he":"מתאן נוזלי וחמצן נוזלי","thrust_kn_each":2745,"isp_s":350}},{"id":"booster-thrust-structure","name_he":"מבנה הדחף","name_en":"Thrust Structure","from_m":4.5,"to_m":7,"kind":"thrust_structure","desc_he":"מעל המנועים נמצא מבנה הדחף, שלד הפלדה שתפקידו להעביר את הכוח האדיר של 33 המנועים אל גוף הטיל בלי לרסק אותו. כשכל המנועים בוערים נוצר דחף של בערך 9,200 טונות, ומבנה הדחף מפזר את העומס העצום הזה מנקודות העיגון של כל מנוע אל המעטפת הגלילית בקוטר 9 מטרים. זה עובד כמו שלד של גשר: הכוח חייב לזרום במסלולים מחושבים מראש, אחרת המתכת מתקפלת. דרך האזור הזה עוברות גם כל הצנרות הראשיות שמזרימות חמצן ומתאן אל המנועים, לצד שסתומים, מערכות הצתה וקווי לחץ. הכיפה התחתונה של מכל החמצן נשענת ישירות על המבנה, כך שהמכלים עצמם הופכים לחלק נושא עומס של הטיל, עיקרון תכנוני שחוסך מאות טונות של שלדה נפרדת.","facts":[{"label_he":"עומס מועבר","value":"בערך 9,200 טונות דחף"},{"label_he":"קוטר","value":"9 מטרים"},{"label_he":"חומר","value":"פלדת אל חלד"}]},{"id":"booster-lox-tank","name_he":"מכל החמצן הנוזלי של הבוסטר","name_en":"Booster Liquid Oxygen Tank","from_m":7,"to_m":43,"kind":"tank_ox","desc_he":"המכל הגדול ביותר בטיל כולו: בערך 2,850 טונות של חמצן נוזלי בטמפרטורה של בערך מינוס 205 מעלות צלזיוס. החמצן מקורר אל מתחת לנקודת הרתיחה שלו, קירור יתר שמכווץ אותו ומאפשר לדחוס יותר מסה לאותו נפח. מדוע החמצן למטה והדלק למעלה? החמצן כבד בהרבה מהמתאן, ומיקומו הנמוך שומר על מרכז כובד נמוך ויציב ברגעי ההמראה, כמו שק חול בתחתית סירת מפרש. דרך מרכז המכל עובר צינור ענק (Downcomer) שמוביל את המתאן מהמכל העליון היישר אל המנועים. דפנות המכל עשויות פלדת אל חלד בעובי של מילימטרים בודדים בלבד, והלחץ הפנימי הוא שמקשיח אותן, בדיוק כמו פחית שתייה סגורה שקשה למעוך אותה כל עוד היא מלאה.","facts":[{"label_he":"כמות חמצן","value":"בערך 2,850 טונות"},{"label_he":"טמפרטורה","value":"מינוס 205 מעלות צלזיוס"},{"label_he":"אורך המקטע","value":"בערך 36 מטרים"}]},{"id":"booster-ch4-tank","name_he":"מכל המתאן של הבוסטר","name_en":"Booster Liquid Methane Tank","from_m":43,"to_m":69.5,"kind":"tank_fuel","desc_he":"מכל הדלק של הבוסטר מכיל בערך 800 טונות של מתאן נוזלי שקורר עד בערך מינוס 165 מעלות צלזיוס. SpaceX בחרה במתאן ולא בקרוסין המסורתי משתי סיבות: הוא נשרף נקי כמעט בלי פיח, ולכן המנועים מוכנים לטיסה נוספת בלי ניקוי יסודי, וחשוב מכך, אפשר לייצר אותו על מאדים מקרח מים ומפחמן דו חמצני שבאטמוספירה. בין מכל המתאן למכל החמצן מפרידה כיפה משותפת אחת (Common Dome) כפולת דפנות, שחוסכת את משקלן של שתי כיפות נפרדות ומקצרת את הטיל בכמה מטרים. מראש המכל יורד צינור ההזנה הראשי, שחוצה את מכל החמצן כולו בדרכו אל 33 המנועים: קשית ענקית באורך של יותר מ40 מטרים שמזרימה טונות של דלק בכל שנייה. בגרסת V3 טבעת ההצתה החמה כבר בנויה כחלק בלתי נפרד מראש המכל הזה.","facts":[{"label_he":"כמות מתאן","value":"בערך 800 טונות"},{"label_he":"טמפרטורה","value":"בערך מינוס 165 מעלות צלזיוס"},{"label_he":"סך דלק וחמצן בבוסטר","value":"3,650 טונות"}]},{"id":"gridfins","name_he":"סנפירי סבכה","name_en":"Grid Fins","from_m":62,"to_m":66.5,"kind":"gridfins","overlay":true,"desc_he":"שלושה סנפירי סבכה ענקיים מפלדת אל חלד בולטים מצדי חלקו העליון של הבוסטר. בניגוד להגה רגיל, סנפיר סבכה בנוי כרשת של תאים קטנים, מבנה שממשיך לעבוד ביעילות גם במהירויות על קוליות, כשהבוסטר צולל חזרה דרך האטמוספירה באלפי קילומטרים בשעה. בגרסת V3 ירד מספרם מארבעה לשלושה, בפריסה של 90, 90 ו180 מעלות סביב ההיקף, וכל סנפיר גדל בכמחצית לעומת הדור הקודם, כך שסך שטח השליטה נשמר ואף גדל, עם מנגנון אחד פחות שיכול להתקלקל. הם גם הונמכו מעט כדי להרחיק אותם מהסילון הלוהט של ההצתה החמה. פיני הלכידה, הבליטות שעליהן נתפס הבוסטר בזרועות מגדל השיגור, שולבו הפעם ישירות במבנה הסנפירים. ההנעה חשמלית, פשוטה ואמינה יותר ממערכת הידראולית.","facts":[{"label_he":"מספר סנפירים","value":"3"},{"label_he":"פריסה","value":"90, 90 ו180 מעלות"},{"label_he":"גודל","value":"כמחצית יותר מסנפירי הדור הקודם"},{"label_he":"הנעה","value":"מנועים חשמליים"}]},{"id":"hot-stage-ring","name_he":"טבעת ההצתה החמה","name_en":"Hot Staging Ring (Integrated Interstage)","from_m":69.5,"to_m":72.3,"kind":"interstage","desc_he":"החלק העליון ביותר של הבוסטר הוא טבעת ההצתה החמה. כאן מתרחש אחד הרגעים הדרמטיים בטיסה: החללית מציתה את מנועיה בזמן שהיא עדיין מחוברת לבוסטר, והסילון הלוהט נפלט החוצה דרך פתחי אוורור ענקיים בדופן הטבעת. השיטה, שהושאלה מטילים רוסיים ותיקים, מבטלת את רגע איבוד התאוצה שבין ניתוק להצתה, ומוסיפה בערך עשירית לכושר הנשיאה, שיפור ששווה טונות רבות של מטען. בדורות הקודמים הטבעת הייתה חלק נפרד שהושלך לים אחרי כל שיגור כדי לחסוך משקל; בגרסת V3 היא מובנית בראש מכל המתאן, קלה יותר, ונשארת על הבוסטר לאורך כל הטיסה, צעד הכרחי בדרך לשימוש חוזר מלא. באזור הזה שוכנת גם האוויוניקה של הבוסטר: מחשבי הטיסה, הסוללות ומערכות התקשורת שמנהלות את תמרון החזרה והלכידה.","facts":[{"label_he":"תוספת ביצועים","value":"בערך עשירית מכושר הנשיאה"},{"label_he":"גובה הטבעת","value":"בערך 3 מטרים"},{"label_he":"בגרסת V3","value":"מובנית בטיל, אינה מושלכת"}]},{"id":"ship-engines","name_he":"מנועי החללית","name_en":"Ship Engine Section (3 Raptor 3 + 3 RVac)","from_m":72.3,"to_m":77,"kind":"engines","desc_he":"לחללית Starship שישה מנועי Raptor 3 בשתי קבוצות. במרכז שלושה מנועים אטמוספריים בעלי יכולת הטיה, והם שמבצעים את תמרון הנחיתה המפורסם: החללית צונחת על הבטן כמו צנחן חופשי, וברגע האחרון מציתה אותם, מזדקפת ונוחתת בעדינות על עמוד אש. סביבם שלושה מנועי Raptor Vacuum עם פעמוני פליטה ענקיים ברוחב של יותר מ2 מטרים, המותאמים לעבודה בריק של החלל: פעמון גדול מאפשר לגזים להתרחב עוד ולהפיק יותר תנע מכל קילוגרם דלק, ולכן היעילות שלהם מגיעה לבערך 380 שניות של דחף סגולי, לעומת 350 בגרסה האטמוספרית. שלושת המנועים המרכזיים חולקים קו הזנה משותף, ולכל מנוע ואקום צינור ייעודי משלו. בטיסה 13 ביולי 2026 הודגמה לראשונה הצתה חוזרת של מנוע בחלל, יכולת קריטית לחזרה ממסלול ולנחיתה על הירח.","facts":[{"label_he":"מספר מנועים","value":"6 (3 אטמוספריים, 3 ואקום)"},{"label_he":"דחף סגולי בוואקום","value":"בערך 380 שניות"},{"label_he":"קוטר פעמון מנוע ואקום","value":"בערך 2.4 מטרים"},{"label_he":"הישג בטיסה 13","value":"הצתה חוזרת בחלל"}],"engine":{"name":"Raptor 3 + Raptor Vacuum","count":6,"layout":"cluster6","cycle_he":"בעירה מדורגת בזרימה מלאה (Full Flow Staged Combustion)","propellant_he":"מתאן נוזלי וחמצן נוזלי","thrust_kn_each":2745,"isp_s":380}},{"id":"aft-flaps","name_he":"מדפים אחוריים","name_en":"Aft Flaps","from_m":72.3,"to_m":82,"kind":"flaps","overlay":true,"desc_he":"שני מדפים אחוריים גדולים יושבים בבסיס החללית, והם עובדים יחד עם שני המדפים הקדמיים כמו הידיים והרגליים של צנחן חופשי. בחזרה מהחלל Starship לא צוללת עם האף קדימה אלא נופלת שטוחה על הבטן, כשהמדפים פרושים לצדדים ובולמים את הנפילה. הטיה קטנה של כל מדף משנה את שטח ההתנגדות לאוויר ומאפשרת שליטה מדויקת בזווית ובכיוון, בלי מנועים ובלי כנפיים. המדפים מונעים במנועים חשמליים עוצמתיים שמסובבים אותם בתוך שניות גם מול עומס אווירודינמי עצום. צדם החיצוני מצופה אריחי מגן חום, מפני שהם סופגים את מלוא החום של הכניסה לאטמוספירה. ברגע תמרון ההזדקפות לפני הנחיתה המדפים נמשכים פנימה בבת אחת, והחללית עוברת מנפילה שטוחה לעמידה אנכית מעל נקודת הנחיתה.","facts":[{"label_he":"מספר מדפים","value":"2"},{"label_he":"מהירות בכניסה לאטמוספירה","value":"בערך 27,000 קמ\"ש"},{"label_he":"הנעה","value":"מנועים חשמליים"}]},{"id":"ship-lox-tank","name_he":"מכל החמצן של החללית","name_en":"Ship Liquid Oxygen Tank","from_m":77,"to_m":92,"kind":"tank_ox","desc_he":"מכל החמצן הראשי של החללית מכיל בערך 1,200 טונות של חמצן נוזלי בקירור יתר, והוא ממוקם בתחתית, קרוב למנועים. הסיבה לגודלו פשוטה: על כל קילוגרם של מתאן המנועים צורכים בערך 3.6 קילוגרמים של חמצן, ולכן מכל החמצן תמיד גדול משמעותית ממכל הדלק. במהלך העלייה למסלול המכל הענק מתרוקן בתוך דקות ספורות. לקראת הנחיתה החללית לא משתמשת בו כלל: כשהמכל כמעט ריק, מעט הנוזל שנשאר מתנדנד בין הדפנות ועלול להגיע אל המשאבות עם בועות גז, מתכון בטוח לכיבוי מנוע. לכן קיימים מכלי עזר קטנים ומלאים תמיד (Header Tanks), שמהם ניזונים המנועים בתמרון הנחיתה. זה כמו ג''ריקן רזרבי ברכב, שמור בצד ומלא עד הסוף, בדיוק לרגע שבו המכל הראשי כבר אינו אמין.","facts":[{"label_he":"כמות חמצן","value":"בערך 1,200 טונות"},{"label_he":"יחס שריפה","value":"בערך 3.6 ק\"ג חמצן לכל ק\"ג מתאן"},{"label_he":"זמן בעירה בעלייה","value":"בערך 6 דקות"}]},{"id":"ship-ch4-tank","name_he":"מכל המתאן של החללית","name_en":"Ship Liquid Methane Tank","from_m":92,"to_m":105,"kind":"tank_fuel","desc_he":"מכל המתאן של החללית מחזיק בערך 400 טונות של דלק, והוא מופרד ממכל החמצן שמתחתיו בכיפה משותפת אחת שחוסכת משקל יקר. מהמכל יורדים צינורות הזנה אל ששת המנועים: שלושת המנועים המרכזיים חולקים קו הזנה משותף, בעוד שלכל אחד ממנועי הוואקום צינור ייעודי משלו. הקירור העמוק של הדלק, עד מתחת למינוס 165 מעלות, איננו גחמה: מתאן צפוף יותר תופס פחות נפח, וכל מטר של מכל שנחסך הוא טונות של פלדה שלא צריכות להמריא. גם כאן מוטמן מכל עזר קטן למתאן עבור שלב הנחיתה. בסך הכול נושאת חללית V3 בערך 1,600 טונות של דלק וחמצן, יותר מהמשקל המלא של רוב הטילים השלמים שפועלים היום בעולם, וזה רק השלב העליון של המערכת.","facts":[{"label_he":"כמות מתאן","value":"בערך 400 טונות"},{"label_he":"סך דלק וחמצן בחללית","value":"בערך 1,600 טונות"},{"label_he":"טמפרטורת אחסון","value":"מינוס 165 מעלות ומטה"}]},{"id":"payload-bay","name_he":"תא המטען","name_en":"Payload Bay (Starlink Dispenser)","from_m":105,"to_m":117,"kind":"payload","desc_he":"תא המטען של Starship גדול מכל מה שהוטס אי פעם: בתצורת מטען מלאה מתוכנן נפח של בערך 1,000 מטרים מעוקבים, יותר מהנפח המאוכלס של תחנת החלל הבינלאומית כולה. אין כאן חרטום שנפתח ונזרק כמו ברוב הטילים; המטען יוצא דרך פתח צר בדופן שזכה לכינוי מנגנון הפז, על שם צעצוע הממתקים: לווייני Starlink V3 השטוחים נערמים זה על גבי זה כמו קלפים בחפיסה, ונדחפים החוצה אחד אחרי השני דרך החריץ, והדלת נסגרת לפני החזרה לאטמוספירה. בטיסה 13 ביולי 2026 שוגרו כך לראשונה 20 לוויינים מבצעיים אמיתיים, כל אחד במשקל של כמעט 2 טונות, ובטיסה 14 מתוכננים 26. בעתיד ישמש התא לגרסאות ייעודיות: מגורי צוות, ציוד לבסיס ירחי או מטענים בדרך למאדים.","facts":[{"label_he":"נפח מתוכנן","value":"בערך 1,000 מטרים מעוקבים"},{"label_he":"כושר נשיאה","value":"יותר מ100 טונות למסלול נמוך"},{"label_he":"שיא נוכחי","value":"20 לווייני Starlink V3 בטיסה 13"},{"label_he":"משקל כל לוויין","value":"כמעט 2 טונות"}]},{"id":"heatshield","name_he":"מגן החום","name_en":"Heatshield Tiles","from_m":72.3,"to_m":124.4,"kind":"heatshield","overlay":true,"desc_he":"כל צדה של החללית שפונה קדימה בכניסה לאטמוספירה, צד הבטן, מכוסה בשריון של בערך 18 אלף אריחים קרמיים שחורים משושים, כמו קשקשים של דג ענק. בחזרה ממסלול פוגשת החללית את האוויר במהירות של בערך 27,000 קמ\"ש, והדחיסה של האוויר מולה מציתה סביבה פלזמה בטמפרטורות שמטפסות עד 1,400 מעלות ויותר, חם מלבה געשית. הצורה המשושה אינה קישוט: היא מונעת קווים ישרים ארוכים בין האריחים, שדרכם הפלזמה הייתה יכולה לחתוך פנימה כמו סכין. מתחת לאריחים נוספה בדורות האחרונים שכבת גיבוי מתכלה, שנשרפת באופן מבוקר ומגינה על הפלדה גם אם אריח נושר. זהו האתגר ההנדסי הקשה בתוכנית כולה: מגן חום שמסוגל לטוס שוב למחרת בלי שיפוץ, דבר שאף חללית בהיסטוריה עוד לא השיגה, כולל מעבורות החלל שדרשו חודשי טיפול אחרי כל טיסה.","facts":[{"label_he":"מספר אריחים","value":"בערך 18,000"},{"label_he":"טמפרטורת שיא","value":"בערך 1,400 מעלות צלזיוס"},{"label_he":"צורה וחומר","value":"משושים קרמיים שחורים"}]},{"id":"forward-flaps","name_he":"מדפים קדמיים","name_en":"Forward Flaps","from_m":111,"to_m":120,"kind":"flaps","overlay":true,"desc_he":"שני המדפים הקדמיים קטנים מהאחוריים, והם יושבים גבוה על החרטום. הם פועלים כמו ידיו של צנחן חופשי: תזוזות קטנות שלהם מטות את האף מעלה או מטה וקובעות את זווית הגלישה של החללית בכניסה לאטמוספירה. בגרסאות הראשונות הם ישבו רחב, על קו הרוחב המרבי של החרטום, וספגו חום עז בצירים שלהם, נקודת תורפה שהתגלתה שוב ושוב בטיסות הניסוי כשפלזמה חדרה אל מנגנוני ההנעה. לכן בדור הנוכחי הם הוקטנו והוסטו אל הצד המוגן של הגוף, הרחק מזרם הפלזמה הישיר, והצירים עוצבו מחדש עם איטום משופר. זה שינוי שנראה קוסמטי בתמונות, אבל בפועל הוא ההבדל בין מדף שנאכל באוויר ובין מדף ששורד ומתפקד עד רגע ההזדקפות מעל נקודת הנחיתה.","facts":[{"label_he":"מספר מדפים","value":"2"},{"label_he":"תפקיד","value":"שליטה בזווית הגלישה בכניסה לאטמוספירה"}]},{"id":"nosecone","name_he":"חרטום ואוויוניקה","name_en":"Nosecone & Avionics","from_m":117,"to_m":124.4,"kind":"nosecone","desc_he":"קצה החרטום נראה ריק מבחוץ, אבל הוא דחוס בציוד קריטי. בתוך החוד יושב מכל העזר לחמצן נוזלי של הנחיתה: מיקומו הקיצוני מאזן את מרכז הכובד של החללית בנפילה השטוחה, כמו משקולת בקצה של חץ. סביבו נמצאות מערכות האוויוניקה הראשיות: מחשבי טיסה, סוללות, חיישני ניווט ואנטנות Starlink שמזרימות וידאו ונתונים בפס רחב אל הקרקע לאורך כל הטיסה. בגרסת V3 נוספו לחללית מתאמי עגינה חיצוניים, ההכנה למשימה הבאה בתור: תדלוק במסלול, שבו שתי חלליות Starship ייצמדו זו לזו ויעבירו מאות טונות של דלק בחלל, יכולת שאין לאף כלי טיס אחר והיא תנאי הכרחי למשימות הירח של NASA ולחזון המאדים. בגרסאות מאוישות עתידיות מיועד החלל הזה להפוך לסיפון העליון של תא הצוות.","facts":[{"label_he":"גובה המקטע","value":"בערך 7 מטרים"},{"label_he":"בפנים","value":"מכל עזר לחמצן, אוויוניקה, אנטנות Starlink"},{"label_he":"חידוש בגרסת V3","value":"מתאמי עגינה לתדלוק במסלול"}]}],"fun_facts_he":["בגובה 124.4 מטרים ובדחף המראה של בערך 9,200 טונות, Starship גבוה וחזק מכל טיל שנבנה אי פעם, כמעט פי שלושה מהסאטורן 5 של משימות אפולו.","מלא בדלק, הצמד שוקל בערך 5,300 טונות, כמו תשעה מטוסי איירבוס A380 מלאים בנוסעים ובדלק, וכל המשקל הזה מתרומם על עמוד אש של 33 מנועים.","זרועות הפלדה של מגדל השיגור, שזכו לכינוי מקלות האכילה, כבר לכדו באוויר בוסטר חוזר 3 פעמים, תמרון שנחשב בלתי אפשרי עד שבוצע לראשונה באוקטובר 2024.","מנוע Raptor 3 שוקל בערך 1.5 טונות בלבד אבל מפיק 280 טונות של דחף: יחס דחף למשקל של יותר מ180, מהגבוהים שהושגו אי פעם במנוע רקטי.","SpaceX בחרה דווקא במתאן כדלק מפני שאפשר לייצר אותו על מאדים, מקרח מים ומפחמן דו חמצני שבאטמוספירה, כך שחללית שתנחת שם תוכל לתדלק ולהמריא חזרה הביתה."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
insert into public.vehicles (slug, doc) values ('vulcan', '{"slug":"vulcan","name_en":"Vulcan Centaur","name_he":"וולקן קנטאור","company_slug":"ula","status_he":"פעיל אך מושהה זמנית: 4 טיסות, כולן הצלחות, נכון לספטמבר 2026. השיגורים הופסקו אחרי טיסת פברואר 2026 לצורך חקירת תקלה בזרבובית מאיץ מוצק, וטיסת החזרה מתוכננת עם מטען Amazon Leo לקראת סוף 2026","intro_he":"Vulcan Centaur היא רקטת השיגור הכבדה החדשה של United Launch Alliance (ULA), מיזם משותף של Boeing ושל Lockheed Martin, והיא היורשת של שתי סוסות העבודה הוותיקות Atlas V ושל Delta IV. גובהה 61.6 מטרים בתצורה הסטנדרטית (67.4 מטרים עם חרטום מטען ארוך), קוטרה אחיד, 5.4 מטרים, והיא בנויה משני שלבים: בוסטר מתאן וחמצן עם שני מנועי BE-4 של Blue Origin, ושלב עליון Centaur V מונע מימן עם שני מנועי RL10. עד שישה מאיצי דלק מוצק GEM 63XL נצמדים לבסיסה לפי הצורך, כך שהביצועים נתפרים למשימה: עד 27.2 טונות למסלול נמוך ועד 14.4 טונות למסלול העברה גאוסטציונרי.\n\nחשיבותה של Vulcan כפולה: היא הרקטה שנבחרה לשאת את המשימות הביטחוניות הרגישות ביותר של חיל החלל האמריקאי, והיא זו שסיימה את התלות של ארצות הברית במנוע הרוסי RD-180 שהניע את Atlas V. נכון לספטמבר 2026 ביצעה הרקטה 4 טיסות, כולן הצלחות, החל מטיסת הבכורה בינואר 2024 שנשאה את נחתת הירח Peregrine. עם זאת, מאז פברואר 2026 הצי מושהה: בטיסת USSF-87 נשרפה זרבובית של מאיץ מוצק בפעם השנייה בתולדות הרקטה, וחברת ULA משלימה חקירה ותיקון לקראת טיסת החזרה, שיגור ראשון של עשרות לווייני Amazon Leo בתצורת VC6L. לפני Vulcan עומד ספר הזמנות עצום: 38 שיגורים עבור Amazon לצד עשרות משימות ביטחוניות ומסחריות.","dims":{"height_m":61.6,"diameter_m":5.4,"mass_t":546.7,"payload_leo_t":27.2,"stages":2,"thrust_liftoff_kn":17100,"first_flight":"2024-01-08","flights":"4 טיסות, 4 הצלחות (נכון לספטמבר 2026), הצי מושהה מאז פברואר 2026 לחקירת תקלת מאיץ מוצק"},"sections":[{"id":"booster-engines","name_he":"מנועי BE-4 ומבנה הדחף","name_en":"BE-4 Engines & Thrust Structure","from_m":0,"to_m":4.4,"kind":"engines","desc_he":"בתחתית הבוסטר יושבים שני מנועי BE-4 של חברת Blue Origin, וכל אחד מהם מפיק כ2,400 קילוניוטון דחף בגובה פני הים, בערך כמו הדחף הכולל של שלושה מטוסי נוסעים גדולים במלוא העוצמה. המנועים שורפים מתאן נוזלי עם חמצן נוזלי במחזור בעירה מדורגת עשירה בחמצן: חלק מהתערובת נשרף תחילה בטורבינה שמניעה את המשאבות, והגזים מוזרמים בחזרה אל תא הבעירה הראשי, כך שכמעט שום אנרגיה לא מתבזבזת. שני המנועים מוטים על צירים (גימבול) כדי להגות את הרקטה, בדומה לרוכב אופניים שמטה את הכידון כדי לשמור על שיווי משקל. מבנה הדחף שמעליהם מפזר את העומס האדיר אל דפנות המכלים. טיסת הבכורה של Vulcan בינואר 2024 הייתה גם טיסת הבכורה של BE-4, המנוע שסיים את התלות האמריקאית במנוע הרוסי RD-180.","facts":[{"label_he":"דחף לכל מנוע (פני הים)","value":"כ2,400 kN"},{"label_he":"דחף כולל של הזוג","value":"כ4,800 kN"},{"label_he":"זמן בעירה","value":"כ299 שניות"},{"label_he":"דלק","value":"מתאן נוזלי וחמצן נוזלי"}],"engine":{"name":"BE-4","count":2,"layout":"cluster2","thrust_kn_each":2400,"isp_s":340,"propellant_he":"מתאן נוזלי (LNG) וחמצן נוזלי","cycle_he":"בעירה מדורגת עשירה בחמצן"}},{"id":"srb-gem63xl","name_he":"מאיצי דלק מוצק GEM 63XL","name_en":"GEM 63XL Solid Rocket Boosters","from_m":0.6,"to_m":22.5,"kind":"srb","overlay":true,"desc_he":"סביב בסיס הבוסטר אפשר להצמיד עד שישה מאיצי דלק מוצק מדגם GEM 63XL של Northrop Grumman, ומספרם (אפס, שניים, ארבעה או שישה) קובע את תצורת הרקטה ואת כוח ההרמה שלה. כל מאיץ הוא גליל קומפוזיט גרפיט אפוקסי באורך 21.9 מטרים ובקוטר 1.6 מטרים, מלא בדלק מוצק יצוק שצורתו הפנימית מכתיבה מראש את פרופיל הדחף, כמו פתיל שקצב הבעירה שלו תוכנן בשלב הייצור ואי אפשר לכבותו לאחר ההצתה. כל מאיץ מוסיף כ2,044 קילוניוטון בשיא, בוער כ90 שניות ואז מושלך אל הים. בטיסות אוקטובר 2024 ופברואר 2026 נשרפה זרבובית של אחד המאיצים בטיסה. הרקטה השלימה את המשימה בשני המקרים, אך התקלה החוזרת הובילה להשהיית כל השיגורים לצורך חקירה ותיקון, שנמשכים נכון לספטמבר 2026.","facts":[{"label_he":"אורך","value":"21.9 מטרים"},{"label_he":"קוטר","value":"1.6 מטרים"},{"label_he":"דחף שיא למאיץ","value":"כ2,044 kN"},{"label_he":"זמן בעירה","value":"כ90 שניות"},{"label_he":"מסת מאיץ","value":"כ53 טונות"}],"engine":{"name":"GEM 63XL","count":6,"layout":"ring","thrust_kn_each":2044,"isp_s":null,"propellant_he":"דלק מוצק (HTPB)","cycle_he":"מנוע רקטי מוצק"}},{"id":"booster-tank-fuel","name_he":"מכל המתאן (LNG) של הבוסטר","name_en":"Booster LNG (Methane) Tank","from_m":4.4,"to_m":16,"kind":"tank_fuel","desc_he":"מכל הדלק של הבוסטר מאחסן גז טבעי נוזלי, בעיקרו מתאן, שקורר לכמינוס 162 מעלות צלזיוס כדי להפוך לנוזל צפוף. זהו אותו גז שמשמש לבישול ביתי, רק נקי במיוחד, וכשהוא מנוזל נפחו מצטמק בערך פי 600. המכל בנוי מלוחות אלומיניום בכרסום אורתוגריד: רשת שתי וערב שמוכרסמת מתוך לוח עבה, כך שהדופן נשארת קשיחה אך קלה, כמו קרטון ביצים שמעניק חוזק עם מעט חומר. הבחירה במתאן היא פשרה חכמה: הוא צפוף בהרבה ממימן ולכן דורש מכלים קטנים יותר, הוא נשרף נקי בלי פיח שמזהם את המנועים, והוא זול וזמין. מהמכל יורדים קווי הזנה קצרים ישירות אל שני מנועי BE-4 שמתחתיו, בעוד החמצן מגיע מהמכל העליון דרך צינור חיצוני ארוך שעובר לצד המכל הזה.","facts":[{"label_he":"טמפרטורת אחסון","value":"כמינוס 162 מעלות צלזיוס"},{"label_he":"אורך המקטע","value":"כ11.6 מטרים"},{"label_he":"קוטר","value":"5.4 מטרים"},{"label_he":"מבנה","value":"אלומיניום אורתוגריד"}]},{"id":"booster-tank-ox","name_he":"מכל החמצן הנוזלי של הבוסטר","name_en":"Booster Liquid Oxygen Tank","from_m":16,"to_m":31.5,"kind":"tank_ox","desc_he":"המכל העליון והגדול מבין שני מכלי הבוסטר מכיל חמצן נוזלי בטמפרטורה של מינוס 183 מעלות צלזיוס. הוא גדול ממכל המתאן כי הבעירה דורשת בערך 3.6 קילוגרם חמצן על כל קילוגרם דלק. בין שני המכלים אין מבנה ביניים נפרד: הם חולקים מחיצה משותפת, כיפה אחת שמפרידה בין שני הנוזלים הקפואים. הפתרון הזה מקצר את הרקטה וחוסך מאות קילוגרמים של מבנה. מכיוון שהחמצן שוכן למעלה והמנועים למטה, צינור הזנה עבה יורד לאורך הדופן החיצונית של הבוסטר, ואפשר לזהות אותו בתמונות כבליטה ארוכה על הגוף. גם המכל הזה בנוי מלוחות אלומיניום בכרסום אורתוגריד עם כיפות אלומיניום מעורגלות, מבנה שנשאר יציב גם כשהמכל ריק ולא נשען על לחץ פנימי, בניגוד גמור לשלב העליון שמעליו.","facts":[{"label_he":"טמפרטורת החמצן","value":"מינוס 183 מעלות צלזיוס"},{"label_he":"יחס בעירה","value":"כ3.6 ק\"ג חמצן לכל ק\"ג מתאן"},{"label_he":"אורך המקטע","value":"כ15.5 מטרים"},{"label_he":"מחיצה","value":"מחיצה משותפת עם מכל המתאן"}]},{"id":"booster-avionics","name_he":"שלד קדמי ואוויוניקה","name_en":"Forward Skirt & Avionics","from_m":31.5,"to_m":33.3,"kind":"avionics","desc_he":"בראש הבוסטר נמצא השלד הקדמי, טבעת מבנית שסוגרת את מכל החמצן ונושאת חלק ממערכות הבקרה של השלב הראשון: מחשבי טיסה, סוללות ומערכות טלמטריה שמשדרות אלפי נתונים בשנייה אל הקרקע. מערכת האוויוניקה של Vulcan מנהלת את ההכוונה, את בקרת הטיסה ואת רצף האירועים של הטיסה כולה, מרגע ההצתה ועד שחרור המטען: היא שמחליטה מתי להטות את המנועים, מתי להשליך את המאיצים המוצקים ומתי להפריד שלבים. אפשר לחשוב עליה כטייס אוטומטי עיקש שממשיך לחשב במדויק גם בתוך רעש ורעידות אדירים. המוח הראשי של הרקטה יושב דווקא למעלה, על מדף הציוד של שלב Centaur, ואילו היחידות שכאן משרתות את הבוסטר עצמו ומעבירות פקודות למנועים ולמאיצים עד רגע ההפרדה, שבו הבוסטר מסיים את חייו הקצרים.","facts":[{"label_he":"אורך המקטע","value":"כ1.8 מטרים"},{"label_he":"תפקיד","value":"הכוונה, בקרת טיסה ורצף אירועים"},{"label_he":"קוטר","value":"5.4 מטרים"}]},{"id":"interstage","name_he":"מתאם ביניים","name_en":"Interstage Adapter","from_m":33.3,"to_m":35.4,"kind":"interstage","desc_he":"מתאם הביניים הוא גליל קומפוזיט קצר שמחבר את ראש הבוסטר אל תחתית Centaur V, ובתוכו, מוגנים מזרם האוויר ומהעומסים, מסתתרים שני מנועי RL10 העדינים של השלב העליון, כמו שעון יקר בתוך נרתיק קשיח. המבנה נושא את כל עומסי הטיסה שעוברים בין השלבים: לחץ אווירודינמי, רעידות ותאוצה שמגיעה לפי כמה מכוח הכבידה. כארבע וחצי דקות אחרי ההמראה, כשהבוסטר מרוקן את מכליו ומסיים את תפקידו, מערכת הפרדה פירוטכנית חותכת את הטבעת, קפיצים מרחיקים את השלבים זה מזה, ורק כשנפער מרחק בטוח מוצתים מנועי המימן של Centaur. התזמון כאן קריטי: הצתה מוקדמת מדי תפגע בבוסטר שזה עתה נפרד, ואיחור יעלה באובדן גובה ומהירות שקשה להשלים.","facts":[{"label_he":"אורך","value":"כ2.1 מטרים"},{"label_he":"קוטר","value":"5.4 מטרים"},{"label_he":"חומר","value":"קומפוזיט גרפיט אפוקסי"}]},{"id":"centaur-engines","name_he":"מנועי RL10 של השלב העליון","name_en":"Centaur RL10 Engines","from_m":35.4,"to_m":37.4,"kind":"engines","desc_he":"שני מנועי RL10C של Aerojet Rocketdyne מניעים את Centaur V. כל אחד מהם מפיק רק כ106 קילוניוטון, בערך אחד חלקי עשרים מדחף של מנוע BE-4 בודד, אבל בריק של החלל לא נדרש כוח גס אלא יעילות, ובה RL10 הוא שיאן מבצעי: דחף סגולי של 453.8 שניות, מהגבוהים שהושגו אי פעם במנוע כימי. הסוד הוא מחזור המרחיב: אין גנרטור גז ואין בעירה מקדימה. המימן הקר זורם בתעלות שבדופן הזרבובית הלוהטת, סופג את חומה ומתפשט בחדות, והגז המתפשט הוא שמסובב את המשאבות לפני שהוא נשרף בעצמו בתא הבעירה. מנוע שמונע מהחום העודף של עצמו הוא פשוט ואמין להפליא. משפחת RL10 טסה מאז 1963 וצברה יותר מ500 טיסות, והמנוע ניתן להצתות חוזרות בחלל, יכולת חיונית למשימות עם כמה מסלולים ולשיגורים ישירים למסלול גאוסטציונרי.","facts":[{"label_he":"דחף לכל מנוע","value":"כ106 kN"},{"label_he":"דחף סגולי","value":"453.8 שניות"},{"label_he":"מורשת","value":"יותר מ500 טיסות מאז 1963"},{"label_he":"יכולת","value":"הצתות חוזרות בחלל"}],"engine":{"name":"RL10C-1-1A","count":2,"layout":"cluster2","thrust_kn_each":106,"isp_s":453.8,"propellant_he":"מימן נוזלי וחמצן נוזלי","cycle_he":"מחזור מרחיב (Expander)"}},{"id":"centaur-tank-ox","name_he":"מכל החמצן של Centaur V","name_en":"Centaur V Liquid Oxygen Tank","from_m":37.4,"to_m":39.9,"kind":"tank_ox","desc_he":"החלק התחתון של מכל Centaur V מכיל חמצן נוזלי במינוס 183 מעלות צלזיוס. בניגוד לבוסטר האלומיניום הקשיח, מכלי Centaur עשויים פלדת אל חלד דקיקה, ועקרון פעולתם שונה לגמרי: הם מיוצבי לחץ. כמו פחית שתייה סגורה, הם שומרים על קשיחותם בזכות הלחץ הפנימי של הגז שבתוכם, וכך נחסך משקל מבני עצום, מה שמתורגם ישירות ליכולת לשאת מטען כבד יותר. מסורת מכלי הבלון הזו מלווה את משפחת Centaur עוד משנות השישים. מעל מכל החמצן נמצאת מחיצה משותפת כפולת דפנות שמפרידה בינו ובין מכל המימן הקר עוד יותר שמעליו, והריק שבין שתי הדפנות משמש בידוד, בדיוק כמו בתרמוס. מיקום המכל הכבד בתחתית השלב שומר על מרכז כובד נמוך ומקצר את הדרך אל המנועים שמתחתיו.","facts":[{"label_he":"חומר","value":"פלדת אל חלד מיוצבת לחץ"},{"label_he":"טמפרטורה","value":"מינוס 183 מעלות צלזיוס"},{"label_he":"קיבולת דלק כוללת של השלב","value":"כ54 טונות"}]},{"id":"centaur-tank-fuel","name_he":"מכל המימן של Centaur V","name_en":"Centaur V Liquid Hydrogen Tank","from_m":39.9,"to_m":46.1,"kind":"tank_fuel","desc_he":"מכל המימן הנוזלי תופס את רוב אורכו של Centaur V מסיבה פשוטה: מימן נוזלי הוא הדלק הקל ביותר שקיים, רק כ70 קילוגרם למטר מעוקב, פי 14 קל ממים, ולכן הוא דורש נפח עצום יחסית למשקלו. המימן נשמר במינוס 253 מעלות צלזיוס, כעשרים מעלות בלבד מעל האפס המוחלט, והמכל מצופה בבידוד קצף מותז (SOFI) שמאט את התאדותו במהלך שהות ארוכה בחלל. גם כאן הדופן היא פלדת אל חלד דקה מיוצבת לחץ, בהמשך אחד עם מכל החמצן שמתחת, דרך המחיצה המשותפת. השילוב של מימן וחמצן מעניק לשלב את היעילות הגבוהה ביותר שיש, ולכן Centaur V מצטיין במשימות אנרגיה גבוהה: הזרקות ישירות למסלול גאוסטציונרי, לירח ולכוכבי לכת. הוא נושא כ54 טונות דלק וחמצן, בערך פי שניים וחצי מקודמו שטס על גבי Atlas V.","facts":[{"label_he":"טמפרטורת המימן","value":"מינוס 253 מעלות צלזיוס"},{"label_he":"צפיפות מימן נוזלי","value":"כ70 ק\"ג למטר מעוקב"},{"label_he":"אורך השלב כולו","value":"11.7 מטרים"},{"label_he":"בידוד","value":"קצף מותז (SOFI)"}]},{"id":"fairing","name_he":"חרטום המטען","name_en":"Payload Fairing","from_m":46.1,"to_m":61.6,"kind":"fairing","desc_he":"חרטום המטען בקוטר 5.4 מטרים בנוי כסנדוויץ'' קומפוזיטי: ליבת חלת דבש מאלומיניום מאוורר בין לוחות גרפיט אפוקסי, שילוב קל וקשיח כמו גלשן גלים איכותי. הוא מגן על הלוויין מפני חיכוך האוויר, מפני הרעש האדיר של השיגור (פאנלים אקוסטיים מרפדים אותו מבפנים) ומפני לכלוך, ונפתח לשני חצאים בעזרת מפרקים שבירים ללא רסיסים כשהרקטה כבר מעל האטמוספרה הצפופה. Vulcan מציעה שתי גרסאות: סטנדרטית באורך 15.5 מטרים וארוכה באורך 21.3 מטרים, שמרימה את גובה הרקטה כולה ל67.4 מטרים. בתוך החרטום, מתאם המטען מחבר את הלוויין אל ראש השלב העליון, ובתצורת ריבוי לוויינים, כמו בשיגורי Amazon Leo המתוכננים, מתקן שיגור מרובה משחרר עשרות לוויינים בזה אחר זה, כל אחד בכיוון ובתזמון משלו.","facts":[{"label_he":"אורך סטנדרטי","value":"15.5 מטרים"},{"label_he":"אורך בגרסה הארוכה","value":"21.3 מטרים"},{"label_he":"קוטר","value":"5.4 מטרים"},{"label_he":"מבנה","value":"חלת דבש אלומיניום עם גרפיט אפוקסי"}]}],"fun_facts_he":["טיסת הבכורה של Vulcan, ב8 בינואר 2024, הייתה גם הטיסה הראשונה אי פעם של מנוע BE-4, וגם נשאה את Peregrine, נחתת הירח הפרטית האמריקאית הראשונה ששוגרה.","ULA קונה את מנועי השלב הראשון שלה מהמתחרה הישירה: Blue Origin מייצרת את BE-4 גם עבור הרקטה שלה עצמה, New Glenn, שמשתמשת בשבעה מנועים כאלה.","שלב Centaur הוא שושלת בת יותר מ60 שנה: הוא היה השלב הראשון בעולם שהונע במימן נוזלי, עוד ב1963, ודור Centaur V הוא הגלגול הגדול והחזק ביותר שלה אי פעם.","פעמיים, באוקטובר 2024 ובפברואר 2026, נשרפה זרבובית של מאיץ מוצק באמצע הטיסה, ובשני המקרים הרקטה בכל זאת הגיעה למסלול מדויק בזכות עודפי ביצוע ופיצוי אוטומטי של מערכת ההיגוי.","מכלי Centaur V עשויים פלדה דקה כל כך שהם היו קורסים ללא לחץ פנימי: הם שומרים על צורתם כמו פחית שתייה סגורה, טכניקה שחוסכת טונות של משקל מבני ומגדילה את המטען המורשה."]}') on conflict (slug) do update set doc = excluded.doc, updated_at = now();
